import { Question } from "@/types";

// General Agriculture: Current affairs, schemes, modern agri-tech, history, cross-subject GK
export const generalAgricultureQuestions: Question[] = [
  { id:"gen_001", subject:"general-agriculture", question:"The headquarters of the Food and Agricultural Organization (FAO) is in:", options:["Geneva", "Rome", "Paris", "New York"], correct:1, explanation:"FAO (Food and Agriculture Organization of the United Nations) was founded in 1945 with its headquarters in Rome, Italy. It leads international efforts to defeat hunger." },
  { id:"gen_002", subject:"general-agriculture", question:"ICAR was established in:", options:["1947", "1929", "1954", "1965"], correct:1, explanation:"The Indian Council of Agricultural Research (ICAR) was established on 16 July 1929 as the Imperial Council of Agricultural Research, based on the Royal Commission on Agriculture (1928)." },
  { id:"gen_003", subject:"general-agriculture", question:"ICAR headquarters is located at:", options:["Hyderabad", "Pune", "Pusa, New Delhi", "Mumbai"], correct:2, explanation:"ICAR is headquartered at Krishi Bhavan and Pusa Campus, New Delhi. It is the apex body coordinating, guiding and managing research, education, and extension in agriculture in India." },
  { id:"gen_005", subject:"general-agriculture", question:"PJTSAU was established in the year:", options:["1972", "1988", "2016", "2014"], correct:3, explanation:"PJTSAU was established in 2014 after Telangana state was bifurcated from Andhra Pradesh. It was carved out of the erstwhile ANGRAU." },
  { id:"gen_006", subject:"general-agriculture", question:"Father of Green Revolution in India is:", options:["Norman Borlaug", "Dr. B.P. Pal", "Dr. M.S. Swaminathan", "Dr. Verghese Kurien"], correct:2, explanation:"Dr. M.S. Swaminathan is known as the 'Father of Green Revolution in India' for leading the introduction of HYV wheat varieties from CIMMYT (Mexico) and ushering in food self-sufficiency." },
  { id:"gen_007", subject:"general-agriculture", question:"Father of Green Revolution globally is:", options:["Dr. M.S. Swaminathan", "Dr. B.P. Pal", "Dr. Verghese Kurien", "Norman Borlaug"], correct:3, explanation:"Norman Borlaug, an American agronomist, is the 'Father of Green Revolution' globally. He developed semi-dwarf, rust-resistant high-yielding wheat at CIMMYT and won the Nobel Peace Prize in 1970." },
  { id:"gen_008", subject:"general-agriculture", question:"Father of White Revolution (Operation Flood) in India is:", options:["Dr. M.S. Swaminathan", "Sir M. Visvesvaraya", "Dr. B.P. Pal", "Dr. Verghese Kurien"], correct:3, explanation:"Dr. Verghese Kurien is the 'Father of White Revolution / Operation Flood' in India, which made India the world's largest producer of milk through Anand Pattern dairy cooperatives." },
  { id:"gen_009", subject:"general-agriculture", question:"Father of Yellow Revolution (Oilseeds) in India is:", options:["Dr. M.V. Rao", "Dr. M.S. Swaminathan", "Dr. Sam Pitroda", "Dr. K. Pratap Reddy"], correct:0, explanation:"Dr. Sam Pitroda is recognised for the Yellow Revolution (oilseeds production), although the Technology Mission on Oilseeds (1986) under Dr. M.V. Rao significantly boosted oilseeds production." },
  { id:"gen_010", subject:"general-agriculture", question:"India's National Agricultural Research System (NARS) is led by:", options:["ICAR", "FAO", "NABARD", "Ministry of Commerce"], correct:0, explanation:"The Indian Council of Agricultural Research (ICAR) leads the National Agricultural Research System (NARS), comprising 113 ICAR institutes, 75 SAUs, 731+ KVKs, and AICRP centres across India." },
  { id:"gen_011", subject:"general-agriculture", question:"The Krishi Vigyan Kendra (KVK) is at which administrative level?", options:["District", "Block", "State", "National"], correct:0, explanation:"Krishi Vigyan Kendras (KVKs) are district-level Farm Science Centres established by ICAR for technology assessment, refinement, and demonstration to bridge the lab-to-land gap in agriculture." },
  { id:"gen_012", subject:"general-agriculture", question:"Which year was declared as International Year of Millets by UN?", options:["2020", "2023", "2025", "2030"], correct:1, explanation:"The United Nations declared 2023 as the 'International Year of Millets' (IYM 2023) on a proposal by India, to promote production and consumption of nutritious millets for food security and health." },
  { id:"gen_013", subject:"general-agriculture", question:"Which year was declared as International Year of Co-operatives by UN?", options:["2025", "2020", "2023", "2012"], correct:0, explanation:"The UN declared 2025 as the 'International Year of Co-operatives' (IYC 2025) with the theme 'Co-operatives Build a Better World', recognising co-operatives' contribution to sustainable development." },
  { id:"gen_014", subject:"general-agriculture", question:"Which year was 2025 also declared by India to promote?", options:["Millets (Shree Anna)", "Pulses", "Sustainable Agriculture", "Natural Farming"], correct:0, explanation:"India is promoting millets as 'Shree Anna' under the International Year of Millets (2023) and continues with related campaigns through 2025 — focusing on global awareness of millet benefits." },
  { id:"gen_015", subject:"general-agriculture", question:"NABARD was established in:", options:["1969", "1982", "1995", "2000"], correct:1, explanation:"National Bank for Agriculture and Rural Development (NABARD) was established on 12 July 1982 with its headquarters in Mumbai, Maharashtra. It is the apex regulator for rural credit and development." },
  { id:"gen_016", subject:"general-agriculture", question:"NABARD headquarters is located at:", options:["Delhi", "Pune", "Mumbai", "Hyderabad"], correct:2, explanation:"NABARD's head office is in Mumbai (Bandra Kurla Complex). It functions as the apex regulatory body for agricultural and rural development banking in India." },
  { id:"gen_017", subject:"general-agriculture", question:"Pradhan Mantri Fasal Bima Yojana (PMFBY) provides:", options:["Loans", "Subsidies", "Crop insurance", "Seed distribution"], correct:2, explanation:"PMFBY (launched 2016) is the Government of India's flagship crop insurance scheme. It provides comprehensive insurance against crop losses due to natural calamities, pests, and diseases." },
  { id:"gen_018", subject:"general-agriculture", question:"PM-KISAN scheme provides direct income support of:", options:["₹4000/year", "₹12000/year", "₹10000/year", "₹6000/year"], correct:3, explanation:"PM-KISAN (launched February 2019) provides ₹6,000 per year income support to all landholding farmer families in 3 equal instalments of ₹2,000 each through Direct Benefit Transfer (DBT)." },
  { id:"gen_020", subject:"general-agriculture", question:"Soil Health Card scheme was launched in:", options:["2014", "2018", "2016", "2015"], correct:3, explanation:"Soil Health Card scheme was launched on 19 February 2015 by Hon'ble PM. It provides farmers with information on soil nutrient status and recommendations for appropriate fertilizer doses." },
  { id:"gen_021", subject:"general-agriculture", question:"Pradhan Mantri Krishi Sinchayee Yojana (PMKSY) is for:", options:["Insurance", "Irrigation and water management", "Fertilizers", "Seeds"], correct:1, explanation:"PMKSY (launched 2015) aims at 'Har Khet Ko Pani' (water for every field). It focuses on irrigation expansion, water-use efficiency through micro-irrigation, and per-drop more crop philosophy." },
  { id:"gen_022", subject:"general-agriculture", question:"The Largest Producer of Milk in the world is:", options:["USA", "India", "China", "New Zealand"], correct:1, explanation:"India has been the world's largest producer of milk since 1998. Annual production is over 230 million tonnes (2023-24), thanks to Operation Flood and a strong dairy cooperative network." },
  { id:"gen_023", subject:"general-agriculture", question:"India ranks 1st globally in production of:", options:["Wheat", "Pulses, Milk and Jute", "Maize", "Rice"], correct:1, explanation:"India is the world's largest producer of pulses (about 25% of world output), milk (over 23%), and jute. It is the 2nd largest producer of rice, wheat, and several other crops." },
  { id:"gen_024", subject:"general-agriculture", question:"India is the largest producer of which spice in the world?", options:["Most spices including chilli, ginger, turmeric, cumin", "Cardamom for farmers as per standard farming practices", "Black pepper in agriculture according to agricultural science principles", "Saffron under Indian conditions in the context of Indian agriculture"], correct:0, explanation:"India is the world's largest producer, consumer, and exporter of spices — especially chilli, turmeric, ginger, coriander, cumin, fenugreek, and fennel. It is called the 'Spice Bowl of the World'." },
  { id:"gen_025", subject:"general-agriculture", question:"World Food Day is celebrated on:", options:["July 1", "October 16", "June 5", "March 22"], correct:1, explanation:"World Food Day is celebrated annually on 16 October to mark the founding of FAO (1945). It raises awareness about hunger and the need to ensure food security globally." },
  { id:"gen_026", subject:"general-agriculture", question:"World Water Day is observed on:", options:["October 16", "April 22", "June 5", "March 22"], correct:3, explanation:"World Water Day is observed annually on 22 March, since 1993, to highlight the importance of fresh water and to advocate for sustainable management of water resources." },
  { id:"gen_027", subject:"general-agriculture", question:"World Environment Day is celebrated on:", options:["October 16", "April 22", "June 5", "March 22"], correct:2, explanation:"World Environment Day is celebrated on 5 June each year by United Nations Environment Programme (UNEP) since 1974, to promote environmental awareness and action." },
  { id:"gen_028", subject:"general-agriculture", question:"World Soil Day is observed on:", options:["October 5", "December 5", "November 5", "June 5"], correct:1, explanation:"World Soil Day is observed on 5 December each year, in honour of late King Bhumibol Adulyadej of Thailand, who championed soil science. The day raises awareness about soil health." },
  { id:"gen_029", subject:"general-agriculture", question:"National Farmers' Day (Kisan Diwas) is celebrated on:", options:["October 16", "August 15", "July 1", "December 23"], correct:3, explanation:"National Farmers' Day in India is celebrated on 23 December, the birth anniversary of former PM Choudhary Charan Singh, who championed the cause of farmers." },
  { id:"gen_030", subject:"general-agriculture", question:"World Food Prize 2024 was awarded to:", options:["Dr. Mariangela Hungria under Indian conditions", "Dr. M.S. Swaminathan in agriculture", "Dr. Norman Borlaug for farmers", "Dr. Geoffrey Hawtin and Dr. Cary Fowler"], correct:3, explanation:"The 2024 World Food Prize was jointly awarded to Dr. Geoffrey Hawtin (UK) and Dr. Cary Fowler (USA) for establishing the Svalbard Global Seed Vault and saving global crop biodiversity." },
  { id:"gen_031", subject:"general-agriculture", question:"World Food Prize 2025 was awarded to:", options:["Dr. Mariangela Hungria", "Dr. Geoffrey Hawtin", "Dr. Cary Fowler", "Dr. Heidi Kuhn"], correct:0, explanation:"World Food Prize 2025 was awarded to Dr. Mariangela Hungria, Brazilian microbiologist, for her work on biological nitrogen fixation through rhizobial inoculants in soybean and other crops." },
  { id:"gen_032", subject:"general-agriculture", question:"The first World Food Prize laureate was:", options:["Norman Borlaug", "Dr. M.S. Swaminathan", "Verghese Kurien", "B.P. Pal"], correct:1, explanation:"Dr. M.S. Swaminathan was the FIRST World Food Prize Laureate (1987) for his pioneering role in India's Green Revolution and contributions to global food security." },
  { id:"gen_033", subject:"general-agriculture", question:"India's first Biochar Centre of Excellence was inaugurated at:", options:["Punjab Agricultural University", "Kanha Shanti Vanam, Hyderabad", "IARI New Delhi", "NDRI Karnal"], correct:1, explanation:"India's first Biochar Centre of Excellence was inaugurated at Kanha Shanti Vanam, Hyderabad (Heartfulness Institute) — focusing on biochar production for sustainable agriculture and carbon sequestration." },
  { id:"gen_034", subject:"general-agriculture", question:"First National Co-operative University of India was established at:", options:["New Delhi", "Anand, Gujarat (IRMA premises)", "Mumbai", "Hyderabad"], correct:1, explanation:"The first National Co-operative University (Tribhuvan Sahakari Vishwavidyalaya) was established at Anand, Gujarat, near IRMA. It is dedicated to co-operative education and research." },
  { id:"gen_035", subject:"general-agriculture", question:"India's National Bank for Financing Infrastructure and Development (NaBFID) is for:", options:["Crop loans", "Microfinance", "Long-term infrastructure financing", "Subsidies"], correct:2, explanation:"NaBFID (National Bank for Financing Infrastructure and Development), established 2021, is the principal Development Finance Institution for long-term infrastructure financing in India." },
  { id:"gen_037", subject:"general-agriculture", question:"Pradhan Mantri Awas Yojana – Gramin (PMAY-G) is for:", options:["Health", "Roads", "Water", "Rural housing"], correct:3, explanation:"PMAY-G (renamed from Indira Awaas Yojana in 2016) provides assistance for construction of pucca houses to rural homeless and those in dilapidated houses, with a target of Housing for All." },
  { id:"gen_038", subject:"general-agriculture", question:"MGNREGA guarantees how many days of employment per year?", options:["50", "150", "100", "365"], correct:2, explanation:"Mahatma Gandhi National Rural Employment Guarantee Act (MGNREGA), 2005 guarantees 100 days of unskilled wage employment per year to every rural household whose adult members demand work." },
  { id:"gen_039", subject:"general-agriculture", question:"Which of these is NOT an agricultural input subsidy?", options:["GST", "Seed subsidy", "Power subsidy for irrigation", "Fertilizer subsidy"], correct:0, explanation:"GST (Goods and Services Tax) is a tax, not a subsidy. Major Indian agriculture subsidies include fertilizers (urea, P&K), seeds, electricity for irrigation, irrigation water, and farm machinery." },
  { id:"gen_040", subject:"general-agriculture", question:"Minimum Support Price (MSP) is recommended by:", options:["RBI in agriculture according to agricultural science principles", "NITI Aayog for farmers as per standard farming practices", "CACP (Commission for Agricultural Costs and Prices)", "FCI under Indian conditions in the context of Indian agriculture"], correct:2, explanation:"The Commission for Agricultural Costs and Prices (CACP), under Ministry of Agriculture, recommends MSP. The Cabinet Committee on Economic Affairs (CCEA) takes the final decision on MSP." },
  { id:"gen_041", subject:"general-agriculture", question:"Currently MSP is announced for how many crops?", options:["10", "All crops", "50", "23"], correct:3, explanation:"The Government of India announces MSP for 23 crops — 7 cereals, 5 pulses, 7 oilseeds and 4 commercial crops (cotton, jute, copra, sugarcane via FRP)." },
  { id:"gen_043", subject:"general-agriculture", question:"Buffer Stock of food grains in India is maintained by:", options:["NAFED in agriculture", "CCI for farmers", "NABARD under Indian conditions", "FCI (Food Corporation of India)"], correct:3, explanation:"FCI (Food Corporation of India), established 1965, is the nodal agency for procurement, storage, and distribution of food grains. It maintains the buffer stock for PDS and food security." },
  { id:"gen_044", subject:"general-agriculture", question:"Public Distribution System (PDS) is operated by:", options:["State Government only", "Central Government only", "RBI", "Both Centre & State"], correct:3, explanation:"PDS is jointly operated by the Centre (FCI procurement and allocation) and the State Governments (last-mile distribution through fair price shops). National Food Security Act 2013 strengthened the PDS." },
  { id:"gen_045", subject:"general-agriculture", question:"India ranks ___ in world wheat production:", options:["2nd", "1st", "3rd", "4th"], correct:0, explanation:"India is the 2nd largest producer of wheat in the world after China, with annual production around 110+ million tonnes. Major wheat-producing states: UP, Punjab, Haryana, MP, Rajasthan, Bihar." },
  { id:"gen_046", subject:"general-agriculture", question:"India ranks ___ in world rice production:", options:["1st", "3rd", "2nd", "4th"], correct:2, explanation:"India is the 2nd largest producer of rice in the world after China, with about 130+ million tonnes annually. India is also the world's largest exporter of rice (basmati and non-basmati combined)." },
  { id:"gen_047", subject:"general-agriculture", question:"The 'Father of Hybrid Rice' is:", options:["Dr. M.S. Swaminathan", "Yuan Long Ping", "Norman Borlaug", "Dr. B.P. Pal"], correct:1, explanation:"Yuan Long Ping (China) is the 'Father of Hybrid Rice'. He developed the world's first hybrid rice in 1973 using a 3-line CMS system, dramatically increasing rice productivity globally." },
  { id:"gen_048", subject:"general-agriculture", question:"India's largest producer state of cotton is:", options:["Punjab", "Maharashtra", "Gujarat", "Telangana"], correct:1, explanation:"Maharashtra is the largest cotton-producing state in India (around 25% of national production), followed by Gujarat and Telangana. Bt cotton dominates Indian cotton cultivation since 2002." },
  { id:"gen_049", subject:"general-agriculture", question:"Largest producer state of sugarcane in India is:", options:["Maharashtra", "Uttar Pradesh", "Karnataka", "Tamil Nadu"], correct:1, explanation:"Uttar Pradesh is the largest sugarcane-producing state in India (~45% of national production), followed by Maharashtra and Karnataka. UP is also the largest producer of sugar." },
  { id:"gen_050", subject:"general-agriculture", question:"The largest mango-producing state in India is:", options:["Uttar Pradesh", "Maharashtra", "Andhra Pradesh", "Telangana"], correct:0, explanation:"Uttar Pradesh is the largest mango-producing state in India (about 24% of national production). Famous varieties include Dasheri, Langra, and Chausa." },
  { id:"gen_051", subject:"general-agriculture", question:"The largest tea-producing state in India is:", options:["Assam", "West Bengal", "Kerala", "Tamil Nadu"], correct:0, explanation:"Assam is the largest tea-producing state in India, accounting for about 50% of national tea production. India is the 2nd largest producer of tea globally after China." },
  { id:"gen_052", subject:"general-agriculture", question:"The largest coffee-producing state in India is:", options:["Tamil Nadu", "Kerala", "Karnataka", "Andhra Pradesh"], correct:2, explanation:"Karnataka is the largest coffee-producing state in India (about 70% of national output), with major districts being Chikmagalur, Kodagu (Coorg), and Hassan. Both Arabica and Robusta are grown." },
  { id:"gen_053", subject:"general-agriculture", question:"Largest fish-producing state in India is:", options:["Andhra Pradesh", "Kerala", "West Bengal", "Tamil Nadu"], correct:0, explanation:"Andhra Pradesh is the largest fish-producing state in India (both inland and total fish), accounting for about 30% of national production. Krishna Godavari delta supports vast aquaculture." },
  { id:"gen_054", subject:"general-agriculture", question:"India's National Crop is officially:", options:["Wheat in agriculture", "Rice for farmers", "No officially designated 'National Crop'", "Sugarcane under Indian conditions"], correct:2, explanation:"India does not have a single officially designated 'National Crop'. However, rice is the most widely cultivated and is sometimes informally referred to as such due to its importance in Indian diet." },
  { id:"gen_055", subject:"general-agriculture", question:"Indian Council of Agricultural Research (ICAR) is under which Ministry?", options:["Education in agriculture according to agricultural science principles", "Department of Agricultural Research and Education (DARE), Ministry of Agriculture", "Science for farmers as per standard farming practices", "Commerce under Indian conditions in the context of Indian agriculture"], correct:1, explanation:"ICAR is an autonomous body functioning under the Department of Agricultural Research and Education (DARE), Ministry of Agriculture and Farmers' Welfare, Government of India." },
  { id:"gen_056", subject:"general-agriculture", question:"Indian Agricultural Research Institute (IARI) is located at:", options:["New Delhi (Pusa)", "Mumbai", "Pune", "Hyderabad"], correct:0, explanation:"IARI is located at Pusa, New Delhi. It is India's premier agricultural research and education institution. It was originally established at Pusa, Bihar in 1905 and shifted to Delhi after the 1934 earthquake." },
  { id:"gen_057", subject:"general-agriculture", question:"NIPHM (National Institute of Plant Health Management) is located at:", options:["Pusa", "Hyderabad", "Bangalore", "New Delhi"], correct:1, explanation:"NIPHM (National Institute of Plant Health Management), an institute under the Department of Agriculture & Farmers Welfare, is located in Hyderabad. It focuses on plant health, IPM, and pesticide management." },
  { id:"gen_058", subject:"general-agriculture", question:"Central Rice Research Institute (CRRI / NRRI) is at:", options:["Cuttack, Odisha", "New Delhi", "Hyderabad", "Coimbatore"], correct:0, explanation:"CRRI (now National Rice Research Institute, NRRI) is located at Cuttack, Odisha. Established in 1946, it is India's premier institute for rice research." },
  { id:"gen_059", subject:"general-agriculture", question:"Indian Institute of Pulses Research (IIPR) is at:", options:["Kanpur, UP", "Hyderabad", "Pusa", "Coimbatore"], correct:0, explanation:"IIPR (Indian Institute of Pulses Research) is located at Kanpur, Uttar Pradesh. It is the nodal ICAR institute for research on all major pulse crops in India." },
  { id:"gen_060", subject:"general-agriculture", question:"Sugarcane Breeding Institute (SBI) is located at:", options:["Cuttack", "Pune", "Coimbatore", "Nagpur"], correct:2, explanation:"Sugarcane Breeding Institute (SBI), Coimbatore, is the premier ICAR institute for sugarcane breeding in India. It has developed numerous high-yielding sugarcane varieties (Co series)." },
  { id:"gen_062", subject:"general-agriculture", question:"IRRI (International Rice Research Institute) is in:", options:["Philippines (Los Baños)", "India", "China", "Thailand"], correct:0, explanation:"IRRI is located at Los Baños, Laguna, Philippines. Established in 1960, it is the world's premier rice research institute. It developed IR-8 — the variety that triggered the rice Green Revolution." },
  { id:"gen_063", subject:"general-agriculture", question:"CIMMYT (International Maize and Wheat Improvement Center) is in:", options:["Mexico", "USA", "India", "Italy"], correct:0, explanation:"CIMMYT (Centro Internacional de Mejoramiento de Maíz y Trigo) is headquartered in Texcoco, Mexico. It was the workplace of Norman Borlaug and a key institute behind the global Green Revolution in wheat." },
  { id:"gen_064", subject:"general-agriculture", question:"The Svalbard Global Seed Vault is in:", options:["USA", "Italy", "Norway", "India"], correct:2, explanation:"Svalbard Global Seed Vault is located on Spitsbergen island, Norway, near the Arctic Circle. It is a secure backup storage for the world's crop genetic diversity, holding 1+ million samples." },
  { id:"gen_065", subject:"general-agriculture", question:"India's National Gene Bank for plant genetic resources is at:", options:["IARI New Delhi", "NBAII Bangalore", "NBPGR New Delhi", "CTCRI Trivandrum"], correct:2, explanation:"The National Gene Bank is at NBPGR (National Bureau of Plant Genetic Resources), New Delhi. It is the second largest gene bank in the world, conserving over 4.5 lakh accessions of plant genetic resources." },
  { id:"gen_066", subject:"general-agriculture", question:"India's first agricultural college was established at:", options:["Coimbatore", "Pusa", "Pune (1879)", "New Delhi"], correct:2, explanation:"The College of Agriculture, Pune (now Mahatma Phule Krishi Vidyapeeth's COA), established in 1879, was India's first agricultural college. It still serves as a premier institution in Maharashtra." },
  { id:"gen_067", subject:"general-agriculture", question:"India's first State Agricultural University was established at:", options:["Coimbatore", "Pantnagar (1960)", "Hyderabad", "Bangalore"], correct:1, explanation:"G.B. Pant University of Agriculture and Technology, Pantnagar (Uttarakhand), established in 1960, was India's first State Agricultural University, modelled after the US land-grant college system." },
  { id:"gen_068", subject:"general-agriculture", question:"The 73rd Constitutional Amendment Act, 1992 is related to:", options:["Panchayati Raj (Rural local self-government)", "Urban local bodies", "Cooperative societies", "Land reforms"], correct:0, explanation:"The 73rd Constitutional Amendment (1992) gave constitutional status to Panchayati Raj Institutions — a 3-tier system: Gram Panchayat (village), Panchayat Samiti (block), Zilla Parishad (district)." },
  { id:"gen_069", subject:"general-agriculture", question:"The 74th Constitutional Amendment is related to:", options:["Panchayati Raj", "Land", "Co-operatives", "Urban local bodies (Municipalities)"], correct:3, explanation:"The 74th Constitutional Amendment (1992) is related to urban local bodies — Nagar Panchayats, Municipal Councils, and Municipal Corporations — providing them constitutional status." },
  { id:"gen_070", subject:"general-agriculture", question:"India's National Mission for Sustainable Agriculture (NMSA) focuses on:", options:["Heavy fertilizer use", "Plantation crops", "Climate-resilient and sustainable farming", "Marine fishing"], correct:2, explanation:"NMSA (National Mission for Sustainable Agriculture), one of the 8 missions under National Action Plan on Climate Change, promotes climate-resilient agriculture through soil health, water-use efficiency, and integrated farming." },
  { id:"gen_071", subject:"general-agriculture", question:"Genome-edited Rice varieties developed by ICAR (announced 2025):", options:["DRR Dhan 100 and Pusa DST Rice 1", "IR-8 and IR-36 in agriculture", "Basmati 370 and Sona Masuri", "Pusa 1121 and Pusa 1509"], correct:0, explanation:"ICAR developed two genome-edited rice varieties using CRISPR-Cas9: DRR Dhan 100 (Kamala) — high-yielding from Samba Mahsuri, and Pusa DST Rice 1 — drought and salinity tolerant. India's first GE crop varieties." },
  { id:"gen_072", subject:"general-agriculture", question:"Bt Cotton (genetically modified) was approved in India in:", options:["1995", "2002", "2010", "2015"], correct:1, explanation:"Bt Cotton (transgenic cotton with Cry1Ac gene from Bacillus thuringiensis providing bollworm resistance) was approved for commercial cultivation in India in March 2002 by GEAC." },
  { id:"gen_074", subject:"general-agriculture", question:"India's first GM food crop approved (later withdrawn) was:", options:["Both Bt Brinjal and GM Mustard had moratoriums", "GM Mustard (DMH-11) for farmers as per standard farming practices", "Bt Brinjal in agriculture according to agricultural science principles", "Golden Rice under Indian conditions in the context of Indian agriculture"], correct:0, explanation:"Bt Brinjal got moratorium in 2010 due to public concerns. GM Mustard (DMH-11) was approved by GEAC in 2022 for environmental release but faces continuing legal challenges. No GM food crop is commercially grown in India yet." },
  { id:"gen_075", subject:"general-agriculture", question:"India's per capita arable land is approximately:", options:["1.5 ha", "0.12 ha", "0.5 ha", "2.0 ha"], correct:1, explanation:"India's per capita arable land is approximately 0.12 ha, much lower than the world average of about 0.20 ha. This emphasizes the need for productivity improvement and sustainable land use." },
  { id:"gen_076", subject:"general-agriculture", question:"The largest source of agricultural credit in India is:", options:["Commercial banks", "Cooperatives", "Money lenders", "Regional Rural Banks (RRBs)"], correct:0, explanation:"Commercial banks have become the largest source of institutional agricultural credit in India (~70%+ share), followed by Cooperatives and RRBs. Money lenders' share has declined dramatically." },
  { id:"gen_077", subject:"general-agriculture", question:"Kisan Credit Card (KCC) was launched in:", options:["1995", "2014", "2005", "1998–99"], correct:3, explanation:"Kisan Credit Card (KCC) was launched in 1998–99 (model scheme by NABARD) to provide adequate and timely short-term credit to farmers for crop production with simplified procedure." },
  { id:"gen_078", subject:"general-agriculture", question:"Largest organic farming state in India is:", options:["Karnataka for farmers", "Maharashtra in agriculture", "Madhya Pradesh", "Sikkim (first fully organic state)"], correct:3, explanation:"Sikkim became India's first fully organic state in 2016 — all its agricultural land was certified organic. Madhya Pradesh, however, has the largest area under organic certification." },
  { id:"gen_079", subject:"general-agriculture", question:"The current N:P:K consumption ratio in India is approximately:", options:["4:2:1 (ideal)", "1:1:1", "11:4:1 (actual, skewed)", "10:5:1"], correct:2, explanation:"The current N:P:K consumption ratio in India is approximately 11:4:1 — heavily skewed towards nitrogen due to subsidy structure. The agronomically ideal balanced ratio is 4:2:1." },
  { id:"gen_080", subject:"general-agriculture", question:"From which year was 100% neem coating of subsidised urea made mandatory in India?", options:["2012", "2020", "2018", "2015"], correct:3, explanation:"From 2015 (May 2015 notification), 100% of subsidised agricultural-grade urea must be neem-coated. Neem coating slows nitrogen release, improves NUE by 10–15%, and prevents diversion." },
  { id:"gen_081", subject:"general-agriculture", question:"India's first 'Genome-Edited' rice was named:", options:["Pusa Basmati", "Sona Masuri", "Kamala (DRR Dhan 100)", "IR-64"], correct:2, explanation:"DRR Dhan 100, named 'Kamala', is India's first genome-edited rice variety, developed by ICAR-IIRR using CRISPR-Cas9 technology in the background of Samba Mahsuri." },
  { id:"gen_082", subject:"general-agriculture", question:"The 'Land Pooling' scheme is associated with:", options:["Agricultural marketing in agriculture according to agricultural science principles", "Subsidies under Indian conditions in the context of Indian agriculture", "Crop insurance for farmers as per standard farming practices", "Allocation of land for projects (urban or industrial development) by pooling farmers' land"], correct:3, explanation:"Land Pooling is an alternative to land acquisition where farmers voluntarily pool their land; after development, a developed plot is returned to them. Used in Andhra Pradesh capital Amaravati and other projects." },
  { id:"gen_083", subject:"general-agriculture", question:"India's National Food Security Act was enacted in:", options:["2013", "2009", "2005", "2016"], correct:0, explanation:"The National Food Security Act (NFSA) was enacted in September 2013. It legally entitles up to 75% of rural and 50% of urban population to receive subsidized food grains under PDS." },
  { id:"gen_084", subject:"general-agriculture", question:"Pradhan Mantri Krishi Sinchayee Yojana motto is:", options:["Health for all in agriculture according to agricultural science principles", "Land for landless under Indian conditions in the context of Indian agriculture", "Jai Jawan Jai Kisan for farmers as per standard farming practices", "Har Khet Ko Pani – Per Drop More Crop"], correct:3, explanation:"PMKSY's motto is 'Har Khet Ko Pani' (water to every field) and 'Per Drop More Crop' (water-use efficiency). It promotes micro-irrigation and improved water management." },
  { id:"gen_085", subject:"general-agriculture", question:"PJTSAU recently organized a state-wide campaign 'Rythu Mungitlo Shastravethalu' (Scientists at the Farmer's Doorstep) during:", options:["October 2025", "July 2025", "May 1–5, 2025", "2024"], correct:2, explanation:"PJTSAU organized 'Rythu Mungitlo Shastravethalu' from May 1–5, 2025 — a state-wide campaign in Telangana directly connecting scientists with farmers in their villages." },
  { id:"gen_086", subject:"general-agriculture", question:"The current Director General of ICAR is:", options:["Dr. Himanshu Pathak", "Dr. Trilochan Mohapatra", "Dr. M.L. Jat", "Dr. R.S. Paroda"], correct:0, explanation:"Dr. Himanshu Pathak was appointed Director General of ICAR and Secretary, DARE in 2022. He has worked extensively on climate-resilient agriculture." },
  { id:"gen_087", subject:"general-agriculture", question:"What does ATMA (Agricultural Technology Management Agency) operate at?", options:["National level", "District level", "State level", "Block level"], correct:1, explanation:"ATMA operates at the district level. It is an autonomous body that brings together public and private extension agencies, ensuring decentralized, farmer-driven, bottom-up extension planning." },
  { id:"gen_088", subject:"general-agriculture", question:"Aspirational Districts Programme (ADP) was launched in:", options:["2014", "2022", "2020", "2018"], correct:3, explanation:"Aspirational Districts Programme was launched on 5 January 2018 by NITI Aayog to rapidly transform 117 most under-developed districts of India through health, nutrition, education, agriculture, and skill development." },
  { id:"gen_089", subject:"general-agriculture", question:"Pradhan Mantri Annadata Aay Sanrakshan Abhiyan (PM-AASHA) is for:", options:["Soil health in agriculture according to agricultural science principles", "Insurance under Indian conditions in the context of Indian agriculture", "Irrigation for farmers as per standard farming practices", "Income protection of farmers (procurement at MSP)"], correct:3, explanation:"PM-AASHA (launched 2018) is an umbrella scheme to ensure remunerative prices to farmers, with three sub-schemes: PSS (Price Support Scheme), PDPS (Price Deficiency Payment Scheme), and PPSS (Private Procurement & Stockist Scheme)." },
  { id:"gen_090", subject:"general-agriculture", question:"In Indian Agriculture, kharif season is approximately:", options:["October–March", "April–June", "June–October (monsoon-dependent)", "Throughout the year"], correct:2, explanation:"Kharif season in India is the monsoon-rain-fed cropping season, generally June to October. Sowing begins with the onset of southwest monsoon. Major kharif crops: paddy, maize, sorghum, bajra, cotton, soybean, groundnut." },
  { id:"gen_091", subject:"general-agriculture", question:"Rabi season is:", options:["June–October", "July–September", "October/November–March/April (winter)", "All year round"], correct:2, explanation:"Rabi is the winter cropping season in India, generally October/November to March/April. Sowing on residual soil moisture; harvest in spring. Major rabi crops: wheat, barley, mustard, chickpea, pea." },
  { id:"gen_092", subject:"general-agriculture", question:"Zaid season refers to:", options:["Monsoon crops in agriculture according to agricultural science principles", "Winter crops for farmers as per standard farming practices", "Summer crops grown between Rabi and Kharif (March–June)", "Perennial crops under Indian conditions in the context of Indian agriculture"], correct:2, explanation:"Zaid is the summer cropping season (March–June), between Rabi harvest and Kharif sowing. Crops are grown with assured irrigation. Major zaid crops: cucumber, watermelon, muskmelon, summer moong, sunflower." },
  { id:"gen_093", subject:"general-agriculture", question:"India's largest exported agricultural commodity by value is:", options:["Marine products and Basmati rice", "Spices for farmers", "Tea in agriculture", "Sugar under Indian conditions"], correct:0, explanation:"India's largest agricultural exports by value are Marine products (~$8 billion), Basmati rice (~$5–7 billion), Non-basmati rice, Spices, and Buffalo meat. India is the largest exporter of rice globally." },
  { id:"gen_094", subject:"general-agriculture", question:"India's highest agricultural import (by value) is:", options:["Wheat", "Edible oils", "Sugar", "Fertilizers"], correct:1, explanation:"Edible oils are India's largest agricultural import (palm oil, soybean oil, sunflower oil) — over 60% of edible oil demand is imported, making India the world's largest edible oil importer." },
  { id:"gen_095", subject:"general-agriculture", question:"Largest consumer of urea in the world is:", options:["USA", "India", "China", "Brazil"], correct:1, explanation:"India is the world's largest consumer of urea (around 35 million tonnes annually). It is also the largest producer and largest importer of urea, despite being self-sufficient in urea production." },
  { id:"gen_097", subject:"general-agriculture", question:"World Pulses Day is celebrated on:", options:["October 16", "June 5", "March 22", "February 10"], correct:3, explanation:"World Pulses Day is observed on 10 February each year, designated by the UN in 2018, to highlight the nutritional and environmental benefits of pulses in sustainable food systems." },
  { id:"gen_098", subject:"general-agriculture", question:"The first Five Year Plan in India primarily focused on:", options:["Industry", "Defence", "Service sector", "Agriculture and irrigation"], correct:3, explanation:"The First Five Year Plan (1951–56) of India was based on the Harrod-Domar model and focused primarily on agriculture and irrigation, including Bhakra Nangal and other multi-purpose river valley projects." },
  { id:"gen_099", subject:"general-agriculture", question:"AGRICET (Agriculture Common Entrance Test) is conducted by:", options:["PJTSAU (for Telangana state)", "ICAR", "SCERT", "Central Government"], correct:0, explanation:"AGRICET is the entrance test conducted by PJTSAU (Professor Jayashankar Telangana State Agricultural University) for admission of Diploma in Agriculture students into B.Sc. (Hons.) Agriculture programs in Telangana." },
  { id:"gen_100", subject:"general-agriculture", question:"Father of Modern Agriculture in India is regarded as:", options:["Norman Borlaug", "Dr. M.S. Swaminathan", "Dr. Verghese Kurien", "Sir Albert Howard"], correct:1, explanation:"Dr. M.S. Swaminathan is widely regarded as the 'Father of Modern Agriculture in India' for his transformative contributions to the Green Revolution and food self-sufficiency in India." },
  { id:"gen_101", subject:"general-agriculture", question:"The Digital Agriculture Mission, approved by the Union Cabinet in September 2024, is primarily aimed at:", options:["Providing free smartphones to every farmer", "Digitising only urban land records", "Building Digital Public Infrastructure (AgriStack) for agriculture", "Replacing agricultural extension workers with robots"], correct:2, explanation:"The Digital Agriculture Mission (approved September 2024, outlay about Rs. 2,817 crore) creates Digital Public Infrastructure for agriculture - including AgriStack (farmers' registry, crop-sown registry and geo-referenced village maps), the Krishi Decision Support System and soil profile maps." },
  { id:"gen_102", subject:"general-agriculture", question:"The National Mission on Natural Farming (NMNF), approved as a standalone scheme in November 2024, promotes:", options:["Higher use of synthetic fertilizers and pesticides", "Chemical-free farming using cow-based and on-farm inputs", "Only large-scale hydroponic cultivation", "Promotion of genetically modified crop exports"], correct:1, explanation:"NMNF was approved in November 2024 as a standalone Centrally Sponsored Scheme (outlay about Rs. 2,481 crore) under the Ministry of Agriculture, promoting chemical-free natural farming based on on-farm biomass and cow-based inputs such as Jeevamrit and Beejamrit to cut input costs and improve soil health." },
  { id:"gen_103", subject:"general-agriculture", question:"Under the 'Namo Drone Didi' scheme, agricultural drones are provided to:", options:["Large corporate agribusiness firms", "Defence and paramilitary forces", "Urban municipal bodies", "Women Self-Help Groups (SHGs)"], correct:3, explanation:"The Namo Drone Didi scheme (approved November 2023) provides drones to Women Self-Help Groups (SHGs) so they can offer rental services to farmers - such as spraying of fertilizers and pesticides - creating rural livelihoods under the 'Lakhpati Didi' initiative." },
  { id:"gen_104", subject:"general-agriculture", question:"The PM Dhan-Dhaanya Krishi Yojana, announced in the Union Budget 2025-26, focuses on developing:", options:["Only coastal fishing districts", "Metropolitan urban centres", "100 districts with low agricultural productivity", "Special economic zones for agri-exports"], correct:2, explanation:"Announced in the Union Budget 2025-26, the Prime Minister Dhan-Dhaanya Krishi Yojana aims to develop 100 districts with low agricultural productivity, moderate crop intensity and below-average credit availability, benefiting an estimated 1.7 crore farmers - modelled on the Aspirational Districts Programme." },
  { id:"gen_105", subject:"general-agriculture", question:"In the Union Budget 2025-26, the Government announced setting up a National Makhana Board in which state?", options:["Punjab", "Bihar", "Kerala", "Assam"], correct:1, explanation:"The Union Budget 2025-26 announced a Makhana Board in Bihar to improve production, processing, value addition and marketing of makhana (fox nuts). Bihar is the largest producer of makhana in India." },
  { id:"gen_r001", subject:"general-agriculture", question:"VAM (Vesicular Arbuscular Mycorrhizae) is a:", options:["Chemical fertiliser", "Fungal biofertiliser that helps in phosphorus uptake", "Bacterial biofertiliser", "Algal biofertiliser"], correct:1, explanation:"As per DA-101 notes: VAM is a fungal biofertiliser (mycorrhizal fungus) that forms association with plant roots and enhances phosphorus uptake." },
  { id:"gen_r002", subject:"general-agriculture", question:"Who is known as the 'Father of Agronomy'?", options:["Justus von Liebig", "M.S. Swaminathan", "Norman Borlaug", "Pietro de'Crescenzi"], correct:3, explanation:"Pietro de'Crescenzi of Italy (1230–1320 AD) is regarded as the Father of Agronomy for his systematic work on crop production." },
  { id:"gen_r003", subject:"general-agriculture", question:"Who is called the 'Father of Indian Agriculture'?", options:["Norman Borlaug", "N.G. Ranga", "M.S. Swaminathan", "B.P. Pal"], correct:2, explanation:"Dr. M.S. Swaminathan is widely called the Father of Indian Agriculture due to his transformative contributions to Indian farming." },
  { id:"gen_r005", subject:"general-agriculture", question:"The optimum bulk density range for most crop soils is:", options:["0.5–0.8 g/cc", "1.1–1.3 g/cc", "1.6–1.8 g/cc", "2.0–2.2 g/cc"], correct:1, explanation:"Most crops grow well in soils with bulk density of 1.1–1.3 g/cc. Above 1.6 g/cc, root penetration becomes difficult." },
  { id:"gen_r006", subject:"general-agriculture", question:"The 'Law of Minimum' was given by:", options:["C.G. Hopkins", "Blackman", "J.B. Lawes", "Justus von Liebig"], correct:3, explanation:"Justus von Liebig proposed the Law of Minimum – crop growth is limited by the nutrient in shortest supply relative to crop requirement." },
  { id:"gen_r007", subject:"general-agriculture", question:"Cyperus rotundus (purple nutsedge / nutgrass) belongs to which weed category?", options:["Grass weeds", "Sedge weeds", "Broadleaf weeds", "Aquatic weeds"], correct:1, explanation:"Cyperus rotundus (nutgrass / motha) is the most problematic sedge weed, belonging to family Cyperaceae. It is very difficult to control due to tubers." },
  { id:"gen_r008", subject:"general-agriculture", question:"The most problematic aquatic weed in rice paddies of Telangana is:", options:["Cyperus difformis", "Ageratum conyzoides", "Parthenium", "Eichhornia crassipes (water hyacinth)"], correct:0, explanation:"Cyperus difformis (flat sedge) and Echinochloa species are major paddy weeds, while Eichhornia clogs canals and reservoirs but Cyperus difformis is the key rice-paddy sedge." },
  { id:"gen_r009", subject:"general-agriculture", question:"Micro-irrigation (drip and sprinkler) is promoted under which Government scheme in India?", options:["Pradhan Mantri Krishi Sinchayee Yojana (PMKSY)", "MGNREGS under field conditions", "RKVY in agronomy under standard field conditions", "PMFBY for crop production under standard field conditions"], correct:0, explanation:"PMKSY (Pradhan Mantri Krishi Sinchayee Yojana) with 'Har Khet Ko Pani' and 'More Crop Per Drop' components promotes micro-irrigation across India." },
  { id:"gen_r010", subject:"general-agriculture", question:"The advantage of sole cropping is:", options:["Simpler management and easier mechanization", "Better resource use efficiency", "Higher LER than intercropping", "Better pest control through diversity"], correct:0, explanation:"Sole cropping (growing one crop per field) is simpler to manage, allows full mechanization, and makes pest/disease management uniform and straightforward." },
  { id:"gen_r011", subject:"general-agriculture", question:"The Harvest Index of modern high-yielding rice varieties is approximately:", options:["0.60–0.70", "0.35–0.50", "0.80–0.90", "0.2–0.3"], correct:1, explanation:"Modern HYV rice has a Harvest Index of 0.35–0.50, compared to 0.20–0.30 for traditional tall varieties. This improved HI was key to Green Revolution gains." },
  { id:"gen_r012", subject:"general-agriculture", question:"Aflatoxin contamination in stored groundnut is caused by:", options:["Aspergillus flavus", "Rhizopus stolonifer", "Claviceps purpurea", "Fusarium moniliforme"], correct:0, explanation:"Aspergillus flavus and A. parasiticus produce aflatoxins in stored groundnut, maize, and other grains, especially under high moisture (>14%) and temperature." },
  { id:"gen_r013", subject:"general-agriculture", question:"Bakanae disease of rice is caused by:", options:["Gibberella fujikuroi", "Helminthosporium oryzae", "Xanthomonas oryzae", "Pyricularia oryzae"], correct:0, explanation:"Bakanae (foolish seedling disease) is caused by the fungus Gibberella fujikuroi, which produces gibberellins." },
  { id:"gen_r014", subject:"general-agriculture", question:"Seed rate for nursery raising in transplanted rice is:", options:["25–30 kg/ha", "100 kg/ha", "5–10 kg/ha", "60–75 kg/ha"], correct:0, explanation:"25–30 kg/ha seed rate is used for raising nursery sufficient to transplant one hectare." },
  { id:"gen_r015", subject:"general-agriculture", question:"Downy mildew of maize is caused by:", options:["Fusarium moniliforme", "Colletotrichum graminicola", "Peronosclerospora sorghi", "Puccinia polysora"], correct:2, explanation:"Sorghum downy mildew (Peronosclerospora sorghi) also infects maize causing downy mildew." },
  { id:"gen_r016", subject:"general-agriculture", question:"Which maize type has the highest protein content?", options:["Flint maize", "Sweet corn", "Quality Protein Maize (QPM)", "Pop corn"], correct:2, explanation:"QPM has increased levels of lysine and tryptophan, making it superior in protein quality." },
  { id:"gen_r017", subject:"general-agriculture", question:"Ergot disease of pearl millet is caused by:", options:["Claviceps fusiformis", "Pyricularia grisea", "Sclerospora graminicola", "Puccinia substriata"], correct:0, explanation:"Ergot of pearl millet is caused by Claviceps fusiformis." },
  { id:"gen_r018", subject:"general-agriculture", question:"Shoot fly (Atherigona soccata) is a major pest of:", options:["Cotton", "Rice", "Sorghum", "Maize"], correct:2, explanation:"Shoot fly (Atherigona soccata) is a serious pest of sorghum causing dead heart." },
  { id:"gen_r019", subject:"general-agriculture", question:"Downy mildew of pearl millet is caused by:", options:["Phytophthora infestans", "Peronosclerospora sorghi", "Sclerospora graminicola", "Pythium ultimum"], correct:2, explanation:"Downy mildew (green ear disease) of pearl millet is caused by Sclerospora graminicola." },
  { id:"gen_r020", subject:"general-agriculture", question:"Groundnut belongs to the family:", options:["Solanaceae", "Poaceae", "Euphorbiaceae", "Fabaceae"], correct:3, explanation:"Groundnut (Arachis hypogaea) belongs to the family Fabaceae (Leguminosae)." },
  { id:"gen_r021", subject:"general-agriculture", question:"Tikka disease of groundnut is caused by:", options:["Puccinia arachidis under standard field conditions", "Sclerotium rolfsii under standard field conditions", "Aspergillus flavus under standard field conditions", "Cercospora arachidicola & C. personatum"], correct:3, explanation:"Early leaf spot (C. arachidicola) and late leaf spot (C. personatum) together cause Tikka disease." },
  { id:"gen_r022", subject:"general-agriculture", question:"Which micronutrient is critical for groundnut pod filling?", options:["Boron", "Calcium", "Iron", "Zinc"], correct:1, explanation:"Calcium is essential for pod development and preventing peg rot in groundnut." },
  { id:"gen_r023", subject:"general-agriculture", question:"TMV-2 is a popular variety of:", options:["Castor", "Soybean", "Sunflower", "Groundnut"], correct:3, explanation:"TMV-2 is a well-known groundnut variety." },
  { id:"gen_r024", subject:"general-agriculture", question:"Aflatoxin contamination in groundnut is caused by:", options:["Fusarium moniliforme", "Penicillium digitatum", "Aspergillus flavus", "Rhizopus stolonifer"], correct:2, explanation:"Aspergillus flavus produces aflatoxins in groundnut, causing health hazards." },
  { id:"gen_r025", subject:"general-agriculture", question:"The first state in India in groundnut production is:", options:["Andhra Pradesh", "Tamil Nadu", "Gujarat", "Karnataka"], correct:2, explanation:"Gujarat is the leading state in groundnut production in India." },
  { id:"gen_r026", subject:"general-agriculture", question:"Cotton belongs to the genus:", options:["Corchorus", "Hibiscus", "Linum", "Gossypium"], correct:3, explanation:"Cotton belongs to the genus Gossypium, family Malvaceae." },
  { id:"gen_r027", subject:"general-agriculture", question:"The most cultivated species of cotton in India is:", options:["G. arboreum", "G. herbaceum", "G. hirsutum", "G. barbadense"], correct:2, explanation:"G. hirsutum (American cotton / Upland cotton) is the most widely grown in India." },
  { id:"gen_r028", subject:"general-agriculture", question:"Cotton fibre is derived from:", options:["Stem bark under standard field conditions", "Seed coat epidermis (trichomes)", "Roots under standard field conditions", "Leaves under standard field conditions"], correct:1, explanation:"Cotton fibres are elongated trichomes from the epidermis of the seed coat." },
  { id:"gen_r029", subject:"general-agriculture", question:"The 'square' in cotton refers to:", options:["Leaf axil bud", "Mature boll", "Seed", "Flower bud"], correct:3, explanation:"In cotton, the flower bud is called a 'square'." },
  { id:"gen_r030", subject:"general-agriculture", question:"Cotton leaf curl virus is transmitted by:", options:["Whitefly (Bemisia tabaci)", "Mealybug", "Thrips", "Aphid"], correct:0, explanation:"Cotton leaf curl virus (CLCuV) is transmitted by the whitefly Bemisia tabaci." },
  { id:"gen_r031", subject:"general-agriculture", question:"Seed rate for Bt hybrid cotton per acre is approximately:", options:["450 g/acre (~1.1 kg/ha)", "2.5 kg/acre", "10 kg/acre", "25 kg/acre"], correct:0, explanation:"Bt hybrid cotton seed is sold in 450 g packets that cover one acre. Per hectare this equals ~1.1 kg (since 1 ha ≈ 2.47 acres). The per-acre unit is the industry standard (CICR / seed company recommendations)." },
  { id:"gen_r033", subject:"general-agriculture", question:"'Topping' in cotton is done to:", options:["Apply growth regulators in agricultural meteorology under standard field conditions", "Remove lower leaves under atmospheric conditions under standard field conditions", "Remove apical meristem to promote lateral branching and boll development", "Remove roots in weather analysis under standard field conditions"], correct:2, explanation:"Topping removes the terminal bud to stop upward growth and improve boll formation on laterals." },
  { id:"gen_r034", subject:"general-agriculture", question:"ICRISAT headquarters is located at:", options:["Delhi", "Hyderabad (Patancheru)", "Bangalore", "Pune"], correct:1, explanation:"ICRISAT (International Crops Research Institute for the Semi-Arid Tropics) is headquartered at Patancheru, Hyderabad." },
  { id:"gen_r035", subject:"general-agriculture", question:"Spacing for medium-duration pigeonpea is:", options:["75×25 cm", "150×75 cm", "15×10 cm", "200×150 cm"], correct:0, explanation:"Medium-duration pigeonpea is spaced at 75 cm × 25 cm." },
  { id:"gen_r036", subject:"general-agriculture", question:"Sterility mosaic of pigeonpea is spread by:", options:["Thrips under standard field conditions", "Aphids under standard field conditions", "Whitefly under standard field conditions", "Eriophyid mites (Aceria cajani)"], correct:3, explanation:"Sterility mosaic virus of pigeonpea is transmitted by the eriophyid mite Aceria cajani." },
  { id:"gen_r037", subject:"general-agriculture", question:"ICPL-87119 is a popular variety of:", options:["Cowpea", "Chickpea", "Pigeonpea (red gram)", "Lentil"], correct:2, explanation:"ICPL-87119 (Asha) is a wilt and sterility-mosaic resistant pigeonpea variety." },
  { id:"gen_r038", subject:"general-agriculture", question:"Yellow mosaic disease of blackgram is transmitted by:", options:["Whitefly (Bemisia tabaci)", "Thrips", "Leafhopper", "Aphid"], correct:0, explanation:"Mungbean yellow mosaic virus (MYMV) is transmitted by the whitefly Bemisia tabaci." },
  { id:"gen_r039", subject:"general-agriculture", question:"Seed rate for blackgram is:", options:["20 kg/ha", "50 kg/ha", "100 kg/ha", "5 kg/ha"], correct:0, explanation:"Blackgram seed rate is approximately 20 kg/ha." },
  { id:"gen_r040", subject:"general-agriculture", question:"Powdery mildew of greengram is caused by:", options:["Xanthomonas campestris", "Phytophthora vignae", "Colletotrichum", "Erysiphe polygoni"], correct:3, explanation:"Powdery mildew of greengram is caused by Erysiphe polygoni." },
  { id:"gen_r041", subject:"general-agriculture", question:"Rhizobium inoculant used for blackgram and greengram belongs to species:", options:["R. meliloti", "Rhizobium phaseoli / R. vigna", "Bradyrhizobium japonicum", "R. japonicum"], correct:1, explanation:"Rhizobium phaseoli / R. vigna (cowpea type Rhizobium) forms nodules on blackgram and greengram." },
  { id:"gen_r042", subject:"general-agriculture", question:"Rhizobium used for soybean is:", options:["Rhizobium leguminosarum", "Sinorhizobium fredii", "Bradyrhizobium japonicum", "Rhizobium meliloti"], correct:2, explanation:"Bradyrhizobium japonicum forms effective nodules on soybean." },
  { id:"gen_r043", subject:"general-agriculture", question:"Seed rate for soybean is approximately:", options:["75 kg/ha", "250 kg/ha", "150 kg/ha", "10 kg/ha"], correct:0, explanation:"Recommended seed rate for soybean is about 75 kg/ha." },
  { id:"gen_r044", subject:"general-agriculture", question:"Anti-nutritional factor present in raw soybean is:", options:["Oxalic acid", "Aflatoxin", "Glucosinolate", "Trypsin inhibitor"], correct:3, explanation:"Soybean contains trypsin inhibitors that reduce protein digestibility when consumed raw." },
  { id:"gen_r045", subject:"general-agriculture", question:"Ricin, a highly toxic compound, is found in:", options:["Linseed under standard field conditions", "Sunflower under standard field conditions", "Castor bean (Ricinus communis)", "Sesame under standard field conditions"], correct:2, explanation:"Ricin is a toxin found in castor beans that is lethal in small quantities." },
  { id:"gen_r046", subject:"general-agriculture", question:"The major use of castor oil is in:", options:["Industrial lubricants and pharmaceuticals", "Food industry under standard field conditions", "Animal feed under standard field conditions", "Perfumery only under standard field conditions"], correct:0, explanation:"Castor oil is primarily used in industrial lubricants, pharmaceuticals, and plastics." },
  { id:"gen_r047", subject:"general-agriculture", question:"Seed rate for sesame is very low (about 3–5 kg/ha) because:", options:["Seeds are expensive", "Seeds don't germinate well", "Yield is low", "Seeds are very small and light"], correct:3, explanation:"Sesame seeds are very small (1000-seed weight ~3 g), so only 3–5 kg/ha is needed." },
  { id:"gen_r048", subject:"general-agriculture", question:"Phyllody in sesame is caused by:", options:["Fungus", "Phytoplasma", "Bacterium", "Virus"], correct:1, explanation:"Phyllody (conversion of floral parts to leaf-like structures) in sesame is caused by phytoplasma." },
  { id:"gen_r049", subject:"general-agriculture", question:"Castor oil content is approximately:", options:["35%", "50%", "75%", "20%"], correct:1, explanation:"Castor seeds contain about 50% oil." },
  { id:"gen_r050", subject:"general-agriculture", question:"The leading state in castor production in India is:", options:["Andhra Pradesh", "Gujarat", "Uttar Pradesh", "Rajasthan"], correct:1, explanation:"Gujarat is the leading castor-producing state in India." },
  { id:"gen_r051", subject:"general-agriculture", question:"Sesame is harvested when:", options:["At 40 DAS in agricultural meteorology", "Lower capsules begin to turn yellow and start opening", "After full yellowing in weather analysis", "All capsules are green under atmospheric conditions"], correct:1, explanation:"Sesame is harvested when lower capsules begin to yellow and open to avoid shattering losses." },
  { id:"gen_r052", subject:"general-agriculture", question:"Castor crop is a _____ crop in terms of water requirement:", options:["Moderate and drought-tolerant", "Very high water requirement", "Waterlogging-tolerant", "Aquatic"], correct:0, explanation:"Castor is relatively drought-tolerant and grows in areas with moderate rainfall." },
  { id:"gen_r053", subject:"general-agriculture", question:"Sesame is believed to have originated from:", options:["South America", "Australia", "Europe", "Africa (Ethiopia region)"], correct:3, explanation:"Sesame is believed to have originated in Ethiopia/Africa and was one of the earliest cultivated oilseeds." },
  { id:"gen_r054", subject:"general-agriculture", question:"Semilooper (Achaea janata) is a major pest of:", options:["Castor", "Rice", "Groundnut", "Cotton"], correct:0, explanation:"The castor semilooper (Achaea janata) is a defoliating pest of castor." },
  { id:"gen_r055", subject:"general-agriculture", question:"The antioxidant compounds in sesame seed are:", options:["Sesamolin and sesamin", "Glucosinolates", "Lycopene and beta-carotene", "Tannins and phytates"], correct:0, explanation:"Sesame seeds contain sesamolin and sesamin, potent antioxidants that give sesame oil its stability." },
  { id:"gen_r056", subject:"general-agriculture", question:"Sunflower is botanically known as:", options:["Brassica juncea", "Helianthus annuus", "Carthamus tinctorius", "Linum usitatissimum"], correct:1, explanation:"Sunflower is Helianthus annuus, belonging to family Asteraceae." },
  { id:"gen_r057", subject:"general-agriculture", question:"Sunflower is grown mainly for:", options:["Starch", "Fiber", "Protein", "Edible oil"], correct:3, explanation:"Sunflower is primarily grown as an oilseed crop; seed contains 40–50% oil." },
  { id:"gen_r058", subject:"general-agriculture", question:"Sunflower is a _____ day plant:", options:["Long day", "Very long day", "Short day", "Day neutral"], correct:3, explanation:"Sunflower is a day-neutral plant, flowering is not significantly affected by photoperiod." },
  { id:"gen_r059", subject:"general-agriculture", question:"The inflorescence of sunflower is called:", options:["Spike", "Capitulum (head)", "Panicle", "Raceme"], correct:1, explanation:"Sunflower inflorescence is a capitulum (head) with ray florets and disc florets." },
  { id:"gen_r060", subject:"general-agriculture", question:"Seed rate for sunflower is:", options:["150 kg/ha", "2.5–3 kg/ha", "75 kg/ha", "25 kg/ha"], correct:1, explanation:"Sunflower seed rate is very low — about 2.5–3 kg/ha for hybrids." },
  { id:"gen_r061", subject:"general-agriculture", question:"Downy mildew of sunflower is caused by:", options:["Botrytis cinerea", "Plasmopara halstedii", "Sclerotinia sclerotiorum", "Puccinia helianthi"], correct:1, explanation:"Downy mildew of sunflower is caused by Plasmopara halstedii." },
  { id:"gen_r062", subject:"general-agriculture", question:"Head rot of sunflower is caused by:", options:["Alternaria helianthi", "Botrytis cinerea", "All of the above", "Sclerotinia sclerotiorum"], correct:3, explanation:"Sclerotinia sclerotiorum causes head rot (white mold) of sunflower." },
  { id:"gen_r063", subject:"general-agriculture", question:"Safflower is botanically known as:", options:["Helianthus annuus", "Linum usitatissimum", "Carthamus tinctorius", "Ricinus communis"], correct:2, explanation:"Safflower is Carthamus tinctorius." },
  { id:"gen_r064", subject:"general-agriculture", question:"Cowpea (black-eyed pea) is botanically known as:", options:["Lablab purpureus", "Vigna mungo", "Vigna radiata", "Vigna unguiculata"], correct:3, explanation:"Cowpea is Vigna unguiculata." },
  { id:"gen_r065", subject:"general-agriculture", question:"Sunflower spacing is:", options:["200×200 cm", "15×5 cm", "150×100 cm", "60×30 cm"], correct:3, explanation:"Recommended spacing for sunflower is 60 cm × 30 cm." },
  { id:"gen_r066", subject:"general-agriculture", question:"Heliotropism (turning towards sun) is characteristic of:", options:["Cotton", "Maize", "Rice", "Sunflower"], correct:3, explanation:"Young sunflower plants show heliotropism — they track the sun across the sky." },
  { id:"gen_r067", subject:"general-agriculture", question:"The leading sunflower producing state in India is:", options:["Karnataka", "Maharashtra", "Andhra Pradesh", "Gujarat"], correct:0, explanation:"Karnataka is the leading sunflower-producing state in India." },
  { id:"gen_r068", subject:"general-agriculture", question:"Which of the following is a rabi oilseed crop?", options:["Groundnut", "Mustard/Rapeseed", "Sunflower", "Castor"], correct:1, explanation:"Mustard/rapeseed is mainly a rabi (winter) oilseed crop in India." },
  { id:"gen_r069", subject:"general-agriculture", question:"Sunflower oil is known for its high content of:", options:["Saturated fatty acids", "Ricinoleic acid", "Linoleic acid (polyunsaturated)", "Erucic acid"], correct:2, explanation:"Sunflower oil is rich in linoleic acid (omega-6 PUFA), making it heart-healthy." },
  { id:"gen_r070", subject:"general-agriculture", question:"KBSH-44 is a hybrid variety of:", options:["Safflower", "Sunflower", "Sesame", "Castor"], correct:1, explanation:"KBSH-44 is a popular sunflower hybrid developed by University of Agricultural Sciences, Dharwad." },
  { id:"gen_r071", subject:"general-agriculture", question:"The double helix structure of the DNA molecule was proposed by:", options:["Fraenkel-Conrat who proposed RNA structure", "Nirenberg and Khorana for nucleic acid code", "Hugo de Vries and Stadler in mutation work", "Watson and Crick in the year 1953"], correct:3, explanation:"Watson and Crick (1953) proposed the double helix structure of the DNA molecule, which became the foundation of molecular genetics and modern plant breeding." },
  { id:"gen_r072", subject:"general-agriculture", question:"Watson and Crick proposed which structure in 1953?", options:["Chromosome theory", "Genetic code", "Double helix structure of DNA", "Pureline theory"], correct:2, explanation:"As per DA-111 notes: Watson and Crick (1953) proposed the double helix structure of the DNA molecule." },
  { id:"gen_r073", subject:"general-agriculture", question:"Assertion (A): F1 hybrids show heterosis (hybrid vigor) in terms of yield and growth.\nReason (R): Heterosis occurs due to the combination of superior alleles from both parents and dominance/overdominance effects in the F1 generation.", options:["A is true but R is false", "A is false but R is true", "Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is NOT the correct explanation of A"], correct:2, explanation:"As per DA-111 notes: F1 hybrids show heterosis due to combination of superior alleles and dominance effects. Both A and R are true; R explains A." },
  { id:"gen_r074", subject:"general-agriculture", question:"Match the seed quality parameters with their importance:\n     Column-I (Parameter)        |  Column-II (Standard)        |  Column-III (Test used)\nA.  Germination (rice certified) |  1.  12% or below             |  i.   Hot air oven\nB.  Germination (wheat certified)|  2.  80% minimum              |  ii.  Blotter/sand germination\nC.  Moisture content (cereals)   |  3.  85% minimum              |  iii. Blotter/sand germination\nD.  Seed vigour                  |  4.  Not fixed, high preferred|  iv.  Accelerated aging test", options:["A-3-iii, B-2-ii,  C-1-i,   D-4-iv", "A-4-iv,  B-1-i,   C-3-iii,  D-2-ii", "A-1-i,   B-4-iv,  C-2-ii,  D-3-iii", "A-2-ii, B-3-iii,  C-1-i,   D-4-iv"], correct:3, explanation:"As per DA-111 notes: Germination rice certified seed: 80% minimum; Germination wheat certified: 85% minimum; Moisture cereals: 12% or below (hot air oven); Seed vigour: accelerated aging test." },
  { id:"gen_r075", subject:"general-agriculture", question:"Mendel's Law of Segregation states that during gamete formation:", options:["Genes on the same chromosome always segregate together for crop production", "Dominant alleles always suppress recessive alleles in F2 in agriculture", "Alleles of two different genes assort independently under field conditions", "The two alleles of a gene separate and go to different gametes"], correct:3, explanation:"Mendel's Law of Segregation (First Law) states that each individual has two alleles for each trait and these alleles separate (segregate) during gamete formation so each gamete carries only one allele." },
  { id:"gen_r076", subject:"general-agriculture", question:"In a monohybrid cross (Tt × Tt), the phenotypic ratio in F2 is:", options:["1 Tall : 1 Dwarf without any intermediate type", "All tall with no dwarf plants appearing", "3 Tall : 1 Dwarf (3:1)", "1 Tall : 2 Medium : 1 Dwarf (1:2:1)"], correct:2, explanation:"In a monohybrid cross Tt × Tt, the F2 genotypic ratio is 1 TT : 2 Tt : 1 tt, but the phenotypic ratio is 3 Tall (T_) : 1 Dwarf (tt) because T is dominant over t." },
  { id:"gen_r077", subject:"general-agriculture", question:"The Law of Independent Assortment (Mendel's Second Law) applies when two genes:", options:["Are located on different (non-homologous) chromosomes", "Show incomplete dominance where neither masks the other", "Are multiple alleles of the same gene locus", "Are located very close together on the same chromosome"], correct:0, explanation:"Mendel's Law of Independent Assortment states that genes located on different (non-homologous) chromosomes assort independently during gamete formation, producing a 9:3:3:1 ratio in F2 of a dihybrid cross." },
  { id:"gen_r078", subject:"general-agriculture", question:"In a dihybrid cross (AaBb × AaBb), the expected F2 phenotypic ratio is:", options:["9:3:3:1 with four distinct phenotypic classes", "1:2:1 showing three phenotypic classes", "1:1:1:1 with four equal phenotypic classes", "3:1 with only two phenotypic classes appearing"], correct:0, explanation:"A dihybrid cross AaBb × AaBb produces an F2 phenotypic ratio of 9 A_B_ : 3 A_bb : 3 aaB_ : 1 aabb, or 9:3:3:1, when genes assort independently and dominance is complete." },
  { id:"gen_r079", subject:"general-agriculture", question:"Incomplete dominance in a cross between red (RR) and white (rr) flowers produces F1 plants that are:", options:["Red and white in equal 1:1 proportion", "All white like the recessive parent", "All red like the dominant parent", "Pink (intermediate) between the two parents"], correct:3, explanation:"Incomplete dominance occurs when neither allele is completely dominant. The F1 (Rr) shows an intermediate pink phenotype between red (RR) and white (rr). F2 shows 1 Red : 2 Pink : 1 White (1:2:1) phenotypic ratio." },
  { id:"gen_r080", subject:"general-agriculture", question:"Codominance differs from incomplete dominance in that codominant alleles:", options:["Completely suppress the effect of the other allele always", "Both express fully and simultaneously in the heterozygote", "Interact to produce a phenotype unlike either parent", "Produce an intermediate blended phenotype in heterozygotes"], correct:1, explanation:"In codominance, both alleles are fully expressed simultaneously in the heterozygote with no blending. Example: AB blood group where both A and B antigens are present on red blood cells." },
  { id:"gen_r081", subject:"general-agriculture", question:"Epistasis differs from dominance in that epistasis involves interactions between:", options:["Environmental factors and a single gene determining phenotype", "Two alleles at the same gene locus in a diploid organism", "Genes on the same chromosome forming linkage groups", "Alleles at different loci where one gene masks another gene"], correct:3, explanation:"Epistasis is an interaction between alleles at different gene loci where one gene (epistatic) masks or suppresses the expression of another gene (hypostatic). It modifies the standard 9:3:3:1 dihybrid ratio." },
  { id:"gen_r082", subject:"general-agriculture", question:"Duplicate dominant epistasis produces an F2 ratio of:", options:["12 : 3 : 1 in three phenotypic classes", "15 dominant phenotype : 1 double recessive", "9 : 7 where recessive epistasis masks expression", "9 : 6 : 1 in three phenotypic classes"], correct:1, explanation:"Duplicate dominant epistasis (A_B_ + A_bb + aaB_ : aabb) produces a 15:1 F2 ratio. If at least one dominant allele at either locus produces the same phenotype, only double recessives show the alternative phenotype." },
  { id:"gen_r083", subject:"general-agriculture", question:"Recessive epistasis (9:3:4) occurs when:", options:["Homozygous dominant at one locus suppresses the other gene", "One gene shows codominance while the other shows dominance", "Both loci show incomplete dominance simultaneously", "The recessive homozygous condition at one locus is epistatic"], correct:3, explanation:"Recessive epistasis occurs when the homozygous recessive condition (aa) at one locus suppresses the expression of alleles at the other locus. This gives a 9 A_B_ : 3 A_bb : 4 aa__ ratio in F2." },
  { id:"gen_r084", subject:"general-agriculture", question:"Mendel's Law of Dominance states that in a cross between two pure lines:", options:["F1 shows both traits separately in 1:1 ratio", "F1 shows blending of both parent traits equally", "F1 shows only the recessive parental trait", "F1 shows only the dominant parental trait"], correct:3, explanation:"Mendel's Law of Dominance states that in a cross between two contrasting pure lines, F1 shows only one parental trait (dominant trait). The recessive trait is masked but not lost and reappears in F2." },
  { id:"gen_r085", subject:"general-agriculture", question:"A testcross involves crossing an organism of unknown genotype with:", options:["A homozygous dominant individual to confirm dominance", "Its F1 sibling to determine heterozygosity level", "A homozygous recessive individual to reveal genotype", "An F2 plant to generate a 9:3:3:1 ratio in offspring"], correct:2, explanation:"A testcross involves crossing an individual with an unknown genotype with a homozygous recessive individual (aabb). The offspring phenotypic ratios reveal whether the unknown parent was homozygous (all dominant offspring) or heterozygous (1:1 ratio)." },
  { id:"gen_r086", subject:"general-agriculture", question:"Gregor Johann Mendel conducted his landmark genetics experiments using:", options:["Zea mays (maize) with different kernel colors and textures", "Oenothera lamarkiana (evening primrose) plants", "Pisum sativum (garden pea) with seven contrasting traits", "Drosophila melanogaster (fruit fly) with multiple characters"], correct:2, explanation:"Mendel worked with Pisum sativum (garden pea) studying seven pairs of contrasting characters: seed shape, seed color, seed coat color, pod shape, pod color, flower position and plant height." },
  { id:"gen_r087", subject:"general-agriculture", question:"Pleiotropy refers to a condition where a single gene controls:", options:["A single trait influenced by many different gene loci", "Quantitative traits with additive effects from many genes", "Multiple different phenotypic traits simultaneously", "Expression of genes on the same chromosome always"], correct:2, explanation:"Pleiotropy is the phenomenon where a single gene controls multiple phenotypic traits. Example: the gene for body color in Drosophila also affects wing length and other characters. Many disease-resistance genes in crops are pleiotropic." },
  { id:"gen_r088", subject:"general-agriculture", question:"Polygenic inheritance (quantitative traits) differs from Mendelian traits because:", options:["The trait shows only two discrete phenotypic classes", "The environment has no effect on phenotype expression", "Multiple genes each contributing a small additive effect control the trait", "Only one gene controls the trait with complete dominance"], correct:2, explanation:"Polygenic (quantitative) traits are controlled by multiple genes each contributing a small additive effect, often influenced by environment. They show continuous variation (bell-curve distribution) rather than discrete Mendelian ratios. Examples: yield, height, oil content." },
  { id:"gen_r089", subject:"general-agriculture", question:"Heritability (h²) in the broad sense measures:", options:["The coefficient of variation of a trait across environments", "The proportion of phenotypic variance due to all genetic effects", "The fraction of phenotypic variation due to additive genetic effects only", "The proportion of variance due to environmental effects only"], correct:1, explanation:"Broad-sense heritability (H²) = VG/VP (genetic variance / phenotypic variance). It measures the proportion of total phenotypic variation attributable to all genetic effects (additive, dominance and epistatic). Narrow-sense heritability uses only additive variance." },
  { id:"gen_r090", subject:"general-agriculture", question:"Complementary gene interaction (9:7 ratio) occurs when:", options:["Both genes are on the same chromosome forming a linkage group", "One recessive gene masks the effect of the other gene locus", "Dominant alleles at both loci are needed to produce the trait", "A dominant allele at either locus alone can produce the trait"], correct:2, explanation:"Complementary gene interaction gives a 9:7 F2 ratio where dominant alleles at both loci (A_B_) are required to produce one phenotype. Plants with recessive homozygous condition at either or both loci show the alternative phenotype. Example: flower color in sweet pea." },
  { id:"gen_r091", subject:"general-agriculture", question:"The dominance hypothesis of heterosis proposes that hybrid vigor results from:", options:["Overdominance where heterozygous state is superior to either homozygote", "Complementation of dominant alleles from each parent masking deleterious recessives", "Greater metabolic efficiency due to increased enzyme activity in hybrids", "Epistatic interactions between non-allelic genes in the hybrid genome"], correct:1, explanation:"The dominance hypothesis states that heterosis occurs because dominant alleles from each parent complement (mask) the deleterious recessive alleles of the other parent. The F1 hybrid benefits from both parents' dominant alleles at most loci." },
  { id:"gen_r092", subject:"general-agriculture", question:"The overdominance hypothesis of heterosis proposes that:", options:["Non-allelic gene interactions (epistasis) cause superior F1 performance", "The heterozygous state (Aa) is inherently superior to both AA and aa", "Dominant alleles from parents complement each other in F1 hybrid", "Environmental factors interact with hybrid genotype to boost yield"], correct:1, explanation:"The overdominance hypothesis proposes that the heterozygous state at a locus (Aa) is inherently superior to either homozygous state (AA or aa). This is also called single-locus heterosis. Shull and East originally proposed this hypothesis." },
  { id:"gen_r093", subject:"general-agriculture", question:"The gamma ray source most commonly used for mutation breeding in plant materials is:", options:["Cobalt-60 or Cesium-137 installed in gamma chambers", "Uranium-235 found in nuclear reactors and power plants", "Radium-226 used in early radiation experiments worldwide", "Polonium-210 used for alpha particle emission in research"], correct:0, explanation:"Cobalt-60 (⁶⁰Co) and Cesium-137 (¹³⁷Cs) are the standard gamma ray sources used in gamma chambers for plant mutation breeding. They emit high-energy gamma rays that penetrate plant tissue and cause DNA damage leading to mutations." },
  { id:"gen_r094", subject:"general-agriculture", question:"Match the soil moisture constants with their definitions:\n     Column-I (Moisture constant) |  Column-II (Tension)        |  Column-III (Significance)\nA.  Saturation                   |  1.  31 bars (~15 bars)       |  i.   Plants wilt permanently\nB.  Field capacity               |  2.  0 bar                    |  ii.  All pores filled, no plant use\nC.  Permanent Wilting Point      |  3.  0.1-0.33 bar             |  iii. Available water for plants\nD.  Available Water Capacity     |  4.  FC - PWP                 |  iv.  Water between FC and PWP", options:["A-3-iii, B-2-ii, C-4-iv,   D-1-i", "A-4-iv, B-1-i,   C-3-iii,  D-2-ii", "A-2-ii, B-3-iii, C-1-i,   D-4-iv", "A-1-i,  B-4-iv,  C-2-ii,   D-3-iii"], correct:2, explanation:"As per DA-121 notes: Saturation (0 bar, all pores filled); Field capacity (0.1-0.33 bar); Permanent Wilting Point (~15 bar, plants wilt permanently); Available Water = FC - PWP." },
  { id:"gen_r095", subject:"general-agriculture", question:"Match the greenhouse gases with their agricultural sources:\n     Column-I (Gas)              |  Column-II (Source)          |  Column-III (GWP relative to CO2)\nA.  Methane (CH4)                |  1.  Synthetic fertilizers    |  i.   298x (very high)\nB.  Nitrous oxide (N2O)          |  2.  Paddy fields             |  ii.  21x\nC.  Carbon dioxide (CO2)         |  3.  Organic matter burning   |  iii. 1x (reference)\nD.  Water vapour                 |  4.  Transpiration, evap.     |  iv.  Variable", options:["A-4-iv, B-3-iii, C-2-ii,   D-1-i", "A-3-iii, B-2-ii, C-1-i,    D-4-iv", "A-1-i,  B-4-iv,  C-2-ii,   D-3-iii", "A-2-ii, B-1-i,   C-3-iii,  D-4-iv"], correct:3, explanation:"As per DA-121 notes: CH4 (paddy fields, 21x GWP); N2O (fertilizers, 298x GWP); CO2 (burning, 1x reference); Water vapour (transpiration, variable GWP)." },
  { id:"gen_r096", subject:"general-agriculture", question:"Hygroscopic water in soil is held with a matric suction greater than:", options:["–3.1 MPa", "–0.3 MPa", "–1.5 MPa", "–0.033 MPa"], correct:0, explanation:"Hygroscopic water is the thin film of water held tightly by soil particles at suctions greater than –3.1 MPa (31 bar) and is not available to plants." },
  { id:"gen_r097", subject:"general-agriculture", question:"Capillary water in soil is held between what suction range?", options:["0 to –0.033 MPa in soil science", "–0.033 MPa to –1.5 MPa (0.33 to 15 bar)", "–1.5 MPa to –3.1 MPa for soil management", "Greater than –3.1 MPa (31 bar)"], correct:1, explanation:"Capillary water is held in micropores at suctions between –0.033 MPa (FC) and –1.5 MPa (PWP). This is the fraction available to plants." },
  { id:"gen_r098", subject:"general-agriculture", question:"Soil organic matter content of most Indian agricultural soils is considered low (deficient) when it is below:", options:["3%", "0.1%", "0.75%", "5%"], correct:2, explanation:"Indian agricultural soils are generally classified as low in organic carbon when OC < 0.5% (roughly OM < 0.87%). The ICAR critical limit for SOM is ~0.75% OM or ~0.4% OC for adequate fertility." },
  { id:"gen_r099", subject:"general-agriculture", question:"The critical phosphorus concentration in soil solution for adequate crop growth is approximately:", options:["0.2–0.3 mg P L⁻¹", "< 0.01 mg P L⁻¹", "50–100 mg P L⁻¹", "5–10 mg P L⁻¹"], correct:0, explanation:"The critical P concentration in soil solution for most crops is about 0.2–0.3 mg L⁻¹ (ppm). Below this, plant P uptake is insufficient for maximum growth." },
  { id:"gen_r100", subject:"general-agriculture", question:"The critical limit of available zinc in soil (DTPA extractable Zn) below which crops show deficiency is:", options:["2.0 mg kg⁻¹", "0.6 mg kg⁻¹", "0.1 mg kg⁻¹", "5.0 mg kg⁻¹"], correct:1, explanation:"The critical limit for DTPA-extractable Zn in soil is 0.6 mg kg⁻¹. Below this, most crops (especially rice, maize, wheat) will show deficiency requiring zinc fertilisation." },
  { id:"gen_r101", subject:"general-agriculture", question:"Iron toxicity in rice ('bronzing') occurs when Fe²⁺ concentration in soil solution exceeds approximately:", options:["0.5 mg L⁻¹", "500 mg L⁻¹", "100–300 mg L⁻¹", "0.01 mg L⁻¹"], correct:2, explanation:"Fe²⁺ toxicity (bronzing) in rice occurs when soil solution Fe²⁺ exceeds about 100–300 mg L⁻¹ in waterlogged, highly reduced soils. Symptoms include reddish-brown leaf discolouration." },
  { id:"gen_r102", subject:"general-agriculture", question:"Bray-P1 method for soil P extraction uses which extractant?", options:["1N NH₄OAc at pH 7", "0.1N H₂SO₄", "0.03N NH₄F + 0.025N HCl", "0.5M NaHCO₃ at pH 8.5"], correct:2, explanation:"The Bray-P1 extraction uses 0.03N NH₄F + 0.025N HCl — the fluoride dissolves Al-P and Fe-P in acid soils. The Olsen method (NaHCO₃, pH 8.5) is preferred for neutral to alkaline soils." },
  { id:"gen_r103", subject:"general-agriculture", question:"The critical limit of available soil potassium (NH₄OAc extractable K) for most crops in Indian soils is:", options:["< 110–150 kg K₂O ha⁻¹", "< 300 kg K₂O ha⁻¹", "< 50 kg K₂O ha⁻¹", "< 500 kg K₂O ha⁻¹"], correct:0, explanation:"The critical limit for exchangeable K is typically 110–150 kg K₂O ha⁻¹ (or about 0.2 cmol(+) kg⁻¹). Soils below this are classified as K-deficient in ICAR recommendations." },
  { id:"gen_r104", subject:"general-agriculture", question:"The DTPA extraction solution (Lindsay and Norvell, 1978) is used to determine plant-available:", options:["Iron (Fe), Manganese (Mn), Zinc (Zn), and Copper (Cu) micronutrients", "Calcium (Ca) and Magnesium (Mg) in soil science", "Boron (B) and Molybdenum (Mo) for soil management", "Nitrogen (N) and phosphorus (P) in soil fertility"], correct:0, explanation:"DTPA (diethylenetriaminepentaacetic acid) at pH 7.3 is the standard chelating extractant for Fe, Mn, Zn, and Cu in neutral to alkaline soils. It mimics root chelation activity." },
  { id:"gen_r105", subject:"general-agriculture", question:"Nitrification inhibitors like Neem-coated urea are used to:", options:["Speed up conversion of urea to nitrate", "Kill soil microorganisms", "Slow down nitrification, preventing N loss through leaching and denitrification", "Increase alkalinity of soil"], correct:2, explanation:"As per DA-122 notes: Nitrification inhibitors (like Neem-coated urea) slow down nitrification, keeping nitrogen in the ammonium form longer, reducing losses through leaching and denitrification." },
  { id:"gen_r106", subject:"general-agriculture", question:"Ammonium sulphate (AS) contains what percentage of nitrogen and what secondary nutrient?", options:["20.6% N and 24% Sulphur (S)", "15% N and 10% Magnesium (Mg)", "33% N and 18% Calcium (Ca)", "46% N; no secondary nutrient"], correct:0, explanation:"Ammonium sulphate [(NH₄)₂SO₄] contains 20.6% N and 24% S. It is acidifying and preferred for alkaline soils and S-deficient crops like oilseeds, pulses, and rice." },
  { id:"gen_r107", subject:"general-agriculture", question:"The Neem-coated urea (NCU) policy mandated in India aims to:", options:["Add micronutrients (Zn, B) from neem seeds to the soil", "Improve neem tree cultivation by providing a market for neem oil", "Reduce urea theft for non-agricultural purposes by making it bitter", "Reduce urease activity and slow nitrification, improving N use efficiency by 5–10%"], correct:3, explanation:"Neem-coated urea (2% neem oil) has dual benefits: neem oil contains nimbin/nimbidin that inhibit soil urease (reducing NH₃ volatilisation) and Nitrosomonas activity (slowing nitrification), improving NUE by 5–15%." },
  { id:"gen_r108", subject:"general-agriculture", question:"Mussoorie rock phosphate (MRP) is a partially acidulated rock phosphate with P₂O₅ content of approximately:", options:["8%", "44%", "20%", "16%"], correct:2, explanation:"Mussoorie Rock Phosphate from Uttarakhand contains approximately 20% P₂O₅. It is partially soluble and suitable for direct application to acid soils as a slow-release P source." },
  { id:"gen_r109", subject:"general-agriculture", question:"In Telangana, the prevalent Alfisols (red soils) have high P fixation capacity because they are rich in:", options:["Free iron (Fe₂O₃) and aluminium (Al₂O₃) oxides from intense weathering", "Montmorillonite clay with high CEC in soil science under standard field conditions", "Organic matter with high phosphatase activity under standard field conditions", "CaCO₃ and Mg²⁺ for soil management under standard field conditions"], correct:0, explanation:"Alfisols (red soils) of Telangana are strongly weathered, rich in Fe₂O₃ (hematite, goethite) and Al₂O₃ oxides that have high P adsorption capacity, making P management critical in these soils." },
  { id:"gen_r110", subject:"general-agriculture", question:"India imports most of its potash requirement as MOP from which countries?", options:["USA and Australia under standard field conditions", "Bangladesh and Sri Lanka under standard field conditions", "Canada (Saskatchewan), Russia, Belarus, and Jordan", "China and Pakistan under standard field conditions"], correct:2, explanation:"India has no significant domestic potash deposits and imports nearly 100% of its MOP requirement from Canada (Canpotex), Russia, Belarus, and Jordan. This makes K the most import-dependent nutrient for Indian agriculture." },
  { id:"gen_r111", subject:"general-agriculture", question:"The Soil Health Card (SHC) scheme in India was launched in which year?", options:["2020", "2015", "2010", "2005"], correct:1, explanation:"The Soil Health Card Scheme was launched by the Government of India on 19 February 2015 under the Department of Agriculture, Cooperation and Farmers Welfare (DACFW) to promote soil testing and rational fertilizer use." },
  { id:"gen_r112", subject:"general-agriculture", question:"The Direct Benefit Transfer (DBT) system for fertilizer subsidy in India was introduced to:", options:["Allow import of fertilizers without customs duty in soil science", "Ensure subsidy reaches genuine farmers by linking fertilizer purchase to Aadhaar/farmer identity at point of sale", "Eliminate all fertilizer subsidies to farmers for soil management according to soil fertility and water conservation principles", "Regulate fertilizer prices to match international market rates in soil fertility"], correct:1, explanation:"DBT for fertilizers (PoS — Point of Sale machines linked to Aadhaar) ensures subsidy is released only on actual sale to verified farmers, preventing diversion. Fertilizer companies receive subsidy reimbursement from government after verified farmer sale." },
  { id:"gen_r113", subject:"general-agriculture", question:"The nutrient-based subsidy (NBS) scheme in India, implemented since 2010, covers which fertilizers?", options:["Urea and MOP only in soil science", "All P and K fertilizers (and SSP); urea remains under flat-rate subsidy separately", "All fertilizers including urea under a single scheme in soil fertility", "Only imported fertilizers excluding domestically produced ones for soil management"], correct:1, explanation:"NBS scheme (from April 2010) provides fixed per-kg subsidy on P and K fertilizers (DAP, MOP, SSP, NPK complexes, etc.) based on their nutrient content. Urea continues under a separate concession scheme with MRP fixed by government." },
  { id:"gen_r114", subject:"general-agriculture", question:"Under the FCO, the fertilizer inspector is empowered to:", options:["Import fertilizers directly on behalf of the government under standard field conditions", "Fix the price of fertilizers in the market during the critical growth period of crops", "Approve new fertilizer factories in soil science in irrigated crop production systems", "Take samples, inspect premises, check quality, and initiate prosecution for substandard fertilizers"], correct:3, explanation:"Fertilizer inspectors under FCO 1985 are authorised to collect samples, inspect dealer/manufacturer premises, check labelling, test quality, and file complaints/prosecute for violation of FCO provisions." },
  { id:"gen_r115", subject:"general-agriculture", question:"The Pradhan Mantri Krishi Sinchayee Yojana (PMKSY) is related to fertilizer management in that it promotes:", options:["Micro-irrigation (drip/sprinkler) enabling precision fertigation and reducing fertilizer wastage", "Free fertilizer distribution to all farmers under tropical agricultural conditions", "Export of surplus fertilizers to neighboring countries under standard field conditions", "Subsidy for organic fertilizer purchase only under tropical agricultural conditions"], correct:0, explanation:"PMKSY promotes micro-irrigation (drip/sprinkler) adoption. Drip systems enable fertigation — delivering nutrients directly to the root zone through irrigation water — improving fertilizer use efficiency by 20–30% and reducing waste." },
  { id:"gen_r116", subject:"general-agriculture", question:"The Father of Entomology in India is:", options:["M.O.P. Iyengar", "T.V. Ramakrishna Ayyar", "C.F. Corbett", "H. Maxwell-Lefroy"], correct:1, explanation:"T.V. Ramakrishna Ayyar is regarded as the Father of Entomology in India." },
  { id:"gen_r117", subject:"general-agriculture", question:"Oenocytes in insects are associated with:", options:["Cuticle synthesis and wax secretion", "Respiration in entomology", "Digestion in crop protection", "Reproduction for field crops"], correct:0, explanation:"Oenocytes are large cells associated with cuticle wax secretion and lipid metabolism." },
  { id:"gen_r118", subject:"general-agriculture", question:"Diapause in insects is:", options:["A type of metamorphosis for field crops", "A moulting process in entomology", "A feeding stage in crop protection", "A period of dormancy due to unfavourable conditions"], correct:3, explanation:"Diapause is a period of arrested development in insects triggered by environmental cues like photoperiod and temperature." },
  { id:"gen_r119", subject:"general-agriculture", question:"An insect that completes one generation per year is called:", options:["Polyvoltine", "Bivoltine", "Univoltine", "Multivoltine"], correct:2, explanation:"Univoltine insects complete one generation per year. Bivoltine = 2 generations, Multivoltine = many generations." },
  { id:"gen_r120", subject:"general-agriculture", question:"The caste responsible for egg-laying in a honeybee colony is:", options:["All three", "Queen", "Worker", "Drone"], correct:1, explanation:"The queen is the only egg-laying female in the honeybee colony. Workers are sterile females; drones are males." },
  { id:"gen_r121", subject:"general-agriculture", question:"Beeswax is secreted by which caste of honeybee?", options:["Worker", "Queen", "All castes equally", "Drone"], correct:0, explanation:"Worker bees secrete beeswax from wax glands on their abdomen, used to build honeycomb." },
  { id:"gen_r122", subject:"general-agriculture", question:"The main food of drone honeybee is:", options:["Pollen only", "Royal jelly throughout life", "Only water", "Honey and pollen"], correct:3, explanation:"Drones (male honeybees) consume honey and pollen. They do not collect food and rely on workers for feeding." },
  { id:"gen_r123", subject:"general-agriculture", question:"Propolis (bee glue) in honeybee hive is used for:", options:["Larval food under standard field conditions", "Sealing cracks and sterilising hive", "Queen rearing under standard field conditions", "Food storage under standard field conditions"], correct:1, explanation:"Propolis is a resinous mixture collected by bees from tree buds, used to seal gaps in the hive and has antimicrobial properties." },
  { id:"gen_r124", subject:"general-agriculture", question:"The commercial silk producing insect is:", options:["Bombyx mori", "Philosamia ricini", "Antheraea paphia", "Attacus atlas"], correct:0, explanation:"Bombyx mori (mulberry silkworm) is the primary commercial silk producer. It feeds on mulberry leaves." },
  { id:"gen_r125", subject:"general-agriculture", question:"The lac insect (Kerria lacca) belongs to order:", options:["Lepidoptera", "Coleoptera", "Hemiptera", "Hymenoptera"], correct:2, explanation:"Lac insect Kerria lacca (formerly Laccifer lacca) belongs to order Hemiptera, family Kerriidae." },
  { id:"gen_r126", subject:"general-agriculture", question:"Shellac is produced from lac resin of Kerria lacca. The main host trees include:", options:["Cotton and tobacco in entomology under standard field conditions", "Mango and banana in crop protection under standard field conditions", "Rice and wheat for field crops under standard field conditions", "Palas (Butea monosperma) and Ber (Ziziphus mauritiana)"], correct:3, explanation:"Kerria lacca is mainly reared on Palas (flame of the forest) and Ber. Other hosts include kusum and ghont." },
  { id:"gen_r127", subject:"general-agriculture", question:"Royal jelly is fed to:", options:["All larvae for first 3 days, then queens exclusively", "All adult bees in entomology", "Drones only in crop protection", "Workers throughout larval stage for field crops"], correct:0, explanation:"All larvae receive royal jelly for the first 3 days. After that, only queen-destined larvae continue to receive it throughout development." },
  { id:"gen_r128", subject:"general-agriculture", question:"Eri silk is produced by:", options:["Antheraea assama", "Bombyx mori", "Philosamia ricini", "Antheraea mylitta"], correct:2, explanation:"Eri silk is produced by Philosamia ricini (Samia cynthia ricini), which feeds on castor leaves." },
  { id:"gen_r129", subject:"general-agriculture", question:"Muga silk (golden silk) is produced by:", options:["Attacus atlas", "Bombyx mori", "Antheraea assama", "Philosamia ricini"], correct:2, explanation:"Muga silk, the golden yellow silk produced in Assam, comes from Antheraea assama silkworm feeding on som and sualu trees." },
  { id:"gen_r130", subject:"general-agriculture", question:"Honey is hygroscopic and does not ferment because of its:", options:["Presence of beeswax in crop protection", "Acidic pH only in entomology", "Low water content (17-20%) and high sugar content", "High water content for field crops"], correct:2, explanation:"Honey has low water content (17-20%) and high sugar concentration, which prevents fermentation by osmotic inhibition of microbes." },
  { id:"gen_r131", subject:"general-agriculture", question:"Tussah (wild silk) is produced by:", options:["Antheraea mylitta", "Antheraea assama", "Philosamia ricini", "Bombyx mori"], correct:0, explanation:"Tussah (tasar) silk is produced by Antheraea mylitta (Indian tasar silkworm), which feeds on Terminalia and Shorea trees." },
  { id:"gen_r132", subject:"general-agriculture", question:"The process of removing silk filament from cocoon is called:", options:["Reeling", "Degumming", "Spinning", "Weaving"], correct:0, explanation:"Reeling is the process of unwinding silk filament from the cocoon in one continuous thread. Cocoons are first softened in hot water." },
  { id:"gen_r133", subject:"general-agriculture", question:"The substance that holds silk filaments together in cocoon is:", options:["Fibroin", "Sericin", "Keratin", "Chitin"], correct:1, explanation:"Sericin (silk gum) holds silk fibroin filaments together in the cocoon. It is removed during degumming." },
  { id:"gen_r134", subject:"general-agriculture", question:"Biotic potential of insects refers to:", options:["Death rate in irrigated crop production systems", "Maximum reproductive capacity under ideal conditions", "Resistance to pesticides under standard field conditions", "Actual rate of increase under standard field conditions"], correct:1, explanation:"Biotic potential is the maximum reproductive capacity of an insect under ideal conditions (unlimited food, no predators, optimum temp)." },
  { id:"gen_r135", subject:"general-agriculture", question:"A pest that causes damage only occasionally under specific conditions is called:", options:["Occasional pest", "Potential pest", "Key pest", "Major pest"], correct:0, explanation:"Occasional pests cause economic damage only under specific favourable conditions but are not regular pests." },
  { id:"gen_r136", subject:"general-agriculture", question:"The relationship between predator and prey population shows:", options:["Prey increases first, then predator follows", "No relationship", "Predator increases before prey", "Both increase simultaneously"], correct:0, explanation:"In predator-prey relationships, prey population increases first, providing food for predators whose population then increases and reduces prey numbers." },
  { id:"gen_r137", subject:"general-agriculture", question:"A pest that is always present and causes significant damage is called:", options:["Key/major pest", "Occasional pest", "Induced pest", "Potential pest"], correct:0, explanation:"Key pests (major pests) are those that occur every season and regularly cause economic damage." },
  { id:"gen_r138", subject:"general-agriculture", question:"Pest resurgence is caused by:", options:["Crop rotation in entomology under standard field conditions", "Indiscriminate use of pesticides killing natural enemies", "Balanced fertilizer use in crop protection", "Use of resistant varieties under standard field conditions"], correct:1, explanation:"Pest resurgence occurs when pesticides kill natural enemies, allowing the target pest to rebound to higher levels than before treatment." },
  { id:"gen_r139", subject:"general-agriculture", question:"An insect pest that is kept below EIL by natural enemies but can become a pest if control is disturbed is:", options:["Major pest", "Occasional pest", "Secondary pest", "Potential pest"], correct:3, explanation:"Potential pests are naturally controlled below EIL by natural enemies but can become economic pests if natural control fails." },
  { id:"gen_r140", subject:"general-agriculture", question:"Environmental resistance includes:", options:["Only temperature for field crops", "Only predators in entomology", "Only pesticides in crop protection", "Food, weather, natural enemies and disease"], correct:3, explanation:"Environmental resistance includes all biotic (predators, parasites, disease, competition) and abiotic (temperature, humidity, rainfall) factors that limit population growth." },
  { id:"gen_r141", subject:"general-agriculture", question:"'S' shaped (sigmoid) population growth curve represents:", options:["Exponential growth without limits", "No population change", "Decline of pest population", "Logistic growth with carrying capacity"], correct:3, explanation:"S-shaped (logistic/sigmoid) growth curve shows population growth that levels off at the carrying capacity (K) of the environment." },
  { id:"gen_r142", subject:"general-agriculture", question:"White-backed planthopper (WBPH) of rice is:", options:["Sogatella furcifera", "Recilia dorsalis", "Nephotettix virescens", "Nilaparvata lugens"], correct:0, explanation:"White-backed planthopper is Sogatella furcifera. It is found on upper parts of plant, unlike BPH which is found at base." },
  { id:"gen_r143", subject:"general-agriculture", question:"Fall armyworm (FAW) scientifically known as Spodoptera frugiperda is native to:", options:["Africa", "Asia", "Australia", "Americas"], correct:3, explanation:"FAW (Spodoptera frugiperda) is native to tropical Americas. It invaded Africa in 2016 and reached India in 2018." },
  { id:"gen_r144", subject:"general-agriculture", question:"Fall armyworm in India primarily attacks:", options:["Rice", "Sugarcane", "Cotton", "Maize"], correct:3, explanation:"FAW in India primarily attacks maize, causing severe damage to young plants and cobs. It also attacks sorghum and other crops." },
  { id:"gen_r145", subject:"general-agriculture", question:"FALL armyworm was first reported in India in which state?", options:["Punjab", "Telangana", "Tamil Nadu and Karnataka", "Maharashtra"], correct:2, explanation:"FAW was first reported in India in May 2018 from maize fields in Tamil Nadu and Karnataka." },
  { id:"gen_r146", subject:"general-agriculture", question:"Application of sand + Chlorpyrifos in the whorl of maize is recommended against:", options:["Root grub", "Fall armyworm and stem borer", "Stalk borer", "Aphids in pest management"], correct:1, explanation:"Chlorpyrifos mixed with sand and applied in the whorl effectively controls FAW and stem borer larvae that feed in the whorl." },
  { id:"gen_r147", subject:"general-agriculture", question:"Spodoptera frugiperda can be identified by 'window pane' feeding symptom where:", options:["Entire leaf is consumed in pest management", "Leaf turns white in crop protection", "Larva feeds from one side leaving transparent epidermis", "Leaf rolls up for field crops"], correct:2, explanation:"Young FAW larvae feed from one side of the leaf leaving the opposite epidermis intact ('window pane' effect). Older larvae consume entire leaf tissue." },
  { id:"gen_r148", subject:"general-agriculture", question:"Nematode management by Paecilomyces lilacinus is an example of:", options:["Chemical control", "Cultural control", "Biological control using fungi", "Physical control"], correct:2, explanation:"Paecilomyces lilacinus is a fungal bioagent that parasitizes nematode eggs and females, used as a biological control agent." },
  { id:"gen_r149", subject:"general-agriculture", question:"MRL (Maximum Residue Limit) in food means:", options:["Maximum yield of a crop in pest management under standard field conditions", "Minimum required level of pesticide in crop protection under standard field conditions", "Maximum quantity of pesticide allowed in food legally safe for consumption", "Maximum legal pesticide application for field crops under standard field conditions"], correct:2, explanation:"MRL is the highest legally permissible concentration of pesticide residue in food/feed, set to ensure consumer safety." },
  { id:"gen_r150", subject:"general-agriculture", question:"WHO classifies pesticide toxicity based on LD50 values. Extremely hazardous pesticides belong to class:", options:["Class Ia", "Class II", "Class III", "Class IV"], correct:0, explanation:"WHO Class Ia = Extremely hazardous (oral LD50 <5 mg/kg). Class Ib = Highly hazardous, Class II = Moderately, Class III = Slightly, Class IV = Unlikely hazardous." },
  { id:"gen_r151", subject:"general-agriculture", question:"First aid for organophosphate poisoning includes:", options:["Applying cold water", "Inducing vomiting with salt water", "Drinking milk", "Atropine injection"], correct:3, explanation:"Atropine sulphate (1-4 mg IV) is the antidote for organophosphate poisoning. 2-PAM (pralidoxime) is used as adjunct therapy." },
  { id:"gen_r152", subject:"general-agriculture", question:"The IPM approach was officially adopted by FAO in:", options:["1985", "1965", "1972", "1992"], correct:2, explanation:"FAO adopted the IPM concept in 1972 as the preferred approach to pest management globally." },
  { id:"gen_r153", subject:"general-agriculture", question:"Personal Protective Equipment (PPE) during pesticide application must include:", options:["Rubber gloves only in pest management under standard field conditions", "Gloves, mask/respirator, full-body coverall, goggles, rubber boots", "Any clothing for field crops under standard field conditions", "Hat only in crop protection under standard field conditions"], correct:1, explanation:"Full PPE includes chemical-resistant gloves, face mask/respirator, full-body coverall, safety goggles and rubber boots." },
  { id:"gen_r154", subject:"general-agriculture", question:"WTO SPS Agreement relates to:", options:["Currency exchange as per crop protection and integrated pest management principles", "Import duties as per crop protection and integrated pest management principles", "Trade in industrial goods in crop protection", "Sanitary and Phytosanitary measures (pesticide residues, food safety) in international trade"], correct:3, explanation:"WTO SPS (Sanitary and Phytosanitary) Agreement sets standards for food safety and animal/plant health affecting agricultural trade, including pesticide residue standards." },
  { id:"gen_r155", subject:"general-agriculture", question:"One horsepower is equal to how many watts?", options:["550 watts", "746 watts", "1000 watts", "1341 watts"], correct:1, explanation:"1 HP = 746 watts. This is the standard mechanical horsepower used in farm power calculations. Knowing this conversion is essential for comparing engine ratings." },
  { id:"gen_r156", subject:"general-agriculture", question:"Which of the following power sources has the highest efficiency for converting input energy to useful mechanical work?", options:["Electric motor (85–95%)", "Diesel engine (32–38%)", "Steam engine (15–20%)", "Petrol engine (25–32%)"], correct:0, explanation:"Electric motors are the most efficient prime movers, converting 85–95% of electrical energy to mechanical work. Diesel engines convert 32–38% and petrol engines 25–32%, while steam engines are the least efficient at 15–20%." },
  { id:"gen_r157", subject:"general-agriculture", question:"What is the relationship between 1 kW and HP?", options:["1 kW = 1.341 HP", "1 kW = 0.746 HP", "1 kW = 0.5 HP", "1 kW = 2.0 HP"], correct:0, explanation:"1 kW = 1.341 HP (or equivalently 1 HP = 0.746 kW). This conversion is frequently tested: a 10 HP engine = 7.46 kW." },
  { id:"gen_r158", subject:"general-agriculture", question:"Farm power availability in India (HP/ha) has increased significantly. What was the approximate value in 2022?", options:["4.0 kW/ha", "0.5 kW/ha", "1.5 kW/ha", "2.5 kW/ha"], correct:3, explanation:"India's farm power availability increased from about 0.3 kW/ha in 1960–61 to approximately 2.5 kW/ha in recent years, reflecting rapid farm mechanisation. The target is 4 kW/ha." },
  { id:"gen_r159", subject:"general-agriculture", question:"The rated engine speed of a farm tractor engine is typically:", options:["500–800 RPM", "1200–1500 RPM", "3000–3600 RPM", "1800–2200 RPM"], correct:3, explanation:"Farm tractor diesel engines have a rated (governed) speed of 1800–2200 RPM. At this speed, maximum rated power is developed. Governors prevent over-speeding beyond this rated speed." },
  { id:"gen_r160", subject:"general-agriculture", question:"The impeller of a centrifugal pump:", options:["Filters sediment from irrigation water in plant breeding", "Controls water flow rate at the outlet for crop improvement", "Rotates at high speed to impart velocity and centrifugal force to water", "Reciprocates to push water through valves in variety development"], correct:2, explanation:"The impeller is the rotating element of a centrifugal pump. It has vanes that spin at high speed, imparting velocity (kinetic energy) to water by centrifugal action. The diffuser/volute then converts velocity to pressure head." },
  { id:"gen_r161", subject:"general-agriculture", question:"A submersible pump differs from a centrifugal pump in that it:", options:["Uses only wind energy in plant breeding according to plant breeding and genetics science principles", "Cannot pump more than 1 m3/hr according to plant breeding and genetics science principles", "Is installed below water level in the borewell; motor and pump are in one sealed unit", "Is installed at the surface; pump and motor are separate in variety development"], correct:2, explanation:"A submersible pump has the motor and pump combined in one sealed, waterproof unit installed below the water surface in borewells/deepwells. Water cools the motor. This is preferred for borewells where the water table is deep." },
  { id:"gen_r162", subject:"general-agriculture", question:"Drip irrigation emitters deliver water at a flow rate of:", options:["2–8 litres/hour", "10–20 litres/hour", "50–100 litres/hour", "0.1–0.5 litres/hour"], correct:0, explanation:"Drip emitters (drippers) typically discharge 2–8 litres per hour (most commonly 4 L/hr) directly at the plant base. This slow, precise application minimises evaporation and maintains optimal soil moisture near the root zone." },
  { id:"gen_r163", subject:"general-agriculture", question:"Sprinkler irrigation achieves a water use efficiency (WUE) of approximately:", options:["75–85%", "60–70%", "40–50%", "95–100%"], correct:0, explanation:"Sprinkler irrigation has WUE of 75–85%, compared to 40–50% for surface (flood) irrigation and 90–95% for drip irrigation. Sprinklers reduce deep percolation and runoff losses compared to flood irrigation." },
  { id:"gen_r164", subject:"general-agriculture", question:"The hydraulic head (total head) a pump must overcome is the sum of:", options:["Suction head only in plant breeding according to plant breeding and genetics science principles", "Only pipe friction losses for crop improvement", "Suction lift + delivery head + friction losses + velocity head", "Delivery head minus suction head in variety development"], correct:2, explanation:"Total head = static head (suction lift + delivery height) + friction head losses in pipes and fittings + velocity head (minor term). The pump must develop sufficient head to lift water from source to delivery point against all these resistances." },
  { id:"gen_r165", subject:"general-agriculture", question:"Cavitation in a centrifugal pump occurs when:", options:["The impeller speed is too low in variety development", "Too much water is available in plant breeding according to plant breeding and genetics science principles", "Water temperature is too cold according to plant breeding and genetics science principles", "Suction head is too high and water vaporises at the inlet, forming bubbles that implode"], correct:3, explanation:"Cavitation occurs when suction lift is too high or suction line is obstructed, causing pressure at the impeller eye to fall below the vapour pressure of water. Vapour bubbles form and then implode violently, causing noise, vibration, and impeller damage." },
  { id:"gen_r166", subject:"general-agriculture", question:"The maximum practical suction lift for a centrifugal pump at sea level is approximately:", options:["3 m", "15 m", "7–8 m", "25 m"], correct:2, explanation:"The theoretical maximum suction lift at sea level is 10.3 m (atmospheric pressure head). Practically, accounting for friction and vapour pressure, the safe maximum suction lift is 7–8 m. Beyond this, cavitation occurs." },
  { id:"gen_r167", subject:"general-agriculture", question:"Micro-sprinklers (mini sprinklers) are best suited for:", options:["Large field crops like wheat in plant breeding", "Greenhouse cooling only for crop improvement", "Orchards and horticultural crops requiring targeted irrigation close to trees", "Paddy fields in variety development according to plant breeding and genetics science principles"], correct:2, explanation:"Micro-sprinklers/mini sprinklers irrigate a small radius (1–3 m) around individual trees in orchards. They provide more uniform wetting than drip (covers wider area) but use less water than conventional sprinklers, ideal for fruit trees." },
  { id:"gen_r169", subject:"general-agriculture", question:"The discharge of a centrifugal pump is expressed in:", options:["Litres per second (L/s) or cubic metres per hour (m³/hr)", "Kilograms per second in plant breeding", "Metres of head for crop improvement", "Kilowatts in variety development according to plant breeding and genetics science principles"], correct:0, explanation:"Pump discharge (flow rate) is measured in litres per second (L/s), litres per minute (L/min) or m³/hour. Head is measured in metres. Power is in kilowatts. These three (flow rate, head, power) define pump performance." },
  { id:"gen_r170", subject:"general-agriculture", question:"A pumpset for flood irrigation of paddy typically requires:", options:["Low head, high discharge", "High head, low discharge", "Very low head, very low discharge", "High head, high discharge"], correct:0, explanation:"Paddy (surface) irrigation needs large volumes of water at low delivery height (low total head). Therefore a high-discharge, low-head centrifugal pump (axial or mixed flow type) is suitable. Deep borewell irrigation needs high head, moderate discharge." },
  { id:"gen_r171", subject:"general-agriculture", question:"The application rate of a sprinkler system must be less than:", options:["The wind speed in plant breeding", "The crop evapotranspiration rate for crop improvement", "The atmospheric humidity in variety development", "The soil's basic infiltration rate (to avoid runoff and ponding)"], correct:3, explanation:"The sprinkler application rate (mm/hr) must not exceed the soil's steady-state (basic) infiltration rate. If application is faster than infiltration, water ponds on the surface, causes runoff and erosion, and reduces efficiency." },
  { id:"gen_r172", subject:"general-agriculture", question:"Which pump type is most suitable for lifting water from deep borewells (>50 m)?", options:["Axial flow pump", "Centrifugal (surface) pump", "Submersible pump", "Reciprocating hand pump"], correct:2, explanation:"Submersible pumps are designed for deep borewells. They are installed below the water surface in the borewell and can lift water from depths of 50–300+ m. Surface centrifugal pumps are impractical for depths beyond 7–8 m (suction limit)." },
  { id:"gen_r173", subject:"general-agriculture", question:"A filter in a drip irrigation system is essential to:", options:["Increase water pressure in plant breeding under standard field conditions", "Add fertiliser to the water for crop improvement under standard field conditions", "Prevent clogging of emitters by removing suspended particles and algae", "Control timing of irrigation in variety development under standard field conditions"], correct:2, explanation:"Drip emitters have very small openings (0.5–1.5 mm) that clog easily with sand, silt, algae and mineral deposits. Screen, disc or sand media filters are mandatory to remove particles >130 µm before the water enters the lateral lines." },
  { id:"gen_r174", subject:"general-agriculture", question:"The uniformity coefficient of a sprinkler/drip system indicates:", options:["The energy efficiency of the pump motor", "The chemical quality of irrigation water", "How evenly water is distributed across the field", "How uniform the water pressure is in the pump"], correct:2, explanation:"The distribution uniformity coefficient (DU) or Christiansen's uniformity coefficient (CU) measures how evenly water is applied across the irrigated area. A CU > 80% is acceptable; > 90% is excellent. Low uniformity means some areas are over- or under-irrigated." },
  { id:"gen_r175", subject:"general-agriculture", question:"An axial flow (propeller) pump is best suited for:", options:["Very low head, very high discharge (drainage, flood irrigation)", "Very high head, low discharge applications", "Deep borewell applications in plant breeding", "Sprinkler irrigation requiring 5–7 bar for crop improvement"], correct:0, explanation:"Axial flow (propeller) pumps move large volumes of water at very low heads (1–5 m). They are ideal for drainage, flood irrigation, and pumping from rivers or canals where the static lift is very small but high flow rates are required." },
  { id:"gen_r176", subject:"general-agriculture", question:"The 'Disease Triangle' concept in plant pathology states that disease occurs when:", options:["Infected seed, poor drainage and excess nitrogen fertilizer interact", "Primary inoculum, secondary inoculum and vector all become active", "High rainfall, high temperature and dense planting coincide together", "Susceptible host, virulent pathogen and favourable environment interact"], correct:3, explanation:"The Plant Disease Triangle states that disease occurs only when a susceptible host, virulent pathogen and favourable environment all interact simultaneously. Absence of any one factor prevents disease development." },
  { id:"gen_r177", subject:"general-agriculture", question:"Koch's Postulates in plant pathology require which sequence of key steps?", options:["Isolate pathogen, inoculate healthy plant, reproduce disease, re-isolate pathogen", "Visual symptom description, microscopy and chemical pathogen testing only", "Cultural identification, host range testing and multi-location field validation trials", "Serological testing, PCR analysis and complete genomic sequencing of pathogen"], correct:0, explanation:"Koch's Postulates: 1) Pathogen found associated with all diseased plants; 2) Isolate and grow in pure culture; 3) Inoculate healthy plant and reproduce the same disease; 4) Re-isolate the same pathogen. These four steps prove causal relationship." },
  { id:"gen_r178", subject:"general-agriculture", question:"An epidemic disease example is Late Blight of potato which caused the Irish famine in", options:["1900", "1830", "1865", "1845"], correct:3, explanation:"As per DA-171 notes: Epidemic disease - usually occurs widely but periodically in destructive form. Ex: Late blight of potato - Irish famine (1845)." },
  { id:"gen_r179", subject:"general-agriculture", question:"The father of plant pathology is:", options:["Louis Pasteur", "Robert Koch", "Anton de Bary", "Martinus Beijerinck"], correct:2, explanation:"Heinrich Anton de Bary is considered the father of plant pathology for his work on fungal diseases, especially late blight of potato." },
  { id:"gen_r180", subject:"general-agriculture", question:"The disease triangle concept includes:", options:["Soil, Water, Air", "Temperature, Humidity, Wind", "Plant, Insect, Soil", "Host, Pathogen, Environment"], correct:3, explanation:"The disease triangle states that disease develops when a susceptible host, virulent pathogen, and favorable environment interact." },
  { id:"gen_r181", subject:"general-agriculture", question:"Koch's postulates were proposed to:", options:["Develop pesticides for crop protection under standard field conditions", "Study plant viruses in plant pathology under standard field conditions", "Classify fungi in disease management under standard field conditions", "Prove that a specific microorganism causes a specific disease"], correct:3, explanation:"Koch's postulates establish a causal relationship between a microorganism and a disease." },
  { id:"gen_r182", subject:"general-agriculture", question:"The first step in Koch's postulates is:", options:["Associate the organism with diseased plant", "Reisolate the pathogen", "Inoculate healthy plant", "Grow the organism in pure culture"], correct:0, explanation:"The first step is to consistently find and associate the suspected pathogen with every case of the disease." },
  { id:"gen_r183", subject:"general-agriculture", question:"The Irish Famine (1845–49) was caused by:", options:["Virus disease in plant pathology", "Bacterial wilt in disease management", "Late blight of potato (Phytophthora infestans)", "Drought for crop protection"], correct:2, explanation:"The great Irish Famine was caused by the oomycete Phytophthora infestans causing late blight of potato." },
  { id:"gen_r184", subject:"general-agriculture", question:"Covered smut / bunt of wheat is caused by:", options:["Tilletia caries", "Ustilago tritici", "Puccinia graminis", "Ustilago nuda"], correct:0, explanation:"Covered smut (bunt) of wheat is caused by Tilletia caries (and T. foetida)." },
  { id:"gen_r185", subject:"general-agriculture", question:"Rhizobium forms symbiotic association with:", options:["All grasses", "Legume roots for N₂ fixation", "Rice roots", "Mycorrhizal fungi"], correct:1, explanation:"Rhizobium bacteria form symbiotic nitrogen-fixing nodules on the roots of leguminous plants." },
  { id:"gen_r186", subject:"general-agriculture", question:"Azospirillum is a:", options:["Free-living / associative N₂ fixer in rhizosphere of cereals", "Mycorrhizal fungus in plant pathology under standard field conditions", "Phosphate solubilizer only in disease management", "Symbiotic N₂ fixer in legumes under standard field conditions"], correct:0, explanation:"Azospirillum is an associative N₂-fixing bacterium found in the rhizosphere of cereals and grasses." },
  { id:"gen_r187", subject:"general-agriculture", question:"Azolla is used as a biofertilizer in rice because it:", options:["Has symbiotic cyanobacterium Anabaena that fixes N₂", "Fixes phosphorus in disease management", "Controls weeds for crop protection", "Releases potassium in plant pathology"], correct:0, explanation:"Azolla (water fern) contains the cyanobacterium Anabaena azollae which fixes atmospheric nitrogen." },
  { id:"gen_r188", subject:"general-agriculture", question:"Frankia forms symbiotic N₂-fixing nodules on:", options:["Legumes under standard field conditions", "Rice under standard field conditions", "Cotton under standard field conditions", "Non-leguminous plants (Casuarina, Alnus)"], correct:3, explanation:"Frankia (actinomycete) forms actinorhizal nodules on non-leguminous trees like Casuarina and Alnus." },
  { id:"gen_r189", subject:"general-agriculture", question:"The blue-green algae (cyanobacteria) that fix nitrogen include:", options:["Chlorella, Spirogyra", "Anabaena, Nostoc, Tolypothrix", "Saccharomyces, Aspergillus", "Rhizobium, Azotobacter"], correct:1, explanation:"Anabaena, Nostoc, and Tolypothrix are heterocyst-forming cyanobacteria that fix atmospheric N₂." },
  { id:"gen_r190", subject:"general-agriculture", question:"The enzyme responsible for biological nitrogen fixation is:", options:["Nitrogenase", "Urease", "Nitrate reductase", "Amylase"], correct:0, explanation:"Nitrogenase enzyme complex (Mo-Fe protein + Fe protein) catalyzes the conversion of N₂ to NH₃." },
  { id:"gen_r191", subject:"general-agriculture", question:"Which wheat variety is most widely cultivated in Telangana for its high yield potential?", options:["GW-496", "HD-2781", "PBW-343", "K-9107"], correct:1, explanation:"HD-2781 (Raj 4120) is one of the most popular wheat varieties in Telangana and Andhra Pradesh, known for its high yield potential, rust resistance, and wide adaptability. GW-496 is Gujarat-specific." },
  { id:"gen_r192", subject:"general-agriculture", question:"The recommended row spacing for wheat cultivation in India is:", options:["30 cm", "45 cm", "22.5 cm", "15 cm"], correct:2, explanation:"Wheat is sown at 22.5 cm row spacing using a seed drill for good crop density and ease of intercultivation. Wider spacing reduces yield; narrower spacing causes lodging. This is the standard for all recommended packages." },
  { id:"gen_r193", subject:"general-agriculture", question:"Recommended seed rate for timely sown wheat is:", options:["100 kg/ha", "150 kg/ha", "50 kg/ha", "75 kg/ha"], correct:0, explanation:"The recommended seed rate for timely sown wheat (November) is 100 kg/ha. For late-sown wheat (December onwards), the seed rate is increased to 125 kg/ha to compensate for reduced tillering due to shorter growing period." },
  { id:"gen_r194", subject:"general-agriculture", question:"The recommended nitrogen dose for wheat cultivation is:", options:["180 kg N/ha", "120 kg N/ha", "60 kg N/ha", "90 kg N/ha"], correct:1, explanation:"120 kg N/ha is recommended for irrigated wheat. N is applied in three splits: 50% as basal + 25% at CRI + 25% at jointing. Late-sown wheat gets 80 kg N/ha due to shorter crop duration." },
  { id:"gen_r195", subject:"general-agriculture", question:"The CRI (Crown Root Initiation) stage in wheat occurs at approximately:", options:["1–2 days after sowing", "45–50 days after sowing", "At heading stage", "20–21 days after sowing"], correct:3, explanation:"CRI (Crown Root Initiation) stage occurs 20–21 days after sowing when the crown (nodal) roots begin to emerge. The first irrigation must be given at CRI stage as this is the most critical moisture-sensitive stage in wheat." },
  { id:"gen_r196", subject:"general-agriculture", question:"How many irrigations are generally recommended for wheat cultivation in Telangana?", options:["2 irrigations", "6 irrigations", "8 irrigations", "4 irrigations"], correct:1, explanation:"Six irrigations are recommended at: (1) CRI, (2) Tillering, (3) Jointing, (4) Flowering/Boot leaf, (5) Milky stage, (6) Dough stage. Critical stages are CRI and grain filling. Total water requirement is 450–500 mm." },
  { id:"gen_r197", subject:"general-agriculture", question:"Recommended phosphorus dose for wheat cultivation is:", options:["120 kg P₂O₅/ha", "30 kg P₂O₅/ha", "90 kg P₂O₅/ha", "60 kg P₂O₅/ha"], correct:3, explanation:"60 kg P₂O₅/ha is recommended for wheat. The full phosphorus dose is applied as basal (at sowing) since phosphorus moves very little in the soil and must be placed near the seed zone during preparation." },
  { id:"gen_r198", subject:"general-agriculture", question:"The GW-496 variety of wheat is primarily grown in:", options:["Telangana and Andhra Pradesh", "Punjab and Haryana", "Gujarat and Rajasthan", "Assam and West Bengal"], correct:2, explanation:"GW-496 (Gujarat Wheat 496) is a semi-dwarf variety developed by GAU, Gujarat. It is suited for Gujarat, Rajasthan, and parts of Western India. It has good bread-making quality and is drought-tolerant under limited water conditions." },
  { id:"gen_r199", subject:"general-agriculture", question:"Lodging in wheat is primarily caused by:", options:["Excess nitrogen + irrigation, causing tall, weak stems that fall over", "Excess phosphorus application in field conditions under field conditions", "Deficiency of potassium in crop production in agriculture", "Late sowing of the crop for agricultural purposes"], correct:0, explanation:"Lodging (plants falling over) occurs when excess nitrogen or high plant population creates tall, soft, weak stems that cannot support the heavy grain head in combination with strong winds or heavy rain. Dwarf varieties resist lodging better." },
  { id:"gen_r200", subject:"general-agriculture", question:"The most critical irrigation stage in wheat for grain filling is:", options:["Grain filling (milky dough) stage", "Tillering stage under standard field conditions", "Jointing stage under standard field conditions", "CRI stage under standard field conditions"], correct:0, explanation:"While CRI is most critical for plant establishment, the grain filling (milky to dough) stage is most critical for yield because water stress at this stage directly reduces grain size and final yield. Both CRI and grain fill are critical." },
  { id:"gen_r201", subject:"general-agriculture", question:"Which fungal disease is the most serious threat to wheat production?", options:["Charcoal rot in crop production in agriculture", "Yellow (stripe) rust, brown (leaf) rust, and black (stem) rust", "Alternaria blight in field conditions under field conditions", "Sclerotinia stem rot for agricultural purposes for crop production"], correct:1, explanation:"Rusts (caused by Puccinia spp.) are the most devastating wheat diseases. Yellow/stripe rust (P. striiformis), Brown/leaf rust (P. triticina) and Black/stem rust (P. graminis) can cause 10–100% yield loss in susceptible varieties under epidemic conditions." },
  { id:"gen_r202", subject:"general-agriculture", question:"Wheat is classified as a:", options:["Zaid crop sown in March", "Kharif crop sown in June–July", "Perennial crop grown year-round", "Rabi crop sown in October–November"], correct:3, explanation:"Wheat is a Rabi (winter) season crop in India, sown in October–November and harvested in March–April. It requires cool weather (15–20°C) during vegetative stage and warm, dry weather at maturity for good grain development." },
  { id:"gen_r203", subject:"general-agriculture", question:"K-9107 wheat variety is recommended for:", options:["Rainfed upland conditions in field conditions", "Very late sowing only", "Waterlogged conditions in crop production", "Timely sown, irrigated conditions in peninsular India"], correct:3, explanation:"K-9107 (released by CSAUAT, Kanpur) is recommended for timely sown, irrigated conditions in the Peninsular Zone (Telangana, Andhra, Karnataka, Maharashtra). It has good grain quality and moderate resistance to rusts." },
  { id:"gen_r204", subject:"general-agriculture", question:"The average national productivity of wheat in India is approximately:", options:["5.0 t/ha", "2.0 t/ha", "1.5 t/ha", "3.2 t/ha"], correct:0, explanation:"India's national average wheat yield is approximately 3.2–3.5 t/ha. Punjab and Haryana achieve 4.5–5.0 t/ha with full packages; central and peninsular India average 2.5–3.0 t/ha due to heat stress at grain fill." },
  { id:"gen_r205", subject:"general-agriculture", question:"Seed treatment of wheat before sowing with Carboxin or Thiram is done to:", options:["Fix atmospheric nitrogen in the soil in crop production", "Repel rodents from the field in field conditions", "Improve germination rate by hormone treatment for agricultural purposes", "Control seed-borne diseases like Karnal bunt, loose smut and flag smut"], correct:3, explanation:"Seed treatment with systemic fungicides (Carboxin 37.5% + Thiram 37.5% @ 3 g/kg seed) controls seed-borne fungal diseases like Loose smut (Ustilago segetum var. tritici), Karnal bunt (Tilletia indica) and Flag smut. This is done before Rhizobium inoculation." },
  { id:"gen_r206", subject:"general-agriculture", question:"The tillering stage in wheat is important because:", options:["It is when deep root growth stops in crop production", "It determines the number of productive shoots and hence yield components", "It is when rusts first appear for agricultural purposes", "It determines the final plant height in field conditions"], correct:1, explanation:"Tillering determines the number of productive tillers per plant, which directly determines the number of ears and thus yield. Adequate N and moisture during tillering (25–40 DAS) promotes maximum tillering and yield potential." },
  { id:"gen_r207", subject:"general-agriculture", question:"JG-11 is an improved variety of:", options:["Lentil", "Cowpea", "Chickpea (Bengal gram)", "Pea"], correct:2, explanation:"JG-11 (Jawaharlal Gram 11) is an improved chickpea (Bengal gram/Cicer arietinum) variety developed by JNKVV, Jabalpur. It is recommended for Central India and is known for bold seeds, good yield and resistance to wilt." },
  { id:"gen_r208", subject:"general-agriculture", question:"The recommended seed rate for chickpea is:", options:["60–75 kg/ha", "30–40 kg/ha", "100–120 kg/ha", "150 kg/ha"], correct:0, explanation:"Chickpea seed rate is 60–75 kg/ha depending on seed size. Small-seeded desi varieties need 60 kg/ha and bold kabuli types need up to 90 kg/ha. Higher seed rates are used for late sowing to compensate for reduced plant growth." },
  { id:"gen_r209", subject:"general-agriculture", question:"Rhizobium inoculation of chickpea seed is recommended because:", options:["It promotes biological N fixation through root nodule bacteria, reducing fertiliser N requirement", "It increases seed size in crop production in agriculture under standard field conditions", "It controls pod borer attack in field conditions under field conditions under standard field conditions", "It improves germination speed for agricultural purposes for crop production under standard field conditions"], correct:0, explanation:"Chickpea is nodulated by Mesorhizobium ciceri. Inoculation with the specific Rhizobium culture fixes atmospheric N2 biologically (50–150 kg N/ha), reducing the need for chemical N fertiliser by up to 60–80% and improving soil fertility." },
  { id:"gen_r210", subject:"general-agriculture", question:"The critical irrigation stage for chickpea is:", options:["Maturity/harvest stage", "Pre-flowering stage", "Pod filling (seed development) stage", "Seed germination (immediately after sowing)"], correct:2, explanation:"The most critical irrigation in chickpea is at pod filling stage (when seeds are developing inside pods). Water stress at this stage causes pod abortion and grain shrivelling, severely reducing yield. One pre-flowering irrigation also helps." },
  { id:"gen_r211", subject:"general-agriculture", question:"ICCC-37 is a:", options:["Lentil variety", "Sunflower hybrid", "Mustard variety", "Kabuli-type chickpea variety"], correct:3, explanation:"ICCC-37 is a kabuli (large, cream-coloured seeded) chickpea variety released from ICRISAT, Patancheru. Kabuli chickpea commands premium prices in export markets. India grows mainly desi type but kabuli export is growing." },
  { id:"gen_r212", subject:"general-agriculture", question:"Helicoverpa armigera (pod borer) is the most serious pest of chickpea. The recommended control measure is:", options:["Only furadan granules in soil in field conditions under standard field conditions", "No control needed as damage is minimal based on conventional agronomic practices", "Ploughing only in crop production in the context of integrated farming systems", "HaNPV (nuclear polyhedrosis virus) spray or chemical insecticides like indoxacarb/emamectin"], correct:3, explanation:"Helicoverpa pod borer is the most destructive pest of chickpea causing 50–100% loss. Integrated management includes HaNPV (Helicoverpa armigera NPV) biopesticide (250 LE/ha), pheromone traps, and chemical insecticides like indoxacarb 14.5 SC at 0.5 mL/L." },
  { id:"gen_r213", subject:"general-agriculture", question:"Lentil (Lens culinaris) belongs to which family?", options:["Poaceae (grass family)", "Cruciferae (Brassicaceae)", "Leguminosae (Fabaceae – legume family)", "Solanaceae"], correct:2, explanation:"Lentil belongs to the family Leguminosae (Fabaceae), subfamily Papilionoideae. Like all legumes, it forms root nodules with Rhizobium for biological nitrogen fixation. It is a cool-season rabi crop." },
  { id:"gen_r214", subject:"general-agriculture", question:"NBeG-3 is a variety of:", options:["Grass pea", "Lentil", "Chickpea", "Field pea"], correct:2, explanation:"NBeG-3 (Nandyal Bengal gram 3) is a chickpea variety recommended for Telangana and Andhra Pradesh. It is a desi-type with short duration and good yield under southern conditions." },
  { id:"gen_r215", subject:"general-agriculture", question:"Chickpea (desi) is predominantly grown in which soil type?", options:["Heavy clay waterlogged soils", "Sandy loam, well-drained soils", "Saline-sodic soils", "Acidic laterite soils"], correct:1, explanation:"Chickpea grows best in sandy loam to loam, well-drained soils with pH 6.0–7.5. It is very sensitive to waterlogging. Heavy clay soils with poor drainage cause root rot. Medium black soils (deep Vertisols) with good drainage also suit chickpea." },
  { id:"gen_r216", subject:"general-agriculture", question:"The average yield of chickpea in India under irrigated conditions is approximately:", options:["3000–4000 kg/ha", "1500–2000 kg/ha", "500–700 kg/ha", "800–1000 kg/ha"], correct:1, explanation:"Chickpea yield under irrigated conditions with proper management is 1500–2000 kg/ha. National average is only 800–900 kg/ha due to rainfed conditions, pest damage and poor inputs. Improved varieties under irrigation can yield 2.5–3.0 t/ha." },
  { id:"gen_r217", subject:"general-agriculture", question:"Wilt disease of chickpea is caused by:", options:["Fusarium oxysporum f.sp. ciceri (fungus)", "Cassava mosaic virus", "Helicoverpa armigera (insect)", "Xanthomonas citri (bacteria)"], correct:0, explanation:"Chickpea wilt is caused by the soilborne fungus Fusarium oxysporum f.sp. ciceri. It is a major constraint in chickpea production. Management includes wilt-resistant varieties (JG-11), Trichoderma seed treatment and crop rotation." },
  { id:"gen_r218", subject:"general-agriculture", question:"Lentil is most commonly cultivated in which Indian states?", options:["Tamil Nadu and Kerala", "Assam and Manipur", "Madhya Pradesh and Uttar Pradesh", "Gujarat and Rajasthan"], correct:2, explanation:"Lentil is predominantly grown in Madhya Pradesh, Uttar Pradesh, Bihar and Rajasthan. MP alone contributes >55% of India's lentil production. India is the world's second largest lentil producer after Canada." },
  { id:"gen_r219", subject:"general-agriculture", question:"Chickpea is photoperiod-sensitive. It is primarily a:", options:["Day-neutral plant", "Long day plant", "Short day plant", "Obligate short day plant"], correct:1, explanation:"Chickpea is a long day plant – flowering is promoted by long days (photoperiods >12 hours). However, desi varieties are less sensitive than kabuli. This explains why chickpea is grown in winter (short days initially for vegetative growth, then longer days induce flowering)." },
  { id:"gen_r220", subject:"general-agriculture", question:"The protein content of chickpea (Bengal gram) seeds is approximately:", options:["10–12%", "15–20%", "35–40%", "21–25%"], correct:3, explanation:"Chickpea seeds contain approximately 21–25% crude protein (on dry weight basis), making them an important plant protein source in vegetarian diets. They are also rich in carbohydrates (50–55%), fibre, minerals and B-vitamins." },
  { id:"gen_r221", subject:"general-agriculture", question:"Phosphorus is applied to chickpea/lentil at the time of:", options:["During irrigation", "Top dressing at 30 DAS", "Foliar spray at flowering", "Basal application at sowing"], correct:3, explanation:"Phosphorus (20–40 kg P₂O₅/ha) is applied as basal dose at sowing. Phosphorus improves root nodule development, early root growth and pod setting. Full P dose is always applied at sowing as it is immobile in soil." },
  { id:"gen_r222", subject:"general-agriculture", question:"The sowing time for chickpea in Telangana/Andhra Pradesh is:", options:["February–March", "October–November", "August–September", "June–July"], correct:1, explanation:"Chickpea is a rabi crop sown in October–November in Telangana. Sowing after mid-November increases the risk of heat stress during pod filling (February–March) leading to lower yields." },
  { id:"gen_r223", subject:"general-agriculture", question:"Pusa Bold is a variety of:", options:["Safflower", "Rapeseed (Brassica napus)", "Indian mustard (Brassica juncea)", "Sunflower"], correct:2, explanation:"Pusa Bold (NB-9-3) is a high-yielding variety of Indian mustard (Brassica juncea) released by IARI, New Delhi. It is bold-seeded (large seed size), early maturing and widely grown in North India for its high oil content." },
  { id:"gen_r224", subject:"general-agriculture", question:"Recommended seed rate for mustard cultivation is:", options:["5–6 kg/ha", "1–2 kg/ha", "20–25 kg/ha", "10–12 kg/ha"], correct:0, explanation:"Mustard is sown at 5–6 kg/ha (line sowing) or up to 10 kg/ha (broadcast). The small seed size means even this low rate gives adequate plant population. Seed should be treated with Thiram @ 2.5 g/kg before sowing." },
  { id:"gen_r225", subject:"general-agriculture", question:"The recommended spacing for mustard cultivation is:", options:["15×5 cm", "45×15 cm", "60×30 cm", "30×10 cm"], correct:1, explanation:"Standard spacing for mustard is 45 cm between rows × 15 cm between plants (after thinning). Row spacing of 30–45 cm allows intercultivation and ensures adequate light penetration to the lower canopy." },
  { id:"gen_r226", subject:"general-agriculture", question:"The recommended nitrogen dose for mustard cultivation is approximately:", options:["80 kg N/ha", "120 kg N/ha", "160 kg N/ha", "40 kg N/ha"], correct:0, explanation:"80 kg N/ha is recommended for irrigated mustard. N is applied in two splits: half as basal + half at first irrigation (25–30 DAS). This promotes good vegetative growth and higher oil content." },
  { id:"gen_r227", subject:"general-agriculture", question:"Mustard (Brassica juncea) is primarily a:", options:["Cross-pollinated crop (insects, especially bees)", "Wind-pollinated crop only under standard field conditions", "Vegetatively propagated crop under standard field conditions", "Self-pollinated crop under standard field conditions"], correct:0, explanation:"Indian mustard (B. juncea) is predominantly cross-pollinated by insects, especially honey bees. Approximately 85–90% cross-pollination occurs. This is why placing bee hives in mustard fields increases seed set and yield by 20–30%." },
  { id:"gen_r228", subject:"general-agriculture", question:"Which mustard variety is known for low erucic acid (double zero/canola quality)?", options:["Pusa Jaikisan (Varuna)", "Kranti", "Pusa Bold", "RH-30"], correct:0, explanation:"Pusa Jaikisan (based on Varuna cross) and RH-30 have improved fatty acid profiles. However, proper 'double zero' (low erucic acid + low glucosinolate = canola quality) mustard varieties have been developed more recently. Kranti is standard high-erucic type." },
  { id:"gen_r229", subject:"general-agriculture", question:"The oil content of Indian mustard seeds is approximately:", options:["15–20%", "25–30%", "55–60%", "38–44%"], correct:3, explanation:"Indian mustard (Brassica juncea) seeds contain 38–44% oil (on dry weight basis). This makes it the primary edible oil crop of North India. Oil content is also influenced by variety, growing conditions and seed maturity." },
  { id:"gen_r230", subject:"general-agriculture", question:"The most critical irrigation stage for mustard is:", options:["After pod maturity under standard field conditions", "Germination stage under standard field conditions", "Pre-flowering (rosette) and flowering stage", "Pre-sowing irrigation only under standard field conditions"], correct:2, explanation:"Mustard is most sensitive to drought at pre-flowering and flowering (siliqua initiation) stages. Irrigation at these stages is critical for pod set and seed fill. Generally 2–3 irrigations are given: at 25–30 DAS and at flowering (55–60 DAS)." },
  { id:"gen_r231", subject:"general-agriculture", question:"The variety RH-30 is a:", options:["Safflower variety in crop production", "Sunflower hybrid in field conditions", "Rapeseed (Brassica napus) variety", "Indian mustard (Brassica juncea) variety from Haryana"], correct:3, explanation:"RH-30 (Rohtak Hybrid 30) is an Indian mustard (B. juncea) variety developed by CCS HAU, Hisar, Haryana. It is an early-maturing variety suitable for limited moisture conditions and is widely grown in Haryana and Rajasthan." },
  { id:"gen_r232", subject:"general-agriculture", question:"The major pest of mustard crop is:", options:["Brown plant hopper", "Leaf roller", "Aphids (Lipaphis erysimi)", "Helicoverpa armigera"], correct:2, explanation:"Mustard aphid (Lipaphis erysimi) is the most serious pest of mustard, capable of causing 10–70% yield loss. Aphids suck plant sap from tender shoots and pods. Spraying with imidacloprid or dimethoate at ETL (76 aphids/6 cm terminal shoot) is recommended." },
  { id:"gen_r233", subject:"general-agriculture", question:"Brassica napus (rapeseed) differs from B. juncea (Indian mustard) in that B. napus:", options:["Is exclusively grown in south India in crop production under standard field conditions", "Has more pungent oil and is preferred in India under standard field conditions", "Is tetraploid (AACC genome, 2n=38) and produces canola-quality oil with low erucic acid", "Is purely self-pollinated with very low yield in field conditions under standard field conditions"], correct:2, explanation:"B. napus (rapeseed) is a tetraploid (2n=38, AACC) and is the source of canola (low erucic acid + low glucosinolate) oil, widely grown in Europe and Canada. B. juncea (Indian mustard, 2n=36, AABB) is the major Indian oilseed, has higher erucic acid and pungent flavour." },
  { id:"gen_r234", subject:"general-agriculture", question:"The sowing time for mustard in North India (Punjab, Haryana, Rajasthan) is:", options:["September–October (before wheat)", "February–March", "June–July", "November–December"], correct:0, explanation:"Mustard is sown in September–October in North India (earlier than wheat) to utilise the cooler days optimally. Early sowing avoids aphid attack and heat stress during grain filling. In Telangana, rabi mustard is sown in November." },
  { id:"gen_r235", subject:"general-agriculture", question:"The siliqua (pod) of mustard typically matures in how many days from sowing?", options:["90–110 days", "160–180 days", "130–150 days", "45–60 days"], correct:0, explanation:"Mustard is a short-duration rabi crop maturing in 90–110 days (early varieties) to 130–140 days (late varieties). This allows it to be harvested before wheat needs the field, making it an ideal rabi crop in rotations." },
  { id:"gen_r236", subject:"general-agriculture", question:"The Kranti variety of mustard is known for:", options:["Medium duration, high yield and tolerance to late sowing", "Very small seed size and low oil content", "Exclusive suitability for south India only", "Very late maturity and high water requirement"], correct:0, explanation:"Kranti is a popular Indian mustard variety (B. juncea) with medium duration (125–135 days), high yield potential (2.0–2.5 t/ha under irrigation) and reasonable adaptability to late sowing. It is grown in MP, Rajasthan and UP." },
  { id:"gen_r237", subject:"general-agriculture", question:"In mustard/rapeseed, thinning is done at:", options:["At flowering stage in crop production", "15–20 DAS, leaving one plant every 15 cm within the row", "Sowing time itself by using low seed rate only", "No thinning is required in field conditions"], correct:1, explanation:"Thinning (roguing excess seedlings) is done at 15–20 DAS when seedlings are 10–15 cm tall, maintaining 15 cm plant-to-plant distance within rows (at 45 cm row spacing). Dense stands cause lodging, poor pollination and reduced yield." },
  { id:"gen_r238", subject:"general-agriculture", question:"White rust (Albugo candida) causes serious damage to mustard by affecting:", options:["Leaves, stems, flowers and siliquae causing distortion and yield loss", "Only seeds reducing oil quality in field conditions", "Root nodules reducing nitrogen fixation in crop production", "Roots and stem base causing wilt for agricultural purposes"], correct:0, explanation:"White rust (Albugo candida) causes white blistered pustules on leaves, stems, flowers and siliquae of mustard. The fungus causes 'staghead' deformity of floral parts, severely reducing seed set and yield. Spraying Metalaxyl + Mancozeb controls it." },
  { id:"gen_r239", subject:"general-agriculture", question:"The average yield of castor hybrid in Telangana under irrigated conditions is approximately:", options:["1500–2000 kg/ha", "5000 kg/ha", "500–800 kg/ha", "2500–3500 kg/ha"], correct:3, explanation:"Improved castor hybrids (DCH-177, GCH-4) yield 2500–3500 kg/ha under irrigated conditions with recommended inputs. Rainfed castor yields 1000–1500 kg/ha. National average is around 1300–1400 kg/ha." },
  { id:"gen_r240", subject:"general-agriculture", question:"The recommended seed rate for linseed (Linum usitatissimum) is:", options:["60 kg/ha", "30 kg/ha", "100 kg/ha", "10 kg/ha"], correct:1, explanation:"Linseed is sown at 30 kg/ha for line sowing (22.5–30 cm rows). Small seed size requires careful depth control (2–3 cm). Seed rate can be reduced to 20–25 kg/ha with seed treatment and good seedbed." },
  { id:"gen_r241", subject:"general-agriculture", question:"The Gaurav variety of linseed is known for:", options:["High seed yield and oil content, suitable for Central India", "Very long fibres suitable for linen in crop production", "Resistance to all rusts in field conditions", "Extra-early maturity in <60 days for agricultural purposes"], correct:0, explanation:"Gaurav is a high-yielding linseed variety recommended for Central India (MP, UP, Bihar, Rajasthan). It has good oil content (39–42%) and is suited for rabi season under limited irrigation." },
  { id:"gen_r242", subject:"general-agriculture", question:"Linseed oil is rich in which fatty acid?", options:["Alpha-linolenic acid (ALA, omega-3)", "Lauric acid (saturated)", "Ricinoleic acid", "Erucic acid"], correct:0, explanation:"Linseed (flaxseed) oil is exceptionally rich in alpha-linolenic acid (ALA, an omega-3 fatty acid) at 50–60% of total fatty acids. This makes it valuable for health supplements and industrial drying oil (paints, varnishes)." },
  { id:"gen_r243", subject:"general-agriculture", question:"Niger (Guizotia abyssinica) or ramtil is mainly grown in:", options:["Punjab and Haryana as a rabi crop in crop production under standard field conditions", "Tamil Nadu paddy fallows in field conditions in agriculture under standard field conditions", "Gujarat as an irrigated crop for agricultural purposes under field conditions", "Tribal and upland areas of Chhattisgarh, Odisha, and Jharkhand as a kharif/pre-rabi crop"], correct:3, explanation:"Niger (ramtil) is primarily grown in tribal upland areas of Chhattisgarh, Odisha, Jharkhand, Maharashtra and Andhra Pradesh. It is a hardy crop adapted to shallow, poor, and laterite soils with very low inputs." },
  { id:"gen_r244", subject:"general-agriculture", question:"Indira Niger-1 is a variety of:", options:["Niger (Guizotia abyssinica / ramtil)", "Sunflower in field conditions", "Safflower in crop production", "Sesame for agricultural purposes"], correct:0, explanation:"Indira Niger-1 is an improved variety of niger (ramtil, Guizotia abyssinica) released from IGAU, Raipur (Chhattisgarh). Niger seeds contain 35–40% oil with good edible oil quality and yield 400–600 kg/ha under dryland conditions." },
  { id:"gen_r245", subject:"general-agriculture", question:"The T-397 variety of linseed was developed at:", options:["UAS Dharwad", "CSAUAT, Kanpur", "GBPUAT, Pantnagar", "ICAR-NIANP Bangalore"], correct:1, explanation:"T-397 (Terai 397) is a linseed variety developed by CSAUAT (now CSAUA&T), Kanpur, Uttar Pradesh. It is an older but still-relevant variety recommended for UP, Bihar and Jharkhand conditions." },
  { id:"gen_r246", subject:"general-agriculture", question:"The dual-purpose use of linseed refers to:", options:["Both seed (oil) and stalk (fibre/linen) utilization in the same crop", "Both cooking oil and biodiesel in crop production", "Both human food and animal feed from seed only", "Both kharif and rabi season sowing in field conditions"], correct:0, explanation:"Linseed (flax) is a dual-purpose crop: (1) Oil type – selected for maximum seed yield and oil; (2) Fibre type – selected for long, strong bast fibres from the stem (flax fibre = linen). Some varieties are intermediate (multipurpose)." },
  { id:"gen_r247", subject:"general-agriculture", question:"Linseed rust, caused by Melampsora lini, can be managed by:", options:["Flooding the field repeatedly in crop production under standard field conditions", "Removing all plant residues by burning only in field conditions under standard field conditions", "Copper fungicide sprays only for agricultural purposes under standard field conditions", "Using resistant varieties, seed treatment and foliar sprays of Zineb or Mancozeb"], correct:3, explanation:"Linseed rust (Melampsora lini) is a major foliar disease. Management includes: use of rust-resistant varieties (Gaurav, T-397 are moderately resistant), Zineb or Mancozeb sprays at 15-day intervals, removal and burning of infected crop debris." },
  { id:"gen_r248", subject:"general-agriculture", question:"The major producing states of linseed in India are:", options:["Rajasthan and Gujarat under standard field conditions", "Madhya Pradesh, Chhattisgarh, Bihar and UP", "Punjab, Haryana, UP under standard field conditions", "Karnataka and Tamil Nadu under standard field conditions"], correct:1, explanation:"Madhya Pradesh, Chhattisgarh, Uttar Pradesh and Bihar are the major linseed-growing states of India. Linseed occupies small areas mainly as an intercrop with wheat or on residual moisture soils." },
  { id:"gen_r249", subject:"general-agriculture", question:"The oil content of linseed seeds is approximately:", options:["25–30%", "38–45%", "55–65%", "15–20%"], correct:1, explanation:"Linseed seeds contain 38–45% oil. The oil is a semi-drying to drying oil due to high ALA content. Beyond edible use, linseed oil is extensively used industrially in paints, varnishes, linoleum, putty, and printing inks." },
  { id:"gen_r250", subject:"general-agriculture", question:"Powdery mildew of linseed is caused by:", options:["Fusarium oxysporum", "Phytophthora infestans", "Alternaria lini", "Oidium lini"], correct:3, explanation:"Powdery mildew of linseed is caused by Oidium lini. White powdery growth appears on leaves and stems. It is managed by sulphur-based fungicide sprays. Alternaria lini causes pasmo disease (leaf spotting and stem cankering)." },
  { id:"gen_r251", subject:"general-agriculture", question:"Niger crop is typically sown at a very low seed rate of:", options:["5–8 kg/ha", "30–35 kg/ha", "15–20 kg/ha", "0.5–1 kg/ha"], correct:3, explanation:"Niger has extremely small seeds (1000 seed weight = 3–4 g) and is sown at 0.5–1 kg/ha in broadcast or 1–2 kg/ha in line sowing. This small quantity gives adequate plant population because of the tiny seed size." },
  { id:"gen_r252", subject:"general-agriculture", question:"Flaxseed (linseed) is increasingly used as a health food ingredient because:", options:["It has the highest protein content of any oilseed in crop production under standard field conditions", "It is used as natural sweetener in field conditions under standard field conditions", "It is rich in omega-3 ALA, dietary fibre (mucilage) and lignans with anti-cancer properties", "It contains high starch for energy for agricultural purposes under standard field conditions"], correct:2, explanation:"Flaxseed is a functional food: rich in alpha-linolenic acid (omega-3, 50–60% of oil), soluble fibre (mucilage in seed coat), and plant lignans (SDG) that have demonstrated antioxidant and potential anti-cancer properties in research." },
  { id:"gen_r253", subject:"general-agriculture", question:"The crop duration of linseed is approximately:", options:["130–160 days", "180–200 days", "90–120 days", "45–60 days"], correct:2, explanation:"Linseed is a medium-duration rabi crop maturing in 90–120 days depending on variety and season. Early varieties mature in 90–100 days; late varieties may take 110–120 days. This fits well in wheat-linseed rotation in Central India." },
  { id:"gen_r254", subject:"general-agriculture", question:"When linseed and lentil are grown as intercrop, what is the typical row arrangement?", options:["Broadcast mixture with no defined ratio", "1:1 (one row linseed, one row lentil)", "Linseed as border crop only", "2:1 or 4:2 (linseed: lentil)"], correct:3, explanation:"Linseed–lentil intercropping in 2:1 or 4:2 row arrangement (linseed:lentil) is common in Central India. The legume (lentil) fixes nitrogen benefiting the companion crop, and the mixture reduces overall pest/disease pressure." },
  { id:"gen_r255", subject:"general-agriculture", question:"In which state is niger crop locally called 'Ramtil'?", options:["Assam under standard field conditions", "Chhattisgarh and Jharkhand", "Kerala under standard field conditions", "Punjab under standard field conditions"], correct:1, explanation:"Niger is locally known as 'Ramtil' in Chhattisgarh, Jharkhand and parts of Odisha. It is also called 'Sarguja' in Chhattisgarh. In Karnataka and Maharashtra it is called 'Uchhelu' or 'Kadu hesaru'." },
  { id:"gen_r256", subject:"general-agriculture", question:"Co-86032 is a popular sugarcane variety known for:", options:["Suitability for rainfed conditions only under standard field conditions", "Poor milling quality but high yield under standard field conditions", "Very high sucrose content, good yield and wide adaptability", "Very short crop duration of 6 months under standard field conditions"], correct:2, explanation:"Co-86032 is one of the most widely cultivated sugarcane varieties in South India (Telangana, AP, Karnataka, Tamil Nadu). It has high cane yield (300–400 q/ha), good sucrose content (CCS 10–11%), good ratoon-ability and ratooning ability." },
  { id:"gen_r257", subject:"general-agriculture", question:"Pyrilla (sugarcane leafhopper) is an important pest of sugarcane. Its biological control agent is:", options:["Trichoderma viride", "Epiricania melanoleuca (an egg parasite", "Chrysoperla carnea", "Bacillus thuringiensis"], correct:1, explanation:"Pyrilla (Pyrilla perpusilla) is effectively controlled by the biological agent Epiricania melanoleuca, a parasite whose larvae feed on Pyrilla egg masses. Mass releases of Epiricania are done in India as a classical biocontrol success story." },
  { id:"gen_r258", subject:"general-agriculture", question:"The Napier-Bajra hybrid (NB-21) is a cross between:", options:["Sorghum × Maize in crop production under standard field conditions", "Berseem × Oat in field conditions under standard field conditions", "Napier grass (Pennisetum purpureum) × Pearl millet (Pennisetum glaucum)", "Oat × Barley for agricultural purposes under standard field conditions"], correct:2, explanation:"NB-21 is the interspecific hybrid between Napier grass (Pennisetum purpureum, elephant grass) and pearl millet (Pennisetum glaucum). It combines the high biomass of Napier with the palatability and nutritive value of pearl millet." },
  { id:"gen_r259", subject:"general-agriculture", question:"Berseem (Trifolium alexandrinum) is an important rabi fodder crop because:", options:["It grows only in waterlogged conditions in paddy season in crop production under standard field conditions", "It is a perennial crop that requires no replanting for 10 years under standard field conditions", "It is a legume that fixes N, produces high-quality protein-rich green fodder and can be multi-cut", "It is a cereal with high energy content in field conditions under standard field conditions"], correct:2, explanation:"Berseem (Egyptian clover) is a high-quality legume fodder with 18–22% crude protein. It can be cut 4–6 times per season (multi-cut), fixes atmospheric nitrogen (80–100 kg N/ha), and improves soil fertility. It is the most important rabi fodder in North India." },
  { id:"gen_r260", subject:"general-agriculture", question:"The oat variety Kent is primarily grown as:", options:["Green fodder oat with high yield and good palatability for livestock", "Oil crop for omega-3 extraction in field conditions", "Industrial oat for paper pulp in crop production", "Grain oat for human consumption for agricultural purposes"], correct:0, explanation:"Kent is a popular green-fodder oat variety grown during rabi season in India. Oat fodder is highly palatable, nutritious and can be cut 2–3 times. It is important for dairy farmers in North and Peninsular India during winter." },
  { id:"gen_r261", subject:"general-agriculture", question:"FC-1 is a fodder cowpea variety. Its main advantage is:", options:["Tolerance to frost in crop production in agriculture", "Suitability for rabi season only in field conditions under field conditions", "High green fodder yield with good protein content (18–22%) in a short duration", "Very high seed yield for grain production for agricultural purposes"], correct:2, explanation:"FC-1 (Fodder Cowpea 1) produces high green fodder yield in a short duration (60–70 days). Cowpea is a legume fodder with 18–22% crude protein, improving livestock milk production and growth rates. It is grown in both kharif and summer seasons." },
  { id:"gen_r262", subject:"general-agriculture", question:"The sorghum variety S-1049 is recommended for:", options:["Grain production with bold seeds", "Seed spice production", "Sugar extraction like sugarcane", "High green fodder yield in kharif season"], correct:3, explanation:"S-1049 (Sorghum for fodder) is a dual-purpose or dedicated fodder sorghum variety with high tillering ability for multi-cut green fodder production. It gives 400–500 q/ha green fodder in kharif season over 3–4 cuts." },
  { id:"gen_r263", subject:"general-agriculture", question:"The 'Jowar-Cowpea' intercropping system is popular for fodder because:", options:["Both fix nitrogen equally in crop production in agriculture in the context of integrated farming systems", "No mixing of protein and carbohydrates is needed in animal feed under field conditions under standard field conditions", "Jowar supplies energy and structural carbohydrates; cowpea fixes N and supplies protein, improving overall fodder quality", "Jowar supplies protein; cowpea supplies energy in field conditions for crop production under standard field conditions"], correct:2, explanation:"Sorghum (jowar) is a high-yielding cereal fodder rich in energy but low in protein. Intercropping with cowpea (a legume) adds protein (18–22% CP in cowpea vs 7–9% in sorghum alone), gives a balanced ration, and cowpea also fixes 50–80 kg N/ha." },
  { id:"gen_r264", subject:"general-agriculture", question:"Napier-Bajra hybrid (NB-21) is propagated vegetatively using:", options:["Rhizomes from mother plant", "Root pieces in crop production", "Stem cuttings or slips (3–4 node sections)", "Seeds only in field conditions"], correct:2, explanation:"NB-21 hybrid is sterile (triploid-like interspecific hybrid) and does not produce viable seeds. It is propagated vegetatively by stem cuttings (3–4 node sections) or rooted slips. Cuttings are planted in furrows at 60–90 cm spacing." },
  { id:"gen_r265", subject:"general-agriculture", question:"At what crop stage should jowar (sorghum) fodder be harvested for maximum nutritive value?", options:["Flowering (anthesis) stage when crude protein is still high", "At full physiological maturity when DM content is maximum", "At 50% flowering stage", "When 50–75% of heads are in milk/early dough stage"], correct:3, explanation:"Fodder sorghum is harvested at 50–75% head formation to milk stage for optimum balance of yield (DM), digestibility, and palatability. Harvesting too early gives good quality but low yield; too late (grain stage) reduces digestibility." },
  { id:"gen_r266", subject:"general-agriculture", question:"Prussic acid (HCN) poisoning in livestock fed on sorghum fodder occurs when:", options:["Young, stressed (drought, frost) or regrowth sorghum plants are fed as there is high dhurrin content", "Silage-preserved sorghum is fed in field conditions under field conditions", "Plants are fully mature with high dry matter in crop production in agriculture", "Plants are harvested at flowering stage for agricultural purposes for crop production"], correct:0, explanation:"Young sorghum plants and regrowth (ratoon) shoots contain high dhurrin (cyanogenic glucoside) that hydrolyses to HCN under stress (drought, frost, nutrient deficiency). HCN causes prussic acid poisoning in livestock. Silage fermentation destroys most HCN." },
  { id:"gen_r267", subject:"general-agriculture", question:"The recommended seed rate for berseem fodder is:", options:["20–25 kg/ha", "50–60 kg/ha", "5 kg/ha", "100 kg/ha"], correct:0, explanation:"Berseem is sown at 20–25 kg/ha broadcast in a well-prepared, fine-tilled seedbed after mixing with 3–4 times sand for uniform distribution. The small seed (1000 seed weight = 3.5 g) requires a very fine, firm seedbed for good germination." },
  { id:"gen_r268", subject:"general-agriculture", question:"Which fodder crop is known as the 'Queen of Fodder Crops' in India?", options:["Cowpea under standard field conditions", "Oat under standard field conditions", "Sorghum under standard field conditions", "Berseem (Trifolium alexandrinum)"], correct:3, explanation:"Berseem (Trifolium alexandrinum) is called the 'Queen of Fodder Crops' in India because of its excellent nutritive value, palatability, high protein content (18–22% CP), multi-cut ability, nitrogen-fixing ability, and high green fodder yield." },
  { id:"gen_r269", subject:"general-agriculture", question:"What is the average green fodder yield of Napier-Bajra hybrid NB-21 per year?", options:["300–400 t/ha/year", "50–80 t/ha/year", "100–250 t/ha/year", "20–30 t/ha/year"], correct:2, explanation:"NB-21 Napier-Bajra hybrid is one of the highest-yielding perennial fodder crops, producing 100–250 tonnes of green fodder per hectare per year over 6–8 cuts annually. This extraordinary yield potential makes it indispensable for dairy farms." },
  { id:"gen_r270", subject:"general-agriculture", question:"Stylosanthes hamata (stylo) is a tropical legume fodder used for:", options:["Coffee shade plant in crop production in agriculture", "Irrigated cultivation only in field conditions under field conditions", "Dryland/rangeland improvement and as a protein bank for cattle grazing", "Making silage only for agricultural purposes for crop production"], correct:2, explanation:"Stylosanthes (stylo) is a drought-hardy tropical legume used to improve degraded pastures and rangeland. It establishes on poor, acidic soils, fixes nitrogen (80–100 kg N/ha), provides nutritious protein-rich fodder even in dry conditions." },
  { id:"gen_r271", subject:"general-agriculture", question:"The fenugreek variety RMt-1 (Rajasthan Methi-1) was developed at:", options:["KAU, Thrissur", "UAS, Dharwad", "IARI, New Delhi", "SKRAU, Bikaner, Rajasthan"], correct:3, explanation:"RMt-1 (Rajasthan Methi-1) was developed by SKN College of Agriculture (under SKRAU), Jobner/Bikaner, Rajasthan. Rajasthan is the largest fenugreek (methi) producing state, with Sikar, Nagaur and Rajsamand as major districts." },
  { id:"gen_r272", subject:"general-agriculture", question:"The sowing time for fenugreek (methi) in Rajasthan for rabi season is:", options:["June–July", "March–April", "September–November", "January–February"], correct:2, explanation:"Fenugreek is sown in September–November in Rajasthan and North India as a rabi crop. In Telangana it is sown in October–November. Early sowing (September–October) gives maximum seed yield; later sowing gives more green leaf (methi) yield." },
  { id:"gen_r273", subject:"general-agriculture", question:"Granville wilt (bacterial wilt) of tobacco is caused by:", options:["Phytophthora nicotianae (oomycete)", "Ralstonia solanacearum (bacterium)", "Tobacco mosaic virus (TMV)", "Fusarium oxysporum (fungus)"], correct:1, explanation:"Granville wilt (southern bacterial wilt) is caused by Ralstonia solanacearum, a soilborne bacterium that colonises the vascular system. Diagnosis: dip cut stem end in water – milky bacterial streaming. Management: resistant varieties, crop rotation, soil solarisation." },
  { id:"gen_r274", subject:"general-agriculture", question:"Blue mould of tobacco in seedbeds is caused by:", options:["Cercospora nicotianae (fungus)", "Phytoplasma", "Peronospora tabacina (oomycete)", "Tobacco etch virus (TEV)"], correct:2, explanation:"Blue mould of tobacco is caused by Peronospora tabacina, a downy mildew pathogen (oomycete). It appears as blue-grey sporulation on the underside of leaves. Metalaxyl or dimethomorph fungicides control blue mould in tobacco seedbeds." },
  { id:"gen_r275", subject:"general-agriculture", question:"The National Food Security Act (NFSA) in India was enacted in:", options:["2010", "2013", "2016", "2005"], correct:1, explanation:"The National Food Security Act (NFSA) was enacted in 2013. It provides legal right to subsidised food grains to approximately 75% rural and 50% urban population — covering about 67% of India's total population." },
  { id:"gen_r276", subject:"general-agriculture", question:"The Minimum Support Price (MSP) is announced by:", options:["State Agriculture Departments after consulting district-level farmer advisory bodies", "Farmer producer organisations based on aggregated production cost survey data", "NABARD after evaluating crop production costs in consultation with state governments", "Central government based on CACP recommendations"], correct:3, explanation:"The Minimum Support Price (MSP) is announced by the Central Government based on recommendations of the Commission for Agricultural Costs and Prices (CACP). It ensures remunerative prices to farmers and food security." },
  { id:"gen_r277", subject:"general-agriculture", question:"The Green Revolution in India is associated with which period?", options:["Early 1950s post-independence period", "1980s liberalisation decade", "1990s economic reforms period", "Late 1960s and 1970s"], correct:3, explanation:"The Green Revolution in India occurred in the late 1960s and 1970s. It was driven by introduction of HYV seeds (wheat, rice), chemical fertilizers, irrigation, and pesticides. It made India self-sufficient in food grains." },
  { id:"gen_r278", subject:"general-agriculture", question:"The government scheme that provides crop insurance to farmers in India is:", options:["MNREGA in the agricultural economy", "Pradhan Mantri Fasal Bima Yojana (PMFBY)", "Kisan Credit Card", "PM-KISAN in rural economic context"], correct:1, explanation:"Pradhan Mantri Fasal Bima Yojana (PMFBY) was launched in 2016 to provide comprehensive crop insurance against natural calamities. Premium is subsidised — farmers pay 1.5–2% for rabi and 2% for kharif crops." },
  { id:"gen_r279", subject:"general-agriculture", question:"PM-KISAN scheme provides financial assistance of _______ per year to farmer families:", options:["₹2,000", "₹6,000", "₹12,000", "₹4,000"], correct:1, explanation:"PM-KISAN (Pradhan Mantri Kisan Samman Nidhi) was launched in 2019. It provides ₹6,000 per year (in three installments of ₹2,000 each) as income support to all landholding farmer families." },
  { id:"gen_r280", subject:"general-agriculture", question:"The 'e-NAM' platform in India was launched for:", options:["Digital agricultural education and training programmes for rural youth", "Online savings and loan banking services for rural farmer communities", "National Agriculture Market — online trading of agricultural produce", "Digitization of land records and property registration for farmers"], correct:2, explanation:"e-NAM (National Agriculture Market) is an online trading portal launched in 2016 that connects APMC mandis across India. It enables farmers to sell produce online to buyers across the country, ensuring competitive prices." },
  { id:"gen_r281", subject:"general-agriculture", question:"Land reform refers to:", options:["Redistribution of land from large landowners to landless poor", "Construction of field channels, check dams, and irrigation infrastructure", "Physical levelling and grading of agricultural land for uniform irrigation", "Improvement of soil fertility through organic manures, lime, and micronutrient application"], correct:0, explanation:"Land reform includes measures like land ceiling (maximum land one can hold), abolition of zamindari (intermediary land tenure), redistribution of surplus land to landless poor, and tenancy reforms (security for tenant farmers)." },
  { id:"gen_r282", subject:"general-agriculture", question:"Food Corporation of India (FCI) was established in:", options:["1975", "1956", "1947", "1965"], correct:3, explanation:"Food Corporation of India (FCI) was established in 1965 to implement the government's food policy — procurement of food grains at MSP, maintenance of buffer stock, and distribution through the Public Distribution System (PDS)." },
  { id:"gen_r283", subject:"general-agriculture", question:"The main objective of the Public Distribution System (PDS) is:", options:["To generate revenue for the government through commodity taxation and trade margins", "To control domestic food price inflation by imposing statutory ceilings on traders", "To export surplus food grains to international markets and earn foreign exchange", "To provide food grains at subsidised prices to the poor"], correct:3, explanation:"The Public Distribution System (PDS) distributes food grains (rice, wheat, sugar, kerosene) at subsidised prices through Fair Price Shops (ration shops) to Below Poverty Line (BPL) and Antyodaya households." },
  { id:"gen_r284", subject:"general-agriculture", question:"Which body recommends the Minimum Support Price (MSP) to the central government?", options:["NITI Aayog in the agricultural economy", "Commission for Agricultural Costs and Prices (CACP)", "NABARD in rural economic context", "RBI for farm income analysis"], correct:1, explanation:"The Commission for Agricultural Costs and Prices (CACP) is a statutory body that recommends MSP for 22 mandated crops including Kharif, Rabi crops, and commercial crops. The final MSP is announced by the Cabinet Committee on Economic Affairs." },
  { id:"gen_r285", subject:"general-agriculture", question:"The 'National Agricultural Market' (e-NAM) portal was launched in:", options:["2016", "2012", "2014", "2018"], correct:0, explanation:"e-NAM (Electronic National Agriculture Market) was launched on 14 April 2016 by PM Modi. It is an online trading platform connecting 1,000+ APMC mandis across India for transparent price discovery. Farmers can sell their produce to buyers across the country through the portal." },
  { id:"gen_r286", subject:"general-agriculture", question:"The 'Pradhan Mantri Fasal Bima Yojana' (PMFBY) provides:", options:["Complete loan waiver for crop loans taken from cooperative banks and RRBs", "Crop insurance at low premium rates with government subsidy on insurance premium", "Free irrigation water through canal distribution during kharif and rabi seasons", "Free certified seeds of improved varieties distributed to all registered farmers"], correct:1, explanation:"PMFBY (Pradhan Mantri Fasal Bima Yojana) launched 2016: crop insurance at farmer premium of 2% for Kharif, 1.5% for Rabi, 5% for commercial/horticulture. Government pays the balance premium. Covers losses from natural calamities, pests, and diseases." },
  { id:"gen_r287", subject:"general-agriculture", question:"The 'terms of trade' for agriculture (Tott) refers to:", options:["Volume of agricultural commodities traded between local farming communities annually in the agricultural economy", "Bilateral trade agreements between countries governing agricultural tariffs and quotas in rural economic context", "The ratio of prices received by farmers (output prices) to prices paid by farmers (input prices)", "Government export-import policy determining duty structure on agricultural products for farm income analysis"], correct:2, explanation:"Terms of Trade (ToT) for agriculture = (Index of prices received by farmers) / (Index of prices paid by farmers) × 100. When ToT < 100, agriculture is in unfavourable terms of trade — farmers' purchasing power for inputs has declined. ToT improvement is a policy goal." },
  { id:"gen_r288", subject:"general-agriculture", question:"The APMC Act reforms allowing private markets and direct farmer-to-processor sales were promoted by:", options:["WTO Agreement on Agriculture requiring mandatory removal of state trading restrictions", "Model APMC Act (2003), Model Contract Farming Act (2018), and Farm Laws (2020 — later withdrawn)", "RBI monetary policy framework for agricultural credit and rural market development", "State governments acting independently based on their own agricultural marketing legislation"], correct:1, explanation:"Central government promoted APMC reforms through: Model APMC Act (2003) — for private markets, FDI in agri marketing; Model Contract Farming Act (2018); and three Farm Laws (2020 — withdrawn in 2021). States like Bihar abolished APMC entirely; most are reforming partially." },
  { id:"gen_r289", subject:"general-agriculture", question:"The 'Rashtriya Krishi Vikas Yojana' (RKVY) was launched in:", options:["2007–08", "2005–06", "2012–13", "2010–11"], correct:0, explanation:"RKVY (Rashtriya Krishi Vikas Yojana) was launched in 2007–08 to incentivize states to increase public investment in agriculture. States increasing agriculture budget share received additional central grants. It funds infrastructure, technology, and productivity improvement projects." },
  { id:"gen_r290", subject:"general-agriculture", question:"The 'Green Box' subsidies in WTO/GATT agriculture agreement are:", options:["Price support payments tied directly to production output with AMS reduction obligations", "Direct payments under production-limiting programmes subject to Blue Box conditions", "Non-trade distorting subsidies (R&D, extension, food security stockholding, disaster relief) — exempt from reduction", "Trade-distorting production subsidies that must be reduced under Amber Box commitments"], correct:2, explanation:"WTO Agreement on Agriculture (1995) categorizes subsidies: Green Box = non-distorting (R&D, extension, food security stocks, disaster relief, environmental programs) — no reduction obligation; Amber Box = trade-distorting (price support, input subsidies) — must be reduced; Blue Box = partially distorting." },
  { id:"gen_r291", subject:"general-agriculture", question:"PM-KISAN (Pradhan Mantri Kisan Samman Nidhi) provides an annual direct income support of:", options:["₹6,000/year (₹2,000 every 4 months)", "₹10,000/year in the agricultural economy", "₹4,000/year in rural economic context", "₹2,000/year for farm income analysis"], correct:0, explanation:"PM-KISAN (launched December 2018): provides ₹6,000 per year to all farmer families owning cultivable land (small, marginal, and large farmers), paid in three equal installments of ₹2,000 every four months directly into bank accounts through DBT." },
  { id:"gen_r292", subject:"general-agriculture", question:"The 'buffer stock' maintained by FCI (Food Corporation of India) is used for:", options:["Supplying subsidised grain to poultry industry and feedlot operators at reduced cost", "Production and distribution of certified foundation seeds through cooperative outlets", "Exporting surplus grain to international markets to earn foreign exchange revenue", "Maintaining food security (distribution through PDS) and market price stabilization"], correct:3, explanation:"FCI maintains buffer stocks (strategic reserves) of wheat and rice to: 1) Ensure food security through PDS distribution, 2) Stabilize market prices (release stock when prices rise, hold when prices fall), 3) Meet emergency food requirements. Buffer stock norms are set by the government." },
  { id:"gen_r293", subject:"general-agriculture", question:"The 'Agricultural Price Policy' in India aims to:", options:["Eliminate all government price support and allow purely market-determined agricultural prices", "Balance interests of producers (remunerative prices) and consumers (affordable food prices) through MSP and public distribution", "Provide all food items completely free to consumers by eliminating retail food prices", "Maximise farmers' income by maintaining consistently high food prices throughout the year"], correct:1, explanation:"India's agricultural price policy aims to: 1) Provide remunerative prices to farmers (MSP, FRP), 2) Maintain affordable food prices for consumers (PDS, buffer stocks), and 3) Control food inflation. CACP recommends MSP balancing cost of production and market conditions." },
  { id:"gen_r294", subject:"general-agriculture", question:"The 'land tenure' reforms after Indian independence included:", options:["Zamindari abolition, tenancy reforms, land ceiling laws, and consolidation of holdings to improve land distribution equity", "Increasing landlord power over tenant cultivators through codified regulatory framework in the agricultural economy", "Maintaining the existing zamindari system with minor administrative modifications only in rural economic context", "Encouraging large-scale absentee landlordism and corporate farming on consolidated estates for farm income analysis"], correct:0, explanation:"Post-independence land reforms: Zamindari abolition (1950s), Tenancy reforms (tenants got security of tenure and ownership rights), Land ceiling legislation (limiting individual holdings to 4–18 ha), Consolidation of fragmented holdings, and Bhoodan/Gramdan movements (voluntary land redistribution)." },
  { id:"gen_r295", subject:"general-agriculture", question:"The 'green marketing' of agricultural produce involves:", options:["Using only biodegradable packaging materials for all agricultural commodity distribution", "Selling certified produce exclusively through government-operated organic produce mandis", "Selling eco-friendly, sustainably produced, and certified organic products at premium prices", "Marketing exclusively green-coloured vegetables and leafy greens in specialty retail stores"], correct:2, explanation:"Green marketing (eco-marketing) involves producing and marketing agricultural products that are environmentally friendly: organic farming certification, fair trade labels, sustainable packaging, reduced carbon footprint, and marketing at price premiums to conscious consumers." },
  { id:"gen_r296", subject:"general-agriculture", question:"The 'NITI Aayog' replaced which body in 2015?", options:["Planning Commission of India", "NABARD", "CACP", "Finance Commission"], correct:0, explanation:"NITI Aayog (National Institution for Transforming India) replaced the Planning Commission from January 1, 2015. Unlike the Planning Commission (which allocated resources through Five-Year Plans), NITI Aayog serves as a policy think tank, advisory body, and platform for cooperative federalism." },
  { id:"gen_r297", subject:"general-agriculture", question:"The 'Bharat Krishi Vigyan Kendra' (KVK) network is maintained by:", options:["ICAR (Indian Council of Agricultural Research) — India has 731 KVKs at district level", "State Agriculture Universities through their field-level agricultural outreach programmes", "Ministry of Rural Development through District Rural Development Agencies at block level", "NABARD through its Rural Infrastructure Development Fund technical assistance programmes"], correct:0, explanation:"KVKs (Krishi Vigyan Kendras — Farm Science Centres) are district-level technology demonstration units funded by ICAR. India has 731 KVKs (one per district). They demonstrate improved technologies, train farmers, and test new varieties under local field conditions." },
  { id:"gen_r298", subject:"general-agriculture", question:"The 'Integrated Farming System' (IFS) approach integrates:", options:["Crop cultivation + livestock + fishery + horticulture on the same farm for better income and sustainability", "Coordination of central government agricultural schemes for comprehensive rural development in the agricultural economy", "Animal husbandry alone integrated with crop residue utilisation for fodder production in rural economic context", "Exclusive crop production optimised through soil-specific nutrient management protocols for farm income analysis"], correct:0, explanation:"Integrated Farming System combines crop (cereals, vegetables, oilseeds) + livestock (dairy, poultry, sheep/goat) + fishery (pond) + horticulture + apiculture on the same farm. Waste from one enterprise becomes input for another. Enhances income, employment, and environmental sustainability." },
  { id:"gen_r299", subject:"general-agriculture", question:"The 'Soil Health Card' scheme aims to:", options:["Provide soil test-based fertilizer recommendations to improve nutrient use efficiency and reduce over-fertilization", "Assess crop damage and yield loss for crop insurance settlement under PMFBY", "Map groundwater availability and aquifer depth across agricultural districts of India", "Provide health and accident insurance coverage to all registered farming households"], correct:0, explanation:"Soil Health Card (SHC) scheme (launched 2015): tests soil for 12 parameters (NPK, pH, EC, OC, S, Zn, Fe, Cu, Mn, B) every 3 years. Farmers receive card with soil status and fertilizer recommendations to optimize nutrient application and reduce cost." },
  { id:"gen_r300", subject:"general-agriculture", question:"The 'Andhra Pradesh Rythu Bharosa' scheme provides what benefit to farmers?", options:["Complete waiver of all agricultural debts including cooperative and bank loans outstanding", "Distribution of certified paddy and kharif crop seeds free of cost to all registered farmers", "Annual income support of ₹13,500 per farmer (in addition to PM-KISAN ₹6,000)", "Free electricity supply for agricultural irrigation pump sets up to 7.5 HP per farmer"], correct:2, explanation:"Andhra Pradesh Rythu Bharosa scheme provides ₹13,500/year direct income support per farmer family — including ₹7,500 as state share + ₹6,000 as PM-KISAN central share. Total: ₹13,500/year. Telangana has a similar scheme called 'Rythu Bandhu' (₹10,000/acre/year)." },
  { id:"gen_r301", subject:"general-agriculture", question:"The 'Telangana Rythu Bandhu' scheme provides:", options:["Investment support of ₹10,000 per acre per year to land-owning farmers (two instalments of ₹5,000)", "Free electricity for agricultural irrigation pumps up to 9 HP connected load", "Subsidised distribution of seeds, fertilizers, and pesticides to all registered farmers", "Comprehensive crop insurance coverage without any farmer premium payment required"], correct:0, explanation:"Rythu Bandhu (Telangana): Provides ₹10,000 per acre per year (₹5,000 before Kharif + ₹5,000 before Rabi) to all land-owning farmers. Launched 2018. It is unique — first investment support scheme tied to landholding rather than crop loss. Excludes tenant farmers (who don't own land)." },
  { id:"gen_r302", subject:"general-agriculture", question:"India's 'Doubling Farmers Income' target (DFI) was set for the year:", options:["2022", "2025", "2020", "2030"], correct:0, explanation:"PM Modi announced the goal to 'Double Farmers Income by 2022–23' (from 2015–16 base). The Dalwai Committee (2017) outlined strategies including: increasing crop productivity, better prices, and reducing post-harvest losses. Despite progress, full doubling was not achieved by 2022." },
  { id:"gen_r303", subject:"general-agriculture", question:"The 'WTO Agreement on Agriculture' (AoA) signed in 1995 aims at:", options:["Harmonising crop production methods and quality standards across all member nations", "Increasing agricultural import tariff barriers to protect domestic farmers from foreign competition", "Reducing domestic support subsidies, export subsidies, and import tariff barriers through multilateral negotiations", "Mandating all WTO member nations to adopt certified organic farming production standards"], correct:2, explanation:"WTO AoA (1995): bound by three pillars — 1) Market Access (reduce tariffs, increase tariff-rate quotas), 2) Domestic Support (reduce trade-distorting Amber Box subsidies, allow Green Box), 3) Export Competition (reduce export subsidies). Developing countries get special and differential treatment." },
  { id:"gen_r304", subject:"general-agriculture", question:"The 'Farmer Producer Organization' (FPO) concept helps small farmers by:", options:["Removing all agricultural middlemen through mandatory producer-to-consumer direct sales in the agricultural economy", "Providing free agricultural mechanization services financed entirely through government grants in rural economic context", "Enabling direct government procurement from each individual farmer household separately for farm income analysis", "Aggregating small farmers into collectively organized entities for better market power, input access, and credit"], correct:3, explanation:"FPOs (Farmer Producer Companies/Cooperatives): aggregate small/marginal farmers to achieve economies of scale in: bulk input purchasing (fertilizer, seeds), collective marketing (better prices, direct sales to processors), accessing finance, and adopting technology. Government targets 10,000 FPOs by 2024." },
  { id:"gen_r305", subject:"general-agriculture", question:"The 'Index of Prices Received by Farmers (IARF)' is computed to:", options:["Provide guidelines for fixing MSP based on current input costs and market price trends", "Determine actuarial risk for crop insurance premium fixation by insurance companies", "Compute annual growth rate of agricultural production across different crop seasons", "Track changes in farm gate prices received by farmers over time — used in terms of trade analysis"], correct:3, explanation:"IARF (Index of Prices Received by Farmers) tracks changes in farm gate prices of agricultural produce over time. It is compared with the Index of Prices Paid by Farmers (IAPF — input prices) to compute agricultural terms of trade (ToT = IARF/IAPF × 100)." },
  { id:"gen_r306", subject:"general-agriculture", question:"The 'Direct Benefit Transfer' (DBT) system for agricultural subsidies aims to:", options:["Channel all subsidies exclusively through fertilizer manufacturers and input supply chains", "Eliminate leakages by transferring subsidies directly to beneficiaries' bank accounts, bypassing intermediaries", "Increase total government fiscal expenditure on agricultural development and infrastructure", "Provide technology-based crop advisory services through mobile and digital platforms"], correct:1, explanation:"DBT (Direct Benefit Transfer) system: government transfers subsidies (PM-KISAN, fertilizer subsidy, PMFBY compensation, KCC interest subvention) directly to farmer bank accounts linked to Aadhaar. It eliminates leakages, reduces corruption, and ensures subsidy reaches intended beneficiaries." },
  { id:"gen_r307", subject:"general-agriculture", question:"The 'input subsidy' to farmers in India includes:", options:["Government paying only certified seed costs for approved varieties to registered farmers", "Subsidy on seeds, fertilizers, irrigation electricity, and credit interest — amounting to crores annually", "Government paying fertilizer costs only through direct benefit transfer to bank accounts", "Government paying all farming costs including labour, machinery, and harvesting charges"], correct:1, explanation:"Input subsidies to Indian farmers include: Fertilizer subsidy (highest — ~₹1.5 lakh crore/yr), Power subsidy (free/subsidized electricity for irrigation pumps — state governments), Seed subsidy (subsidized certified seeds), and Interest subvention on KCC loans (2–5% interest rate reduction)." },
  { id:"gen_r308", subject:"general-agriculture", question:"The 'agricultural value chain' concept includes:", options:["Primary crop production stage alone including land preparation and crop management in the agricultural economy", "Government procurement stage from FCI mandis at minimum support price operations only in rural economic context", "Retail distribution stage from APMC regulated markets to final consumer outlets only for farm income analysis", "All stages from production to consumption: inputs → production → harvest → storage → processing → marketing → retail → consumer"], correct:3, explanation:"Agricultural value chain: Input suppliers → Farmers (production) → Post-harvest handling → Storage → Processing → Wholesale trade → Retail → Consumer. Value is added at each stage. Value chain development reduces losses, improves income sharing, and connects farmers to markets." },
  { id:"gen_r309", subject:"general-agriculture", question:"The 'Gramin Bhandaran Yojana' (Rural Godown scheme) provides subsidy for:", options:["Construction of irrigation channels, check dams, and farm ponds for water conservation", "Rural electrification through solar microgrids for uninterrupted household power supply", "Building concrete village road networks linking farm areas to state highway junctions", "Construction of scientific storage structures (godowns/warehouses) in rural areas for farmers"], correct:3, explanation:"Gramin Bhandaran Yojana (Rural Storage Scheme): provides capital investment subsidy (25% for general category, 33.33% for SC/ST) for construction of rural godowns/warehouses to prevent post-harvest losses and help farmers sell when prices are favourable rather than in distress immediately after harvest." },
  { id:"gen_r310", subject:"general-agriculture", question:"The 'agri-export zones' (AEZ) in India were established for:", options:["Industrial development in peri-urban zones near major agricultural production belts", "Creating food security reserve zones to ensure year-round food availability in emergencies", "Developing clusters of commodity production with facilities for processing, packaging, and export of specific commodities", "Maintaining strategic import buffer stocks for essential agricultural goods in shortage"], correct:2, explanation:"Agri-Export Zones (AEZ): established from 2001 to develop integrated production clusters for specific commodities (mango/AP, basmati/Punjab, pepper/Kerala, grapes/Maharashtra) with: contract farming, cold chain infrastructure, certification, packaging, and export linkages." },
  { id:"gen_r311", subject:"general-agriculture", question:"The 'Minimum Support Price' (MSP) is fixed for how many crops in India?", options:["23 crops", "All agricultural crops", "14 crops", "5 crops"], correct:0, explanation:"MSP is fixed for 23 crops: 14 Kharif crops (paddy, jowar, bajra, maize, ragi, arhar, moong, urad, groundnut, sunflower, soybean, sesamum, nigerseed, cotton), 6 Rabi crops (wheat, barley, gram, masur, rapeseed/mustard, safflower), and 2 commercial crops (jute, copra) + sugarcane (FRP)." },
  { id:"gen_r312", subject:"general-agriculture", question:"The 'Green Revolution' period in India (1960s–70s) increased production through:", options:["Adopting natural farming techniques with improved traditional seed varieties and organic manures", "HYV seeds + chemical fertilizers + assured irrigation — primarily wheat in Punjab, Haryana, UP", "Expanding total cultivated area through reclamation of fallow and forest land only", "Redistributing agricultural land from large holdings equally to small and landless farmers"], correct:1, explanation:"Green Revolution (1960s–70s): HYV wheat (Sonalika, Kalyan Sona) + high fertilizer use + tube-well/canal irrigation in north Indian plains. Wheat production tripled. Later extended to rice (IR-8 variety). However, it was geographically limited (mainly Punjab, Haryana) and crop-limited (wheat, rice)." },
  { id:"gen_r313", subject:"general-agriculture", question:"India's share of agriculture in GDP has declined from ~55% (1950) to approximately:", options:["30% in 2023", "40% in 2023", "5% in 2023", "15–18% in 2023"], correct:3, explanation:"Agriculture's share in India's GDP declined from ~55% in 1950 to ~15–18% in 2022–23, reflecting structural transformation as industry and services grew faster. However, agriculture still employs ~44% of workforce — productivity gap between agriculture and other sectors remains." },
  { id:"gen_r314", subject:"general-agriculture", question:"Green Revolution in India was associated with:", options:["High-yielding varieties of wheat and rice", "Organic farming movement", "Forest conservation in rural economic context", "Environmental protection in the agricultural economy"], correct:0, explanation:"The Green Revolution (1960s–70s) transformed Indian agriculture through HYVs, irrigation, and chemical inputs." },
  { id:"gen_r315", subject:"general-agriculture", question:"M.S. Swaminathan is associated with:", options:["Pink Revolution", "White Revolution", "Green Revolution in India", "Blue Revolution"], correct:2, explanation:"M.S. Swaminathan is known as the father of the Green Revolution in India." },
  { id:"gen_r316", subject:"general-agriculture", question:"MSP (Minimum Support Price) is announced by:", options:["State government only in the agricultural economy", "RBI in rural economic context under standard field conditions", "NABARD for farm income analysis under standard field conditions", "Government of India (Cabinet Committee on Economic Affairs)"], correct:3, explanation:"MSP is announced by the Government of India (CCEA) based on recommendations of CACP." },
  { id:"gen_r317", subject:"general-agriculture", question:"CACP stands for:", options:["Cooperative Agriculture Credit Programme", "Commission for Agri-Credit and Procurement", "Central Agriculture Control Panel", "Commission for Agricultural Costs and Prices"], correct:3, explanation:"CACP (Commission for Agricultural Costs and Prices) recommends MSPs for major crops to the Government of India." },
  { id:"gen_r318", subject:"general-agriculture", question:"e-NAM (National Agriculture Market) is:", options:["An online trading platform for agricultural commodities", "A government farm scheme under standard field conditions", "A rural employment scheme under standard field conditions", "A crop insurance scheme under standard field conditions"], correct:0, explanation:"e-NAM is an online platform that integrates existing APMCs and enables farmers to trade electronically across India." },
  { id:"gen_r319", subject:"general-agriculture", question:"Pradhan Mantri Fasal Bima Yojana (PMFBY) is a scheme for:", options:["Crop loan waiver for farm income analysis", "Free seeds distribution in the agricultural economy", "Export subsidy in rural economic context", "Crop insurance to protect farmers against yield losses"], correct:3, explanation:"PMFBY provides comprehensive crop insurance coverage and financial support to farmers suffering crop loss." },
  { id:"gen_r320", subject:"general-agriculture", question:"FPO stands for:", options:["Farmer Producer Organization", "Food Processing Office", "Farm Product Organization", "Federal Price Order"], correct:0, explanation:"FPO (Farmer Producer Organization) is a collective of farmers registered under the Companies Act to improve bargaining power." },
  { id:"gen_r321", subject:"general-agriculture", question:"Procurement price in India refers to the price at which:", options:["Farmers buy inputs in the agricultural economy", "Consumers buy food in rural economic context", "Traders export grains for farm income analysis", "Government procures foodgrains from farmers through FCI"], correct:3, explanation:"Procurement price is the price at which the Food Corporation of India (FCI) buys foodgrains from farmers." },
  { id:"gen_r322", subject:"general-agriculture", question:"FCI stands for:", options:["Farm Credit Institution", "Farmer's Cooperative of India", "Food Corporation of India", "Federal Crop Insurance"], correct:2, explanation:"FCI (Food Corporation of India) is responsible for procurement, storage, and distribution of foodgrains in India." },
  { id:"gen_r323", subject:"general-agriculture", question:"Issue price is the price at which foodgrains are:", options:["Procured from farmers in rural economic context", "Exported in the agricultural economy", "Sold to consumers through PDS (Public Distribution System)", "Sold to exporters for farm income analysis"], correct:2, explanation:"Issue price is the subsidized price at which FCI supplies grains to consumers through ration shops (PDS)." },
  { id:"gen_r324", subject:"general-agriculture", question:"Buffer stock in India is maintained to:", options:["Feed livestock in the agricultural economy", "Stabilize prices and ensure food security during scarcity", "Export surplus in rural economic context", "Generate profit for farm income analysis"], correct:1, explanation:"Buffer stock is a strategic grain reserve maintained to moderate price fluctuations and ensure food availability." },
  { id:"gen_r325", subject:"general-agriculture", question:"WTO's Agreement on Agriculture (AoA) covers:", options:["Forest products only in the agricultural economy under standard field conditions", "Fisheries in rural economic context under standard field conditions", "Market access, domestic support, and export subsidies in agriculture", "Only domestic food safety for farm income analysis under standard field conditions"], correct:2, explanation:"WTO's AoA has three pillars: market access (tariff reduction), domestic support (subsidy limits), and export subsidies." },
  { id:"gen_r326", subject:"general-agriculture", question:"PM-KISAN scheme provides:", options:["₹6,000 per year income support in three installments to eligible farmers", "Free seeds to farmers in the agricultural economy under standard field conditions", "Soil testing services in rural economic context under standard field conditions", "Crop insurance premium subsidy for farm income analysis under standard field conditions"], correct:0, explanation:"PM-KISAN provides direct income support of ₹6,000/year in three installments to eligible small and marginal farmers." },
  { id:"gen_r327", subject:"general-agriculture", question:"Micro-finance refers to:", options:["Small financial services (credit, savings, insurance) to the rural poor", "Foreign direct investment in the agricultural economy under standard field conditions", "Large loans to corporations in rural economic context under standard field conditions", "Government grants for farm income analysis under standard field conditions"], correct:0, explanation:"Micro-finance provides small-scale financial services to low-income individuals who lack access to traditional banking." },
  { id:"gen_r328", subject:"general-agriculture", question:"Priority Sector Lending (PSL) in India requires banks to lend what percentage to agriculture?", options:["60%", "40%", "5%", "18%"], correct:3, explanation:"RBI mandates that commercial banks lend at least 18% of their Adjusted Net Bank Credit to agriculture as part of 40% PSL target." },
  { id:"gen_r329", subject:"general-agriculture", question:"MGNREGA provides rural households:", options:["Housing assistance in the agricultural economy in agriculture", "Education scholarships in rural economic context under field conditions", "Free food grains for farm income analysis", "At least 100 days of guaranteed wage employment per year"], correct:3, explanation:"MGNREGA (Mahatma Gandhi National Rural Employment Guarantee Act) guarantees 100 days of employment per year to rural households." },
  { id:"gen_r330", subject:"general-agriculture", question:"PMAY-G (Pradhan Mantri Awas Yojana - Gramin) aims to provide:", options:["Irrigation facilities", "Affordable housing to rural poor", "Agricultural loans", "Crop insurance"], correct:1, explanation:"PMAY-G aims to provide pucca houses to all homeless and those living in kutcha/dilapidated houses in rural areas." },
  { id:"gen_r331", subject:"general-agriculture", question:"Land reform in India primarily aimed to:", options:["Promote urban migration in the agricultural economy", "Increase industrial production in rural economic context", "Develop highways for farm income analysis", "Abolish zamindari and redistribute land to the landless"], correct:3, explanation:"Land reforms (1950s–70s) aimed to abolish intermediaries, redistribute land, and secure tenancy rights." },
  { id:"gen_r332", subject:"general-agriculture", question:"Value chain in agriculture refers to:", options:["Farm gate price only in the agricultural economy in agriculture under standard field conditions", "Export price for farm income analysis for crop production under standard field conditions", "Retail price only in rural economic context under field conditions under standard field conditions", "Entire sequence of activities from production to final consumption, adding value at each stage"], correct:3, explanation:"Agricultural value chain includes input supply, production, processing, marketing, and retail — value is added at each stage." },
  { id:"gen_r333", subject:"general-agriculture", question:"Doubling farmers' income by 2022 was a target set by:", options:["FAO in the agricultural economy", "ICAR in rural economic context", "World Bank for farm income analysis", "Government of India (announced in 2016)"], correct:3, explanation:"The Government of India announced the target to double farmers' income by 2022 (from 2015–16 base)." },
  { id:"gen_r334", subject:"general-agriculture", question:"Agribusiness includes:", options:["Import of food only in the agricultural economy under standard field conditions", "All commercial activities related to agricultural production, processing, and distribution", "Urban food retail for farm income analysis in irrigated crop production systems", "Farming only in rural economic context under tropical agricultural conditions"], correct:1, explanation:"Agribusiness encompasses input supply, farm production, processing, marketing, and distribution of agricultural products." },
  { id:"gen_r335", subject:"general-agriculture", question:"India's top agricultural export commodity (by value) is:", options:["Cotton under standard field conditions", "Rice (basmati and non-basmati)", "Wheat under standard field conditions", "Sugar under standard field conditions"], correct:1, explanation:"Rice (basmati and non-basmati) is India's top agricultural export by value." },
  { id:"gen_r336", subject:"general-agriculture", question:"APEDA stands for:", options:["Agricultural Price Enforcement and Distribution Authority", "Agro-Processing and Export Development Agency", "Agriculture Procurement and Economic Development Authority", "Agricultural Produce Export Development Authority"], correct:3, explanation:"APEDA (Agricultural and Processed Food Products Export Development Authority) promotes agricultural exports from India." },
  { id:"gen_r337", subject:"general-agriculture", question:"Terms of Trade (ToT) for agriculture compares:", options:["Domestic and international prices in the agricultural economy", "Input and output prices in manufacturing for farm income analysis", "Export and import volumes in rural economic context", "Prices received by farmers vs. prices paid by farmers for inputs"], correct:3, explanation:"Agricultural terms of trade = index of prices received (outputs) / index of prices paid (inputs) × 100." },
  { id:"gen_r338", subject:"general-agriculture", question:"Food processing industry is important because it:", options:["Adds value, reduces post-harvest losses, and creates employment", "Reduces crop diversity in the agricultural economy", "Reduces crop area in rural economic context", "Increases import dependence for farm income analysis"], correct:0, explanation:"Food processing adds value to raw produce, reduces post-harvest losses (40% in India), and generates rural employment." },
  { id:"gen_r339", subject:"general-agriculture", question:"Cold chain infrastructure is critical for:", options:["Machinery storage in the agricultural economy", "Perishable commodities (fruits, vegetables, dairy, fish)", "Fuel storage in rural economic context", "Cereal storage for farm income analysis"], correct:1, explanation:"Cold chain (refrigerated storage and transport) maintains quality of perishable agricultural produce throughout the value chain." },
  { id:"gen_r340", subject:"general-agriculture", question:"Natural capital in agriculture refers to:", options:["Financial capital in the agricultural economy under standard field conditions", "Natural resources (soil, water, biodiversity) that provide ecosystem services", "Farm machinery in rural economic context under standard field conditions", "Human resources for farm income analysis under standard field conditions"], correct:1, explanation:"Natural capital includes soil health, water resources, and biodiversity that underpin agricultural productivity." },
  { id:"gen_r341", subject:"general-agriculture", question:"Circular economy in agriculture emphasizes:", options:["Linear take-make-dispose model in the agricultural economy", "Maximum export orientation in rural economic context", "Monoculture farming for farm income analysis", "Reducing waste, recycling nutrients, and regenerating natural systems"], correct:3, explanation:"Circular economy principles applied to agriculture include composting, crop-livestock integration, and reducing waste." },
  { id:"gen_r342", subject:"general-agriculture", question:"Carbon credits in agriculture are earned by:", options:["Sequestering carbon through improved farming practices", "Burning crop residue under standard field conditions", "Using more groundwater under standard field conditions", "Increasing synthetic fertilizer use under standard field conditions"], correct:0, explanation:"Farmers can earn carbon credits by adopting practices that sequester atmospheric CO₂ in soil and biomass." },
  { id:"gen_r343", subject:"general-agriculture", question:"Climate-smart agriculture aims to:", options:["Achieve food security while adapting to climate change and reducing emissions", "Expand farm size indefinitely in the agricultural economy under standard field conditions", "Promote only traditional farming in rural economic context under standard field conditions", "Maximize chemical use for farm income analysis under standard field conditions"], correct:0, explanation:"Climate-smart agriculture pursues productivity, resilience to climate change, and reduction of greenhouse gas emissions." },
  { id:"gen_r344", subject:"general-agriculture", question:"The default file extension for MS Word 2016 documents is:", options:[".txt", ".doc", ".pdf", ".docx"], correct:3, explanation:"MS Word 2007 and later saves files in .docx format (XML-based). Older versions used .doc." },
  { id:"gen_r345", subject:"general-agriculture", question:"The default file extension for MS Excel 2016 is:", options:[".csv", ".xls", ".xlsx", ".xlm"], correct:2, explanation:"Excel 2007 and later uses .xlsx format (XML-based). Older versions used .xls." },
  { id:"gen_r346", subject:"general-agriculture", question:"MS PowerPoint is used for:", options:["Spreadsheet calculations", "Creating slide-based presentations", "Word processing", "Database management"], correct:1, explanation:"PowerPoint creates slide show presentations for lectures, meetings, and demonstrations." },
  { id:"gen_r347", subject:"general-agriculture", question:"The default file format of MS PowerPoint 2016 is:", options:[".pptx", ".pps", ".ppt", ".pot"], correct:0, explanation:"PowerPoint 2007 and later uses .pptx format. Older format is .ppt." },
  { id:"gen_r348", subject:"general-agriculture", question:"Slide Transition in PowerPoint refers to:", options:["The slide master in basic computer operations for crop production", "The animation of objects within a slide in agriculture", "The design template for general office use under field conditions", "The visual effect when moving from one slide to the next"], correct:3, explanation:"Slide transition is the animation/effect applied when switching between slides during a presentation." },
  { id:"gen_r349", subject:"general-agriculture", question:"Precision agriculture uses technology for:", options:["Variable rate application of inputs based on spatial variability in fields", "Reducing farm area for general office use in agriculture", "One-size-fits-all farming in basic computer operations under field conditions", "Manual observation only for data management only for crop production"], correct:0, explanation:"Precision agriculture uses GPS, sensors, and GIS to optimize input application according to field variability." },
  { id:"gen_r350", subject:"general-agriculture", question:"Soil moisture sensors in precision agriculture help in:", options:["Pest identification", "Seed selection", "Weather forecasting", "Optimizing irrigation scheduling"], correct:3, explanation:"Soil moisture sensors provide real-time data to trigger irrigation only when needed, saving water." },
  { id:"gen_r351", subject:"general-agriculture", question:"e-Crop advisory services in agriculture provide:", options:["Government job notifications for general office use in agriculture", "Free seeds in basic computer operations under field conditions", "Direct loans for data management only for crop production", "Real-time crop production advice, pest alerts, and weather updates to farmers"], correct:3, explanation:"e-Crop advisory services (via apps, SMS, internet) give farmers timely advice on crop management and market prices." },
  { id:"gen_r352", subject:"general-agriculture", question:"GIS in agriculture is used for:", options:["Word processing for general office use in agriculture", "Mapping soil variability, crop health, land use, and planning irrigation", "Playing games for data management only for crop production", "Accounting in basic computer operations under field conditions"], correct:1, explanation:"GIS (Geographic Information System) integrates spatial data for precision farming, land use planning, and resource management." },
  { id:"gen_r353", subject:"general-agriculture", question:"Cloud computing allows farmers to:", options:["Access data, apps, and services over the internet from anywhere", "Work without electricity for general office use", "Avoid using computers in basic computer operations", "Store data on local hard disks only"], correct:0, explanation:"Cloud computing provides internet-based storage, software, and services accessible from any device." },
  { id:"gen_r354", subject:"general-agriculture", question:"Digital India programme was launched in:", options:["2010", "2015", "2020", "2005"], correct:1, explanation:"Digital India was launched by the Government of India on 1 July 2015 to transform India into a digitally empowered society." },
  { id:"gen_r355", subject:"general-agriculture", question:"UPI (Unified Payments Interface) enables:", options:["Internet browsing for general office use", "Television broadcasting in basic computer operations", "Satellite communication for data management only", "Instant real-time bank transfers using mobile phones"], correct:3, explanation:"UPI is a payment system that facilitates instant inter-bank transactions via smartphones, developed by NPCI." },
  { id:"gen_r356", subject:"general-agriculture", question:"Aadhaar is a:", options:["Bank account for general office use", "Passport number in basic computer operations", "Voter ID for data management only", "12-digit unique biometric identity number issued to Indian residents"], correct:3, explanation:"Aadhaar is India's biometric UID (Unique Identification) 12-digit number issued by UIDAI." },
  { id:"gen_r357", subject:"general-agriculture", question:"PMGDISHA (Pradhan Mantri Gramin Digital Saksharta Abhiyan) aims to:", options:["Build rural roads for general office use", "Provide free computers to farmers", "Provide rural electricity in basic computer operations", "Make rural households digitally literate across India"], correct:3, explanation:"PMGDISHA aims to provide digital literacy skills to six crore rural households to enable them to use digital devices." },
  { id:"gen_r358", subject:"general-agriculture", question:"mKisan (Mobile for Agriculture) portal provides:", options:["Mobile games for general office use", "SMS-based crop advisory, weather alerts, and market prices to farmers", "Social media access in basic computer operations", "Mobile banking only for data management only"], correct:1, explanation:"mKisan portal delivers agricultural information directly to farmers' mobile phones via SMS in local languages." },
  { id:"gen_r359", subject:"general-agriculture", question:"IoT (Internet of Things) in agriculture refers to:", options:["Connected sensors, devices, and systems that collect and exchange data for smart farming", "Traditional farming methods in basic computer operations under field conditions", "Only internet browsing on farm for data management only for crop production", "International trade of crops for general office use in agriculture"], correct:0, explanation:"Agricultural IoT connects field sensors, weather stations, and drones to collect and analyze farm data in real time." },
  { id:"gen_r360", subject:"general-agriculture", question:"Artificial Intelligence (AI) in agriculture can help with:", options:["Removing insects by hand for general office use", "Manual irrigation in basic computer operations", "Crop disease detection, yield prediction, and automated machinery", "Manual weeding only for data management only"], correct:2, explanation:"AI enables image-based disease diagnosis, yield forecasting, robotic harvesting, and smart irrigation management." },
  { id:"gen_r361", subject:"general-agriculture", question:"Blockchain technology in agriculture can improve:", options:["Traceability and transparency in food supply chain and transactions", "Weather prediction in basic computer operations", "Water quality for general office use", "Soil fertility for data management only"], correct:0, explanation:"Blockchain provides an immutable record of transactions, enabling traceability from farm to consumer in food supply chains." },
  { id:"gen_r362", subject:"general-agriculture", question:"In: She is as tall as a sunflower plant, the figure of speech used is:", options:["Simile", "Metaphor", "Alliteration", "Hyperbole"], correct:0, explanation:"Simile compares two things using as...as or like. As tall as a sunflower plant is a simile." },
  { id:"gen_r363", subject:"general-agriculture", question:"Agriculture is the backbone of India — the word backbone is used as:", options:["Personification", "Alliteration", "Simile", "Metaphor"], correct:3, explanation:"Calling agriculture the backbone is a metaphor — a direct comparison without like or as, implying it is the chief support." },
  { id:"gen_r364", subject:"general-agriculture", question:"The figure of speech in Agriculture is the backbone of India is:", options:["Personification", "Alliteration", "Simile", "Metaphor"], correct:3, explanation:"Calling agriculture the backbone is a metaphor — a direct comparison without like or as, implying it is the chief support." },
  { id:"gen_r365", subject:"general-agriculture", question:"The figure of speech in: The wind whispered through the trees is:", options:["Personification", "Metaphor", "Alliteration", "Simile"], correct:0, explanation:"Personification gives human qualities to non-human things. The wind cannot literally whisper." },
  { id:"gen_r366", subject:"general-agriculture", question:"Which is an example of alliteration?", options:["Peter Piper picked a peck of pickled peppers.", "Rain, rain, go away.", "She sells vegetables at the market.", "The farmer works hard every day."], correct:0, explanation:"Alliteration is repetition of the same consonant sound at the start of nearby words. P sound repeats in Peter Piper picked." },
  { id:"gen_r367", subject:"general-agriculture", question:"The figure of speech The crop yield was a sea of gold is an example of:", options:["Personification", "Simile", "Metaphor", "Hyperbole"], correct:2, explanation:"A metaphor directly compares two things without using like or as. The crop is being called a sea of gold." },
  { id:"gen_r368", subject:"general-agriculture", question:"The Chipko movement in India was a protest against:", options:["Wildlife poaching in horticultural practices", "Forest fires for vegetable cultivation", "Commercial deforestation and tree felling in Himalayas", "Industrial pollution in orchard management"], correct:2, explanation:"Chipko movement (1973, Uttarakhand) — villagers hugged trees to prevent commercial felling. It was a landmark environmental movement." },
  { id:"gen_r369", subject:"general-agriculture", question:"The Diameter at Breast Height (DBH) is measured at:", options:["3.0 m from ground", "1.37 m from ground", "2.0 m from ground", "0.5 m from ground"], correct:1, explanation:"DBH (Diameter at Breast Height) is measured at 1.37 meters (4.5 feet) from the ground — standard in forest mensuration." },
  { id:"gen_r370", subject:"general-agriculture", question:"Joint Forest Management (JFM) in India aims to:", options:["Convert forests to agriculture in horticultural practices", "Complete protection without human use for vegetable cultivation", "Involve local communities in forest protection for shared benefits", "Commercial timber exploitation in orchard management"], correct:2, explanation:"JFM (1990) involves local communities through Village Forest Committees in forest protection and management, sharing the benefits." },
  { id:"gen_r371", subject:"general-agriculture", question:"India classifies its forests (Indian Forest Act 1927) into:", options:["Reserved forests only", "Commercial plantations only", "Reserved, protected, and unclassed forests", "Community and private forests only"], correct:2, explanation:"India classifies forests into Reserved Forests (strictly protected), Protected Forests, and Unclassed Forests under the Indian Forest Act 1927." },
  { id:"gen_r372", subject:"general-agriculture", question:"Match: Col A: 1-Carbon sequestration, 2-Soil conservation, 3-Water table, 4-Biodiversity. Functions of forests. Col B: P-roots bind soil, Q-stores CO2, R-habitat, S-roots recharge groundwater. Col C: i-climate mitigation, ii-erosion prevention, iii-animal habitats, iv-well water level", options:["1-S-iv, 2-R-iii, 3-P-ii, 4-Q-i", "1-Q-i, 2-P-ii, 3-S-iv, 4-R-iii", "1-P-ii, 2-Q-i, 3-R-iii, 4-S-iv", "1-R-iii, 2-S-iv, 3-Q-i, 4-P-ii"], correct:1, explanation:"Carbon sequestration (stores CO2=climate mitigation=i), Soil conservation (roots bind=erosion prevention=ii), Water table (roots recharge=well level=iv), Biodiversity (habitat=animals=iii)." },
  { id:"gen_r373", subject:"general-agriculture", question:"Forests classified as Reserved Forests in India are:", options:["Open for all uses in horticultural practices", "Strictly protected with all activities restricted unless permitted", "Used only for tribal people", "Available for commercial logging for vegetable cultivation"], correct:1, explanation:"Reserved Forests are the most strictly protected category under the Indian Forest Act 1927 — all activities are restricted unless specifically permitted." },
  { id:"gen_r374", subject:"general-agriculture", question:"The term agroforestry was coined by:", options:["FAO in 1960 in orchard management", "National Forest Policy 1952 in horticultural practices", "Indian Forest Act 1927 for vegetable cultivation", "ICRAF (International Centre for Research in Agroforestry) in the 1970s"], correct:3, explanation:"The term agroforestry was formally defined and popularized by ICRAF (now World Agroforestry Centre) in the 1970s." },
  { id:"gen_r375", subject:"general-agriculture", question:"ASSERTION-REASON: Assertion (A): The Chipko movement was initiated by women. Reason (R): Women in Uttarakhand hills were most affected by deforestation — losing fuelwood, fodder, and water sources.", options:["Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "Both A and R are true and R is the correct explanation of A", "A is false but R is true"], correct:2, explanation:"Chipko was largely women-led because women suffer most from deforestation (collecting fuelwood, water, fodder). R correctly explains A." },
  { id:"gen_r376", subject:"general-agriculture", question:"Match forest types to distribution: Col A: 1-Mangrove, 2-Alpine forest, 3-Dry thorn, 4-Tropical evergreen. Col B: P-Western Ghats, Q-Himalayas, R-Rajasthan, S-Sundarbans/coastal. Col C: i-above 3000m altitude, ii-rainfall >200cm, iii-saline tidal zone, iv-rainfall <75cm", options:["1-P-ii, 2-S-iii, 3-Q-i, 4-R-iv", "1-R-iv, 2-P-ii, 3-Q-i, 4-S-iii", "1-Q-i, 2-R-iv, 3-S-iii, 4-P-ii", "1-S-iii, 2-Q-i, 3-R-iv, 4-P-ii"], correct:3, explanation:"Mangrove (saline tidal=Sundarbans=iii), Alpine (>3000m=Himalayas=i), Dry thorn (<75cm=Rajasthan=iv), Tropical evergreen (>200cm=Western Ghats=ii)." },
  { id:"gen_r377", subject:"general-agriculture", question:"ASSERTION-REASON: Assertion (A): Joint Forest Management (JFM) was introduced in India in 1990. Reason (R): JFM was introduced to recognize that top-down forest management alone had failed to protect forests and communities needed to be partners.", options:["Both A and R are true but R is not the correct explanation of A", "A is false but R is true", "A is true but R is false", "Both A and R are true and R is the correct explanation of A"], correct:3, explanation:"JFM was introduced in 1990 recognizing the failure of centralized management. Community involvement through Village Forest Committees improved forest protection. R explains A." },
  { id:"gen_r378", subject:"general-agriculture", question:"Champion and Seth (1968) classified the forests of India into how many major forest types?", options:["10 major types", "5 major types", "16 major types", "8 major types"], correct:2, explanation:"Champion and Seth (1968) classified Indian forests into 16 major forest types and 221 minor types based on climate, soil and vegetation." },
  { id:"gen_r379", subject:"general-agriculture", question:"What percentage of India's total geographical area is covered by forests as per ISFR 2021?", options:["21.71%", "17.33%", "19.05%", "24.56%"], correct:0, explanation:"According to the India State of Forest Report (ISFR) 2021, forest and tree cover together constitute 24.62% but forest cover alone is 21.71% of India's geographical area." },
  { id:"gen_r380", subject:"general-agriculture", question:"Which type of forest is called 'Jungle' in the Champion & Seth classification?", options:["Tropical thorn", "Tropical moist deciduous", "Tropical dry deciduous", "Tropical wet evergreen"], correct:2, explanation:"In the Champion & Seth classification, tropical dry deciduous forests are commonly referred to as 'Jungle' type forests due to their open scrubby nature." },
  { id:"gen_r381", subject:"general-agriculture", question:"Alpine forests in India are found above the tree line at altitudes more than:", options:["3000 m", "3500 m", "4000 m", "2500 m"], correct:1, explanation:"Alpine forests/vegetation in India is found above 3500 m altitude, beyond the tree line. They consist mainly of dwarf shrubs, mosses and lichens." },
  { id:"gen_r382", subject:"general-agriculture", question:"The ICRAF definition of agroforestry includes which key components?", options:["Natural forest management for agriculture under standard field conditions", "Trees with crops only on arable land under standard field conditions", "Growing trees in blocks separate from farmland under standard field conditions", "Deliberate integration of trees/shrubs with crops and/or animals"], correct:3, explanation:"ICRAF (World Agroforestry Centre) defines agroforestry as a collective name for land-use systems involving deliberate integration of woody perennials with crops and/or animals on the same land." },
  { id:"gen_r383", subject:"general-agriculture", question:"Van Panchayats for community forest management were first established in which state?", options:["Madhya Pradesh", "Uttarakhand (formerly Uttar Pradesh hills)", "Himachal Pradesh", "Rajasthan in horticultural practices"], correct:1, explanation:"Van Panchayats were established in the hill districts of Uttarakhand (then UP) under the UP Panchayat Forest Rules 1931. They are among the earliest community forest management systems in India." },
  { id:"gen_r384", subject:"general-agriculture", question:"Joint Forest Management (JFM) in India was formally launched following the Government of India circular in:", options:["1980", "1988", "1996", "1990"], correct:3, explanation:"Joint Forest Management was formally launched through a Government of India circular in 1990, providing a framework for states to involve local communities in forest protection and management." },
  { id:"gen_r385", subject:"general-agriculture", question:"The Scheduled Tribes and Other Traditional Forest Dwellers (Recognition of Forest Rights) Act was passed in the year:", options:["2002", "2006", "2010", "1996"], correct:1, explanation:"The Forest Rights Act was passed in 2006 (came into effect 2008). It recognizes the rights of tribal and traditional forest-dwelling communities over forest land and resources." },
  { id:"gen_r386", subject:"general-agriculture", question:"Vana Samrakshana Samithis (VSS) are village-level committees established in Telangana for:", options:["Supervising social welfare schemes", "Managing water user associations", "Organizing agricultural extension programmes", "Joint forest management and protection of forests"], correct:3, explanation:"Vana Samrakshana Samithis (VSS) are village-level forest protection committees in Telangana (and AP) established under Joint Forest Management for community participation in forest protection." },
  { id:"gen_r387", subject:"general-agriculture", question:"Under the Forest Rights Act 2006, the minimum land that can be recognized as individual forest rights is up to:", options:["6 hectares", "4 hectares", "10 hectares", "2 hectares"], correct:1, explanation:"The Forest Rights Act 2006 recognizes individual forest rights for up to 4 hectares of forest land per nuclear family that has been cultivating it for at least three generations (75 years)." },
  { id:"gen_r388", subject:"general-agriculture", question:"Under Joint Forest Management, what share of forest produce does the Village Forest Committee (VFC) typically receive?", options:["25%", "75%", "40%", "50%"], correct:3, explanation:"Under most state JFM policies, the Village Forest Committee/Protection Committee receives 50% of the net proceeds from sale of forest produce from the protected area." },
  { id:"gen_r389", subject:"general-agriculture", question:"Which ministry administers the Forest Rights Act 2006 in India?", options:["Ministry of Tribal Affairs", "Ministry of Agriculture", "Ministry of Environment, Forest & Climate Change", "Ministry of Rural Development"], correct:0, explanation:"The Ministry of Tribal Affairs administers the Scheduled Tribes and Other Traditional Forest Dwellers (Recognition of Forest Rights) Act, 2006." },
  { id:"gen_r390", subject:"general-agriculture", question:"Community forest rights under the Forest Rights Act 2006 recognize tribal rights to:", options:["Sell timber commercially in horticultural practices", "Collect and use minor forest produce from community forests", "Individual ownership of forest land for vegetable cultivation", "Convert forest land to agricultural land"], correct:1, explanation:"Community forest rights recognize the rights of forest-dwelling communities to collect, use and dispose of minor forest produce, protect and manage community forest resources." },
  { id:"gen_r391", subject:"general-agriculture", question:"The Chipko movement in India was related to:", options:["Anti-poaching campaign in tiger reserves", "Protest against deforestation in the Himalayas", "Tribal forest rights movement", "Social forestry plantation drive"], correct:1, explanation:"The Chipko movement (1973) started in Uttarakhand where women hugged trees (chipko means hug) to prevent their felling by contractors, highlighting community forest rights and conservation." },
  { id:"gen_r392", subject:"general-agriculture", question:"Under the Forest Rights Act, the Gram Sabha has the power to:", options:["Only review but not approve forest rights claims", "Refer all claims to district collector for decision", "Approve commercial timber extraction", "Grant or reject claims for individual forest rights"], correct:3, explanation:"Under the Forest Rights Act 2006, the Gram Sabha has the power to initiate the process of determining individual and community forest rights and to receive, verify and approve/reject claims." },
  { id:"gen_r393", subject:"general-agriculture", question:"Brahmi (Bacopa monnieri) is mainly used in Ayurveda as:", options:["Antimalarial drug", "Anti-diabetic herb", "Diuretic and kidney tonic", "Brain tonic and memory enhancer"], correct:3, explanation:"Brahmi (Bacopa monnieri) is primarily used as a brain tonic, memory enhancer and anti-anxiety herb in Ayurveda. Its active principles are bacosides A and B." },
  { id:"gen_r394", subject:"general-agriculture", question:"Brahmi (Bacopa monnieri) naturally grows in:", options:["Arid desert zones", "Waterlogged and marshy areas", "High altitude alpine meadows", "Tropical dry deciduous forests"], correct:1, explanation:"Bacopa monnieri (Brahmi) is an aquatic/semi-aquatic herb that grows naturally in waterlogged, marshy and wetland areas. It is a creeping herb found throughout India near water bodies." },
  { id:"gen_r395", subject:"general-agriculture", question:"Isabgol (Psyllium) is obtained from which species?", options:["Cassia angustifolia", "Plantago ovata", "Plantago major", "Foeniculum vulgare"], correct:1, explanation:"Isabgol (Psyllium husk) is derived from the seeds of Plantago ovata. It is a bulk-forming laxative containing mucilage and is used in treating constipation, diarrhea and IBS." },
  { id:"gen_r396", subject:"general-agriculture", question:"Stevia is used as a natural sweetener because it contains compounds called:", options:["Saccharin analogues under standard field conditions", "Sucrose esters under standard field conditions", "Glucose and fructose mixtures", "Steviol glycosides (Stevioside, Rebaudioside)"], correct:3, explanation:"Stevia contains steviol glycosides (primarily stevioside and rebaudioside A), which are 200–300 times sweeter than sucrose but calorie-free, making it valuable for diabetics." },
  { id:"gen_r397", subject:"general-agriculture", question:"Isabgol (Plantago ovata) is mainly cultivated in which state of India?", options:["Karnataka", "Uttar Pradesh", "Andhra Pradesh", "Rajasthan and Gujarat"], correct:3, explanation:"Isabgol is mainly cultivated in Rajasthan (especially in Jalore and Barmer districts) and Gujarat. India is the world's largest producer and exporter of psyllium husk." },
  { id:"gen_r398", subject:"general-agriculture", question:"Stevia (Stevia rebaudiana) belongs to the plant family:", options:["Apiaceae", "Lamiaceae", "Asteraceae (Compositae)", "Solanaceae"], correct:2, explanation:"Stevia rebaudiana belongs to the family Asteraceae (Compositae). It is a native of Paraguay and Brazil, now cultivated in India, China and other countries." },
  { id:"gen_r399", subject:"general-agriculture", question:"Isabgol husk (Psyllium) is composed mainly of:", options:["Mucilage (soluble dietary fiber)", "Starch and proteins", "Fatty acids and oils", "Alkaloids and terpenes"], correct:0, explanation:"Isabgol husk contains about 70–85% mucilage (arabinoxylan, a soluble dietary fiber). This mucilage absorbs water and forms a gel, acting as a bulk-forming laxative." },
  { id:"gen_r400", subject:"general-agriculture", question:"The natural habitat of Stevia (Stevia rebaudiana) is:", options:["African savanna grasslands", "Amazon rainforests of Brazil", "Semi-arid highlands of Paraguay and Brazil", "Himalayan alpine meadows"], correct:2, explanation:"Stevia rebaudiana is native to the semi-arid highlands of northeastern Paraguay and southern Brazil. It is now cultivated worldwide as a natural zero-calorie sweetener." },
  { id:"gen_r401", subject:"general-agriculture", question:"Vetiver (Khus grass) used for essential oil extraction has the botanical name:", options:["Chrysopogon zizanioides", "Cymbopogon nardus", "Vetiveria zizanioides", "Both A and C"], correct:3, explanation:"Vetiver/Khus grass was formerly called Vetiveria zizanioides and is now classified as Chrysopogon zizanioides. Both names refer to the same species used for vetiver oil and erosion control." },
  { id:"gen_r402", subject:"general-agriculture", question:"Patchouli (Pogostemon cablin) essential oil is most commonly used in:", options:["Food flavoring and beverages", "Agricultural pesticide formulations in horticultural practices", "Perfumery as a fixative and in aromatherapy", "Pharmaceutical antibiotics for vegetable cultivation"], correct:2, explanation:"Patchouli oil (Pogostemon cablin) is widely used in perfumery as a fixative (slowing evaporation of other fragrances) and in aromatherapy, cosmetics and incense making." },
  { id:"gen_r403", subject:"general-agriculture", question:"Vetiver roots are used for making:", options:["Paper and cardboard only in horticultural practices", "Medicinal tinctures only for vegetable cultivation", "Khus mats, baskets and cooling screens (khas-khas tatties)", "Cosmetic hair oils only in orchard management"], correct:2, explanation:"Vetiver (Khus) roots are used for making cooling screens, mats, baskets and handicrafts. When wet they give a pleasant earthy fragrance, and the roots also yield vetiver essential oil." },
  { id:"gen_r404", subject:"general-agriculture", question:"The Wildlife Protection Act was enacted by the Government of India in:", options:["1986", "1960", "1972", "1980"], correct:2, explanation:"The Wildlife Protection Act was enacted in 1972 to provide legal protection to wildlife and their habitats in India. It has been amended several times, most significantly in 1991 and 2002." },
  { id:"gen_r405", subject:"general-agriculture", question:"The Convention on Biological Diversity (CBD) was signed at:", options:["Stockholm, 1972 in horticultural practices", "Rio de Janeiro, 1992 (Earth Summit)", "Kyoto, 1997 for vegetable cultivation", "Paris, 2015 in orchard management"], correct:1, explanation:"The Convention on Biological Diversity (CBD) was opened for signature at the Earth Summit in Rio de Janeiro in June 1992 and entered into force in December 1993." },
  { id:"gen_r406", subject:"general-agriculture", question:"India's Biological Diversity Act was enacted in:", options:["2006", "1992", "2000", "2002"], correct:3, explanation:"India's Biological Diversity Act was enacted in 2002 to give effect to the CBD. It provides for conservation of biological diversity, sustainable use and equitable sharing of benefits." },
  { id:"gen_r407", subject:"general-agriculture", question:"The Environment Protection Act in India was enacted in:", options:["1980", "1972", "1986", "1992"], correct:2, explanation:"The Environment (Protection) Act was enacted in 1986 following the Bhopal Gas Tragedy (1984). It empowers the Central Government to protect and improve environmental quality." },
  { id:"gen_r408", subject:"general-agriculture", question:"Which Schedule of the Wildlife Protection Act 1972 lists the most strictly protected animals?", options:["Schedule I", "Schedule II", "Schedule IV", "Schedule III"], correct:0, explanation:"Schedule I of the Wildlife Protection Act 1972 lists species afforded the highest protection. Hunting or trade of Schedule I animals (like Tiger, Elephant, Lion) is strictly prohibited with maximum penalties." },
  { id:"gen_r409", subject:"general-agriculture", question:"Project Tiger was launched in India in which year?", options:["1980", "1970", "1988", "1973"], correct:3, explanation:"Project Tiger was launched on April 1, 1973 by Prime Minister Indira Gandhi to protect tigers and their habitat. It started with 9 tiger reserves and now India has 53 tiger reserves." },
  { id:"gen_r410", subject:"general-agriculture", question:"The girth of a tree is measured at a height of _____ from the ground (Diameter at Breast Height):", options:["2.0 m", "0.5 m", "3.0 m", "1.37 m"], correct:3, explanation:"DBH (Diameter at Breast Height) is measured at 1.37 meters (4.5 feet) from the ground — the standard in forest mensuration." },
  { id:"gen_r411", subject:"general-agriculture", question:"The main objective of Joint Forest Management (JFM) in India is:", options:["Involving local communities in forest protection and management for shared benefits", "Converting forests to agriculture for vegetable cultivation in agriculture", "Complete protection without human use in horticultural practices", "Commercial timber exploitation in orchard management under field conditions"], correct:0, explanation:"JFM was introduced in 1990 to involve local communities (through Village Forest Committees) in forest protection and management, sharing the benefits." },
  { id:"gen_r412", subject:"general-agriculture", question:"Forest cover of India includes:", options:["Commercial plantations only", "Reserved, protected, and unclassed forests", "Agroforestry areas only", "Reserved forests only"], correct:1, explanation:"India classifies forests into Reserved Forests (strictly protected), Protected Forests, and Unclassed Forests based on the Indian Forest Act 1927." },
  { id:"gen_r413", subject:"general-agriculture", question:"Match: Col A: 1-Carbon sequestration, 2-Soil conservation, 3-Water table, 4-Biodiversity. Functions of forests. Col B: P-root systems bind soil, Q-stores carbon dioxide, R-habitat for plants and animals, S-tree roots recharge groundwater. Col C: i-climate change mitigation, ii-erosion prevention, iii-animal habitats, iv-well water level", options:["1-R-iii, 2-S-iv, 3-Q-i, 4-P-ii", "1-P-ii, 2-Q-i, 3-R-iii, 4-S-iv", "1-Q-i, 2-P-ii, 3-S-iv, 4-R-iii", "1-S-iv, 2-R-iii, 3-P-ii, 4-Q-i"], correct:2, explanation:"Carbon sequestration (stores CO2=climate mitigation=i), Soil conservation (roots bind soil=erosion prevention=ii), Water table (roots recharge=well level=iv), Biodiversity (habitat=animals=iii)." },
  { id:"gen_r414", subject:"general-agriculture", question:"The main pollinator of mango flowers is:", options:["Flies and midges (Diptera)", "Honey bee (Apis mellifera, A. cerana)", "Wind — cross-pollination through air movement", "Butterflies and moths (Lepidoptera)"], correct:0, explanation:"Mango flowers (panicles) have a strong unpleasant odour that primarily attracts flies, midges, and other Diptera insects as pollinators. Honey bees and other insects also visit, but flies and midges are the primary pollinators of mango." },
  { id:"gen_r415", subject:"general-agriculture", question:"The National Horticulture Mission (NHM) was launched in India in:", options:["2005–06", "1991–92", "2000–01", "2010–11"], correct:0, explanation:"National Horticulture Mission (NHM) was launched in 2005–06 (10th Five Year Plan) to promote holistic growth of the horticulture sector — covering fruits, vegetables, flowers, spices, mushrooms, plantation crops, and bamboo. It provides subsidies for area expansion, nurseries, cold storage, and market infrastructure." },
  { id:"gen_r416", subject:"general-agriculture", question:"The botanical name of Tuberose (Rajnigandha) is:", options:["Gladiolus grandiflorus", "Lilium longiflorum", "Polianthes tuberosa", "Rosa hybrida"], correct:2, explanation:"Tuberose — Polianthes tuberosa (family Agavaceae/Asparagaceae) — is one of the most fragrant flowers used for garlands, religious offerings, and perfume industry. It is propagated by bulbs. India is the 2nd largest producer. WB, TN, Karnataka, and AP are major producers." },
  { id:"gen_r417", subject:"general-agriculture", question:"The 'Pradhan Mantri Fasal Bima Yojana' (PMFBY) for horticulture crops is implemented through:", options:["Insurance companies with central-state government premium subsidy", "State-level agricultural cooperatives solely without government premium support", "National Horticulture Mission alone without any insurance company involvement", "Commercial banks acting as both insurers and premium subsidy providers"], correct:0, explanation:"PMFBY provides affordable crop insurance to farmers against losses from natural calamities, pests, and diseases. For horticulture crops, premium is 5% of sum insured (others 1.5–2%). Central and state governments share premium subsidy. Insurance companies settle claims based on CCE/area approach." },
  { id:"gen_r418", subject:"general-agriculture", question:"The 'Somatic hybridisation' technique in horticulture is also known as:", options:["Protoplast fusion", "Polyploidy breeding using colchicine to double chromosome number", "Mutation breeding using gamma radiation or chemical mutagens", "Conventional hybridisation through controlled hand-pollination"], correct:0, explanation:"Somatic hybridisation involves fusion of protoplasts (cells without cell walls) from two different plants, typically interspecific or intergeneric combinations difficult by conventional crossing. Used in Solanum species, citrus, and other horticultural crops for wide hybridisation." },
  { id:"gen_r419", subject:"general-agriculture", question:"The major aphid pest of citrus that also transmits tristeza virus is:", options:["Aphis gossypii (Cotton melon aphid) causing direct feeding damage", "Pentalonia nigronervosa (Banana aphid) transmitting BBTV", "Myzus persicae (Green peach aphid) transmitting CMV and other viruses", "Toxoptera citricida (Brown citrus aphid)"], correct:3, explanation:"Toxoptera citricida (Brown Citrus Aphid) is the most efficient vector of Citrus Tristeza Virus (CTV), which causes 'quick decline' and 'stem pitting' in citrus. Control: aphicide sprays, mild strain cross-protection, and resistant rootstocks." },
  { id:"gen_r420", subject:"general-agriculture", question:"The botanical name of Tamarind (Chintapandu) is:", options:["Emblica officinalis (Indian Gooseberry — Amla)", "Tamarindus indica", "Ziziphus mauritiana (Indian Jujube — Ber)", "Phyllanthus emblica (Amla — family Phyllanthaceae)"], correct:1, explanation:"Tamarind — Tamarindus indica — belongs to family Fabaceae (Caesalpinioideae). It is used as a souring agent in cooking (especially South Indian cuisine), in beverages, chutneys, and has medicinal properties. AP and Telangana have large tamarind resources." },
  { id:"gen_r421", subject:"general-agriculture", question:"Match spices: Col A: 1-Cardamom, 2-Black pepper, 3-Turmeric, 4-Ginger. Col B: P-Zingiber officinale, Q-Curcuma longa, R-Piper nigrum, S-Elettaria cardamomum. Col C: i-Piperaceae, ii-Zingiberaceae family member, iii-Zingiberaceae, iv-Zingiberaceae", options:["1-R-i, 2-S-iv, 3-P-ii, 4-Q-iii", "1-S-iv, 2-R-i, 3-Q-iii, 4-P-ii", "1-Q-iii, 2-P-ii, 3-S-iv, 4-R-i", "1-P-ii, 2-Q-iii, 3-R-i, 4-S-iv"], correct:1, explanation:"Cardamom (Elettaria=Zingiberaceae=iv), Black pepper (Piper=Piperaceae=i), Turmeric (Curcuma=Zingiberaceae=iii), Ginger (Zingiber=Zingiberaceae=ii)." },
  { id:"gen_r422", subject:"general-agriculture", question:"Match aromatic and medicinal plants: Col A: 1-Lemongrass, 2-Turmeric, 3-Ginger, 4-Aloe vera. Use: P-skin healing, Q-anti-inflammatory, R-digestive/spice, S-essential oil. Botanical: i-Zingiber officinale, ii-Curcuma longa, iii-Aloe barbadensis, iv-Cymbopogon citratus", options:["1-R-i, 2-S-iv, 3-Q-ii, 4-P-iii", "1-P-iii, 2-R-i, 3-S-iv, 4-Q-ii", "1-Q-ii, 2-P-iii, 3-R-i, 4-S-iv", "1-S-iv, 2-Q-ii, 3-R-i, 4-P-iii"], correct:3, explanation:"Lemongrass (essential oil=Cymbopogon=iv), Turmeric (anti-inflammatory=Curcuma=ii), Ginger (digestive/spice=Zingiber=i), Aloe vera (skin healing=Aloe barbadensis=iii)." },
  { id:"gen_r424", subject:"general-agriculture", question:"Citrus greening disease (Huanglongbing – HLB) is caused by:", options:["Xanthomonas campestris", "Citrus Tristeza Virus (CTV)", "Candidatus Liberibacter asiaticus (bacteria)", "Phytophthora parasitica (fungus)"], correct:2, explanation:"Citrus greening (Huanglongbing/HLB) is caused by the bacterium Candidatus Liberibacter asiaticus, transmitted by the psyllid insect Diaphorina citri. It is the most destructive citrus disease globally." },
  { id:"gen_r425", subject:"general-agriculture", question:"The spacing recommended for guava cultivation is:", options:["3×3 m (1111 plants/ha)", "6×6 m (277 plants/ha)", "1×1 m (10000 plants/ha)", "10×10 m (100 plants/ha)"], correct:1, explanation:"Standard spacing for guava is 6×6 m (277 plants/ha). High-density planting may use 3×3 m (1111 plants/ha) with dwarfing rootstocks or pruning management." },
  { id:"gen_r426", subject:"general-agriculture", question:"LCA-206 is a popular chilli variety released in which state?", options:["Andhra Pradesh", "Tamil Nadu", "Maharashtra", "Karnataka"], correct:0, explanation:"LCA-206 is a popular chilli variety released by Acharya N.G. Ranga Agricultural University (ANGRAU), Andhra Pradesh. It is widely grown for dry chilli production." },
  { id:"gen_r427", subject:"general-agriculture", question:"Guntur Sannam, a GI-tagged chilli variety, is grown in:", options:["Warangal, Telangana", "Guntur, Andhra Pradesh", "Raichur, Karnataka", "Mysuru, Karnataka"], correct:1, explanation:"Guntur Sannam chilli (S4 variety) is grown extensively in Guntur district of Andhra Pradesh. It is one of the world's most important commercial dry chilli varieties with high pungency and color." },
  { id:"gen_r428", subject:"general-agriculture", question:"The popular rose variety 'Gruss an Teplitz' is known as:", options:["A white cut flower rose", "A yellow climber rose variety", "The 'Crimson Glory' of Indian rose gardens", "A miniature rose variety"], correct:2, explanation:"Gruss an Teplitz is a heritage climbing rose known for its deep crimson-red, fragrant flowers. It is one of the oldest and most popular rose varieties in Indian gardens." },
  { id:"gen_r429", subject:"general-agriculture", question:"Agmark grading standard for agricultural produce in India is governed by:", options:["Agricultural Produce (Grading and Marking) Act 1937 (AGMARK)", "Food Safety and Standards Authority of India (FSSAI)", "Export Inspection Council (EIC) under standard field conditions", "Bureau of Indian Standards (BIS) under standard field conditions"], correct:0, explanation:"AGMARK grading standards are established under the Agricultural Produce (Grading and Marking) Act 1937. The AGMARK logo certifies that produce meets the prescribed quality standards." },
  { id:"gen_r430", subject:"general-agriculture", question:"The T&V (Training and Visit) system of agricultural extension was introduced in India in:", options:["1974–75 with World Bank financial support for extension reforms", "2000 under the ATMA extension reform framework", "1952 as part of the Community Development Programme by Government", "1991 under the economic liberalisation policy of India"], correct:0, explanation:"The Training and Visit (T&V) system was introduced in India in 1974–75 with World Bank support. Designed by Daniel Benor, it involves regular fortnightly training of Village Level Workers (VLWs) and scheduled bi-weekly farm visits." },
  { id:"gen_r431", subject:"general-agriculture", question:"Krishi Vigyan Kendra (KVK) was established primarily for:", options:["Regulating agricultural input markets at district level", "Front-line demonstration and vocational training at district level", "Producing certified seed of improved varieties for state distribution", "Conducting basic agricultural research at district level"], correct:1, explanation:"Krishi Vigyan Kendra (KVK — Farm Science Centre) is a district-level agricultural extension and training institute. It conducts frontline demonstrations, vocational training, on-farm testing, and disseminates technology to farmers." },
  { id:"gen_r432", subject:"general-agriculture", question:"Innovators and early adopters in the adoption process represent approximately what percentage of farmers?", options:["50% each representing majority of farming community", "2.5% and 13.5% respectively in Rogers' diffusion model", "5% and 5% respectively in Rogers' adoption categories", "20% and 40% respectively in the normal adoption curve"], correct:1, explanation:"Everett Rogers' Diffusion of Innovations categorises adopters as: Innovators (2.5%), Early Adopters (13.5%), Early Majority (34%), Late Majority (34%), and Laggards (16%). Innovators take risks; laggards are last to adopt." },
  { id:"gen_r433", subject:"general-agriculture", question:"MGNREGA (Mahatma Gandhi National Rural Employment Guarantee Act) guarantees employment of:", options:["365 days per year to all registered rural labour households", "90 days per year to all Below Poverty Line (BPL) rural households", "60 days per year to all rural households irrespective of demand", "100 days per year to rural households that demand unskilled manual work"], correct:3, explanation:"MGNREGA (2005) guarantees 100 days of wage employment per year to every rural household whose adult members are willing to do unskilled manual work. It focuses on creating durable assets and protecting livelihoods." },
  { id:"gen_r434", subject:"general-agriculture", question:"Pradhan Mantri Gram Sadak Yojana (PMGSY) is related to:", options:["Providing all-weather road connectivity to unconnected rural habitations", "Providing rural employment guarantee of 100 days to rural households", "Providing safe drinking water to all rural habitations in India", "Providing primary health care and nutrition services to rural women"], correct:0, explanation:"PMGSY (launched 2000) aims to provide all-weather road connectivity to unconnected rural habitations. Good roads improve access to markets, health facilities, and schools, enhancing the overall rural development." },
  { id:"gen_r435", subject:"general-agriculture", question:"The 73rd Constitutional Amendment (1992) is related to:", options:["Panchayati Raj as a three-tier rural local self-government system", "Agricultural land reforms and tenancy regulation in rural areas", "Urban local bodies and municipal governance in Indian cities", "Environmental protection and forest conservation laws in India"], correct:0, explanation:"The 73rd Constitutional Amendment (1992) gave constitutional status to Panchayati Raj Institutions (PRIs) — a three-tier system: Gram Panchayat (village), Panchayat Samiti (block), and Zila Parishad (district). Reservations for women (1/3) and SCs/STs were mandated." },
  { id:"gen_r436", subject:"general-agriculture", question:"Which scheme provides direct income support of ₹6000/year to farmers?", options:["MGNREGA", "PMGSY", "PMFBY", "PM-KISAN"], correct:3, explanation:"PM-KISAN (Pradhan Mantri Kisan Samman Nidhi, launched Feb 2019) provides ₹6,000 per year income support to all landholding farmer families in three equal installments of ₹2,000 each, directly into bank accounts." },
  { id:"gen_r437", subject:"general-agriculture", question:"The Kisan Call Centre in India provides:", options:["Crop insurance coverage for farmers through telephone registration", "Subsidised certified seeds and fertilizers through telephone ordering", "Free agricultural information and advice to farmers over toll-free telephone", "Short-term agricultural loans to small and marginal farmers"], correct:2, explanation:"Kisan Call Centres (KCC) established in 2004 provide free, expert agricultural advice to farmers over a toll-free helpline (1800-180-1551). Farmers can call in local language to get advice on crop production, pest management, weather, and government schemes." },
  { id:"gen_r438", subject:"general-agriculture", question:"The Community Development Programme (CDP) in India was launched in:", options:["1962", "1947", "1965", "1952"], correct:3, explanation:"The Community Development Programme (CDP) was launched on October 2, 1952 (Gandhi Jayanti). It was the first major programme for rural development in independent India, aiming at comprehensive village development through community participation." },
  { id:"gen_r439", subject:"general-agriculture", question:"The Kisan Call Centre (KCC) toll-free helpline number in India is:", options:["1800-120-1551", "1800-200-3000", "1800-180-1551", "1800-180-5555"], correct:2, explanation:"Kisan Call Centre (KCC) — toll-free no. 1800-180-1551 — was launched in 2004 by the Ministry of Agriculture. Farmers can call 24×7 to get advice on crop management, pest control, weather, market prices, and government schemes in their local language." },
  { id:"gen_r440", subject:"general-agriculture", question:"The first Krishi Vigyan Kendra (KVK) in India was established at:", options:["Tamil Nadu Agricultural University, Coimbatore in 1970 as a pilot", "Pondicherry in 1974 based on Mohan Singh Mehta Committee recommendation", "ICAR–IARI campus in New Delhi in 1966 as a demonstration centre", "Punjab Agricultural University, Ludhiana in 1972 during Green Revolution"], correct:1, explanation:"The first Krishi Vigyan Kendra (KVK) was established in 1974 at Pondicherry (now Puducherry) based on recommendations of the Mohan Singh Mehta Committee. Today there are over 700 KVKs across India under ICAR, SAUs, and NGOs." },
  { id:"gen_r441", subject:"general-agriculture", question:"The IADP (Intensive Agricultural District Programme) was launched in India in:", options:["1960–61 as a pilot in 7 districts with package of improved inputs", "1985 as a district-level food security programme in food-deficit states", "1975 as part of the Twenty-Point Programme of national development", "1952 as the Community Development Programme phase of rural development"], correct:0, explanation:"IADP was launched in 1960–61 in 7 pilot districts as India's first intensive agricultural development programme ('Package Programme'). It bundled improved inputs (seeds, fertilizers, credit, extension) to achieve rapid yield increases in selected districts." },
  { id:"gen_r442", subject:"general-agriculture", question:"The IAAP (Intensive Agricultural Area Programme) extended coverage from IADP by:", options:["Introducing private sector involvement in agricultural extension services", "Focusing exclusively on rice cultivation in coastal agricultural districts", "Extending the package approach from 7 to 114 districts covering crop-specific areas (1964)", "Restricting coverage to smaller pilot zones within existing IADP districts"], correct:2, explanation:"IAAP (1964) extended the intensive district-based package approach from 7 to 114 districts, covering all major crop areas across India. While IADP covered whole districts, IAAP targeted specific crop areas rather than all crops." },
  { id:"gen_r443", subject:"general-agriculture", question:"The Swaminathan National Commission on Farmers (2004–06) recommended:", options:["Operation Flood extension to all districts for dairy development", "Green Revolution 2.0 with focus on GM crops for food security", "Land ceiling acts be abolished for industrial farming consolidation", "Farmer-centric extension reforms ensuring MSP at 50% above cost of production"], correct:3, explanation:"The National Commission on Farmers chaired by Prof. M.S. Swaminathan (2004–06) recommended: strengthening extension services, farmer-centric approach, making farming economically viable, ensuring minimum support price at 50% above cost of production, and addressing farmer distress." },
  { id:"gen_r444", subject:"general-agriculture", question:"PM-KISAN scheme provides to eligible farmer families:", options:["₹6,000 per year in three equal instalments of ₹2,000 direct bank transfer", "Crop insurance coverage worth ₹6,000 per hectare per season", "Free drip irrigation equipment worth ₹6,000 per farm household", "Free high-yielding seeds worth ₹6,000 per season per farmer"], correct:0, explanation:"PM-KISAN (launched Feb 2019) provides ₹6,000/year in three equal instalments of ₹2,000 directly to farmer bank accounts via Direct Benefit Transfer (DBT). It supports small and marginal farmers for agricultural input purchases. Over 11 crore farmers are beneficiaries." },
  { id:"gen_r445", subject:"general-agriculture", question:"Agricultural Extension Education as a formal course was introduced in India modelled after:", options:["University of Illinois and US Land-Grant university model after 1950s", "IARI, New Delhi's agricultural research and extension programme", "Punjab Agricultural University, Ludhiana's extension division (1962)", "TNAU, Coimbatore's early agricultural training programmes in 1906"], correct:0, explanation:"Agricultural Extension Education as a formal course was introduced in Indian State Agricultural Universities (SAUs) modelled after the US Land-Grant University system. The First Education Commission (1949) and Indo-US cooperation led to establishing SAUs with extension as a core function." },
  { id:"gen_r446", subject:"general-agriculture", question:"The Village Level Worker (VLW) or 'Gram Sevak' was part of which extension system?", options:["ATMA district-level extension reform framework of 2000s", "National Horticulture Mission state-level extension programme", "Community Development Programme (CDP) block-based extension (1952)", "T&V (Training and Visit) fortnightly extension training system"], correct:2, explanation:"The Village Level Worker (VLW), also called Gram Sevak or Multi-Purpose Village Worker, was the field-level extension worker in the Community Development Programme (1952). Each VLW covered 5–10 villages and was responsible for all aspects of rural development." },
  { id:"gen_r447", subject:"general-agriculture", question:"Which of the following is NOT a function of Krishi Vigyan Kendra (KVK)?", options:["Issuing of land records and revenue certificates (Pahani)", "On-farm testing of new agricultural technologies in farmers' conditions", "Vocational training for farm youth in agri-enterprises", "Front Line Demonstrations of improved varieties and practices"], correct:2, explanation:"KVK functions include: on-farm testing, FLDs, vocational training, farm advisory services, and seed/input distribution. Issuing land records (Pahani) is NOT a KVK function — it is done by the Revenue Department (VRO/MRO)." },
  { id:"gen_r448", subject:"general-agriculture", question:"Farmer Producer Organisation (FPO) is promoted to provide farmers with:", options:["Collective marketing, input procurement, and value addition for better prices", "Direct government loans without collateral for individual crop production", "Free residential training at agricultural universities and research institutes", "Government land allocation through community farming arrangements"], correct:0, explanation:"FPOs/FPCs are collective enterprises owned and governed by farmers. Benefits: bulk input purchase at lower cost, collective marketing at better prices, access to institutional credit, value addition, and reduced exploitation by intermediaries. Government promotes 10,000 FPOs through SFAC and NABARD." },
  { id:"gen_r449", subject:"general-agriculture", question:"Pradhan Mantri Krishi Sinchai Yojana (PMKSY) involves extension workers in:", options:["Processing crop insurance claims under PMKSY for water-stressed crops", "Managing irrigation infrastructure construction under PMKSY as engineers", "Administering land reform and consolidation under PMKSY schemes", "Disseminating information on micro-irrigation adoption and training farmers in efficient water use"], correct:3, explanation:"PMKSY (launched 2015, motto: 'Har Khet Ko Paani, More Crop Per Drop') integrates irrigation schemes. Extension workers under ATMA/KVK train farmers in drip and sprinkler irrigation use, scheme benefits, and application procedures." },
  { id:"gen_r450", subject:"general-agriculture", question:"Farmer Field Schools were originally developed for IPM in rice in:", options:["India in 1975 as part of the Integrated Pest Management programme", "Mexico in 1960 during the Green Revolution for wheat pest management", "Indonesia in 1989 by FAO in response to pesticide overuse", "USA in 1985 for cotton integrated pest management training"], correct:2, explanation:"Farmer Field Schools were developed by FAO in Indonesia (1989) for IPM in rice as a response to pesticide overuse and pest resistance. Farmers meet weekly in their field, observe crop ecosystem, conduct group analysis, and make pest management decisions." },
  { id:"gen_r451", subject:"general-agriculture", question:"Rashtriya Krishi Vikas Yojana (RKVY) was launched in:", options:["2000–01 during Tenth Five Year Plan as agricultural credit scheme", "2015–16 as RKVY-RAFTAAR with start-up and FPO focus", "1991 as part of economic liberalisation and agricultural market reforms", "2007–08 during Eleventh Five Year Plan for 4% agricultural growth"], correct:3, explanation:"RKVY (Rashtriya Krishi Vikas Yojana) was launched in 2007–08 (11th Five Year Plan) to incentivise states to increase agriculture investment and achieve 4% annual growth. It funds infrastructure, mechanisation, extension, and allied activities. Now renamed RKVY-RAFTAAR." },
  { id:"gen_r452", subject:"general-agriculture", question:"The Government of India announces Minimum Support Price (MSP) for how many crops?", options:["All 600+ notified agricultural crops grown in India", "23 crops — 14 kharif, 6 rabi, and 2 commercial crops", "7 crops — only major food grains (wheat, rice, and millets)", "14 crops — kharif food crops and pulses only"], correct:1, explanation:"Government of India announces MSP for 23 crops: 14 kharif crops, 6 rabi crops, and 2 commercial crops (jute, copra). Extension workers inform farmers about MSP procurement opportunities." },
  { id:"gen_r453", subject:"general-agriculture", question:"The first agricultural university in India was established at:", options:["G.B. Pant University of Agriculture and Technology, Pantnagar (1960)", "IARI, New Delhi, established in 1905 as a central research institute", "TNAU, Coimbatore, established in 1906 as Madras Agriculture College", "Punjab Agricultural University, Ludhiana, established in 1962"], correct:0, explanation:"G.B. Pant University of Agriculture and Technology (GBPUAT), Pantnagar (established 1960) was India's first Agricultural University modelled after US Land-Grant Universities, with extension education as a core function. Established with USAID and Rockefeller Foundation support." },
  { id:"gen_r454", subject:"general-agriculture", question:"The 'Antyodaya' concept in extension means:", options:["Urban extension services for peri-urban and small-town farmers", "Targeting middle-class farmers who can demonstrate adoption to others", "Upliftment of the last and poorest person in the development process", "Export-oriented extension for producing commercial crops competitively"], correct:2, explanation:"Antyodaya (Gandhian concept) means 'rise of the last man' — ensuring that development benefits reach the poorest, most marginalised farmers first. Extension programmes under Antyodaya Gram Vikas Yojana target BPL households." },
  { id:"gen_r455", subject:"general-agriculture", question:"Kisan Credit Card (KCC) scheme promoted by NABARD provides farmers with:", options:["Short-term revolving credit for crop production and post-harvest needs", "Long-term infrastructure loans for farm mechanisation and land development", "Free agricultural land to landless labourers through government allocation", "Personal accident insurance coverage for farm workers and labourers"], correct:0, explanation:"KCC (Kisan Credit Card), launched 1998, provides farmers a revolving credit line for crop production expenses, post-harvest expenses, maintenance of farm assets, and consumption needs. Interest subvention (3%) on prompt repayment reduces effective interest to 4–7%." },
  { id:"gen_r456", subject:"general-agriculture", question:"IT-based crop insurance using satellite/drone imagery for Crop Cutting Experiments is called:", options:["e-NAM National Agriculture Market linked insurance verification", "DBT (Direct Benefit Transfer) system for insurance claim payment", "Smart Sampling using WINDS/FASAL/BhuVan satellite platforms", "e-KYC based farmer identity verification for insurance registration"], correct:2, explanation:"Under PMFBY, IT-based Smart Sampling uses satellite (RISAT, Resourcesat), drone imagery, and FASAL/BhuVan platforms for planning Crop Cutting Experiments (CCEs) efficiently. GPS-tagged CCE data is uploaded digitally to speed up yield estimation and insurance claim settlement." },
  { id:"gen_r457", subject:"general-agriculture", question:"MGNREGS relates to agricultural extension by:", options:["Providing guaranteed daily wage employment to extension workers only", "Funding farm ponds, check dams, and land development works for agriculture", "Training agricultural extension workers in farm management skills", "Selling agricultural inputs and machinery at subsidised rates to farmers"], correct:1, explanation:"MGNREGS funds land and water conservation works — farm ponds, check dams, land development, soil bunding, plantation — that are directly relevant to agricultural development. Extension workers link MGNREGS works to agricultural benefit for farmers." },
  { id:"gen_r458", subject:"general-agriculture", question:"The e-NAM (National Agriculture Market) portal links:", options:["Certified seed companies to farmers for direct online seed purchase", "Agricultural extension agents to researchers for technology information", "National commercial banks to rural farmers for agricultural credit", "APMCs across India to create a unified national online market for farm produce"], correct:3, explanation:"e-NAM (launched April 2016) is a pan-India online trading portal networking existing APMC mandis to create a unified national market. It enables farmers to get better prices through transparent bidding, reduces intermediaries, and allows buyers from any state to bid." },
  { id:"gen_r459", subject:"general-agriculture", question:"India's 'Agriculture 2.0' (Digital Agriculture Mission) vision emphasises:", options:["Stopping adoption of foreign agricultural technology and farm inputs", "Digital tools, AI-driven advisory, FPOs, and market-linked extension approach", "Reducing the number of agricultural extension workers and offices", "Returning exclusively to traditional organic farming without external inputs"], correct:1, explanation:"Agriculture 2.0 (Digital Agriculture Mission) envisions AI/ML, satellite data, IoT-based advisory, FPO strengthening, direct market linkage, and outcome-based digital extension services. It shifts from supply-driven to demand-driven extension using data analytics." },
  { id:"gen_r460", subject:"general-agriculture", question:"The number of community development projects started initially under the CDP of 1952 was:", options:["55", "25", "200", "100"], correct:0, explanation:"As part of the Community Development Programme started on 2nd October 1952, 55 community development projects were initially organized across the country." },
  { id:"gen_r461", subject:"general-agriculture", question:"Three-column matching: Match the development programme, its year, and its key feature:\nCol A: 1-CDP, 2-Panchayati Raj, 3-NES\nCol B: P-1952, Q-1953, R-1959\nCol C: i-Three tier local governance, ii-55 projects with 300 villages each, iii-National Extension Service", options:["1-P-iii, 2-R-ii, 3-Q-i", "1-R-i, 2-Q-iii, 3-P-ii", "1-P-ii, 2-R-i, 3-Q-iii", "1-Q-iii, 2-P-ii, 3-R-i"], correct:2, explanation:"CDP was started in 1952 (P) with 55 projects of 300 villages each (ii); Panchayati Raj was 1959 (R) with three-tier governance (i); NES was National Extension Service 1953 (Q-iii)." },
  { id:"gen_r462", subject:"general-agriculture", question:"Assertion (A): The Community Development Programme was launched on Gandhi Jayanti (2nd October) 1952.\nReason (R): Gandhi Jayanti was chosen because Gandhiji's Sevagram experiment in 1921 inspired the CDP model.", options:["Both A and R are true and R is the correct explanation of A", "A is true but R is false", "Both A and R are true but R is not the correct explanation of A", "A is false but R is true"], correct:1, explanation:"A is true - CDP was launched on 2nd October 1952 (Gandhi Jayanti). R is speculative/false - the official reason for choosing this date is to honor Gandhi's birthday and his legacy of rural development, but the CDP was based on the Etawah project model, not directly the Sevagram model." },
  { id:"gen_r463", subject:"general-agriculture", question:"Assertion (A): Extension education aims to bring desirable change in rural people's behavior regarding farm, home, and community.\nReason (R): KVKs (Krishi Vigyan Kendras) were established to implement extension education at district level.", options:["Both A and R are true and R is the correct explanation of A", "A is false but R is true", "A is true but R is false", "Both A and R are true but R is not the correct explanation of A"], correct:3, explanation:"Both A and R are true - extension education aims for behavioral change in farm/home/community (A), and KVKs implement extension at district level (R). But KVKs' existence does not explain the definition of extension education." },
  { id:"gen_r464", subject:"general-agriculture", question:"The number of farm families normally assigned to one Village Extension Worker (VEW) under T&V system is:", options:["600â€“800 farmers", "Above 5000 farmers", "50â€“100 farmers", "1000â€“2000 farmers"], correct:0, explanation:"Under the T&V system, each VEW (Village Extension Worker) is responsible for 600â€“800 farm families in approximately 8â€“10 villages, visiting them on a fixed fortnightly schedule." },
  { id:"gen_r465", subject:"general-agriculture", question:"In a result demonstration, the size of the demonstration plot is typically:", options:["5â€“10 ha", "0.2â€“0.4 ha (0.5â€“1 acre)", "10â€“20 ha", "0.01 ha (100 sq m)"], correct:1, explanation:"Result demonstrations are typically conducted on 0.2â€“0.4 ha (0.5â€“1 acre) plots under actual farm conditions to show realistic results that neighboring farmers can relate to." },
  { id:"gen_r466", subject:"general-agriculture", question:"The Kisan Call Centre (KCC â€“ 1800-180-1551) was established to:", options:["Provide free agricultural advisory to farmers through toll-free helpline", "Market agricultural produce online in extension education", "Recruit agricultural extension workers in rural development programmes", "Provide farm credit over phone under this extension approach"], correct:0, explanation:"Kisan Call Centre (KCC) â€“ toll-free number 1800-180-1551 â€“ provides free, immediate agricultural advisory in local languages to farmers who call with queries on crop production, disease, marketing etc." },
  { id:"gen_r467", subject:"general-agriculture", question:"Agri Clinics and Agri Business Centres scheme was started to promote:", options:["Only seed retail shops in rural development programmes under standard field conditions", "Only credit services to farmers under standard field conditions", "Government agricultural extension exclusively in extension education", "Agripreneurship among agriculture graduates for private extension services"], correct:3, explanation:"Agri Clinics and Agri Business Centres (ACABC) scheme promotes agripreneurship by supporting agriculture graduates to set up private extension clinics providing fee-based advisory and input services to farmers." },
  { id:"gen_r468", subject:"general-agriculture", question:"KVK (Krishi Vigyan Kendra) was established on the recommendations of which committee?", options:["Mohan Singh Mehta Committee / Swaminathan Committee", "Mehta Committee in rural development programmes", "Kelkar Committee under this extension approach", "Sivaraman Report in extension education"], correct:0, explanation:"Krishi Vigyan Kendra (KVK) was established based on the recommendations of the Mohan Singh Mehta committee report (1973) submitted to ICAR. The first KVK was established in Pondicherry in 1974." },
  { id:"gen_r469", subject:"general-agriculture", question:"The 5 stages of the Adoption-Diffusion Process (Rogers, 1962) are in the correct order:", options:["Awareness â†’ Trial â†’ Interest â†’ Evaluation â†’ Adoption", "Evaluation â†’ Awareness â†’ Interest â†’ Trial â†’ Adoption", "Interest â†’ Awareness â†’ Trial â†’ Evaluation â†’ Adoption", "Awareness â†’ Interest â†’ Evaluation â†’ Trial â†’ Adoption"], correct:3, explanation:"Rogers' adoption process: Awareness (first hears about it) â†’ Interest (wants to know more) â†’ Evaluation (mentally tries it) â†’ Trial (small-scale trial) â†’ Adoption (full-scale adoption)." },
  { id:"gen_r470", subject:"general-agriculture", question:"Innovators (the first to adopt new technology) constitute approximately what percentage of a community?", options:["34%", "13.5%", "2.5%", "16%"], correct:2, explanation:"Rogers' Diffusion of Innovation categorizes adopter categories: Innovators (2.5%), Early Adopters (13.5%), Early Majority (34%), Late Majority (34%) and Laggards (16%)." },
  { id:"gen_r471", subject:"general-agriculture", question:"The four mandates of a KVK (Krishi Vigyan Kendra) are:", options:["Research, Education, Extension, Credit", "On-farm testing, Frontline demonstrations, Training, Farm advisory", "Crop production, Animal husbandry, Post-harvest, Marketing", "Training farmers, Training extension workers, Seed production, Farm credit"], correct:1, explanation:"KVKs have four mandates: (1) On-farm testing of technologies, (2) Frontline demonstrations, (3) Capacity development (training of farmers and extension workers) and (4) Farm advisory." },
  { id:"gen_r472", subject:"general-agriculture", question:"The technology transfer chain from research to farmers is typically:", options:["Farmer â†’ KVK â†’ SAU â†’ ICAR (reversed)", "ICAR â†’ SAU â†’ KVK â†’ Extension Department â†’ Farmer", "International organizations â†’ Government â†’ Farmers in rural development programmes", "ICAR directly to farmers only in extension education"], correct:1, explanation:"The technology transfer chain: ICAR (national research) â†’ SAU (state research adaptation) â†’ KVK (location testing and FLD) â†’ State Extension Department (mass dissemination) â†’ Farmer (adoption)." },
  { id:"gen_r473", subject:"general-agriculture", question:"The number of KVKs currently operational in India is approximately:", options:["100", "1000", "731", "300"], correct:2, explanation:"As of 2023, there are 731 KVKs operational in India, one in each district (with some districts having two). They are the frontline technology transfer institutions of ICAR." },
  { id:"gen_r474", subject:"general-agriculture", question:"The 73rd Constitutional Amendment Act 1992 related to Panchayati Raj was enacted in which year?", options:["1992", "1996", "1990", "1994"], correct:0, explanation:"The 73rd Constitutional Amendment Act was passed in 1992 and came into force on April 24, 1993. It gave constitutional status to Panchayati Raj Institutions (PRIs) in India." },
  { id:"gen_r475", subject:"general-agriculture", question:"What minimum reservation for women is mandatory in Panchayati Raj Institutions under the 73rd Amendment?", options:["25%", "15%", "33% (one-third)", "50%"], correct:2, explanation:"The 73rd Amendment mandates not less than 1/3rd (33%) reservation for women in seats and offices of Sarpanch in PRIs. Many states have increased this to 50%." },
  { id:"gen_r476", subject:"general-agriculture", question:"The 11th Schedule of the Indian Constitution (added by 73rd Amendment) lists how many subjects to be assigned to Panchayats?", options:["18 subjects", "29 subjects", "66 subjects", "52 subjects"], correct:1, explanation:"The 11th Schedule lists 29 subjects including agriculture, land improvement, minor irrigation, animal husbandry, fisheries, social forestry, cottage industries, rural housing and primary education." },
  { id:"gen_r477", subject:"general-agriculture", question:"The duration of each Panchayati Raj Institution's term as mandated by the 73rd Amendment is:", options:["5 years", "2 years", "6 years", "3 years"], correct:0, explanation:"The 73rd Constitutional Amendment mandates a 5-year term for all Panchayati Raj Institutions. If dissolved earlier, fresh elections must be conducted within 6 months." },
  { id:"gen_r478", subject:"general-agriculture", question:"State Election Commission (SEC) as required by the 73rd Amendment supervises:", options:["Elections to Panchayati Raj Institutions and Urban Local Bodies", "State Assembly elections in extension education", "Cooperative society elections in rural development programmes", "Parliamentary elections in rural areas"], correct:0, explanation:"Each state's State Election Commission (SEC) is responsible for superintendence, direction and control of preparation of electoral rolls and conduct of elections to PRIs and Urban Local Bodies." },
  { id:"gen_r479", subject:"general-agriculture", question:"Which committee recommended the establishment of three-tier Panchayati Raj in India (1957)?", options:["Ashok Mehta Committee", "L.M. Singhvi Committee", "Kelkar Committee", "Balwantrai Mehta Committee"], correct:3, explanation:"The Balwantrai Mehta Committee (1957) recommended a three-tier democratic decentralization structure (Panchayati Raj) with Gram Panchayat, Panchayat Samiti and Zilla Parishad." },
  { id:"gen_r480", subject:"general-agriculture", question:"Under the 73rd Amendment, which constitutional body is responsible for recommending devolution of state revenue to PRIs?", options:["Inter-State Council", "CAG (Comptroller and Auditor General)", "Finance Commission (State Finance Commission", "Planning Commission"], correct:2, explanation:"Each state must constitute a State Finance Commission (SFC) every 5 years to review the financial position of PRIs and recommend principles for devolution of state taxes and grants to them." },
  { id:"gen_r481", subject:"general-agriculture", question:"The 73rd Amendment was significant for agriculture because it:", options:["Transferred 29 subjects including agriculture to Panchayats for local governance", "Nationalized all agricultural land in extension education under standard field conditions", "Established NABARD in rural development programmes under standard field conditions", "Abolished all agricultural taxes under this extension approach under standard field conditions"], correct:0, explanation:"The 73rd Amendment transferred 29 subjects (including agriculture, minor irrigation, animal husbandry, social forestry, poverty alleviation) to Panchayats, enabling local governance of rural development." },
  { id:"gen_r482", subject:"general-agriculture", question:"A Farmer Producer Organization (FPO) is:", options:["An NGO working for farmer welfare under this extension approach", "A bank providing farm credit in extension education", "A government department managing farmers in rural development programmes", "A producer organization where farmers are members and collectively do business"], correct:3, explanation:"An FPO (Farmer Producer Organization) is a legal entity formed by farmers where they are members/shareholders. FPOs collectively procure inputs, add value and sell produce for better bargaining power." },
  { id:"gen_r483", subject:"general-agriculture", question:"The Government of India scheme to form 10,000 new FPOs was launched in which year?", options:["2022", "2018", "2020", "2015"], correct:2, explanation:"The Central Government launched the '10,000 FPOs Scheme' in February 2020 with a budget of Rs. 6865 crore to form and promote 10,000 Farmer Producer Organizations across India by 2027-28." },
  { id:"gen_r484", subject:"general-agriculture", question:"KVK training programmes are classified as:", options:["Short-term (1â€“5 days), medium-term (2â€“4 weeks) and long-term (3â€“6 months) training", "Only on-farm demonstration training in rural development programmes under standard field conditions", "Only in-house training at KVK in extension education under standard field conditions", "Only online e-learning under this extension approach under standard field conditions"], correct:0, explanation:"KVK training programmes include short-term (1â€“5 days for awareness/skill), medium-term (2â€“4 weeks) and long-term (3â€“6 months vocational) training for farmers, farm women, youth and extension workers." },
  { id:"gen_r485", subject:"general-agriculture", question:"e-NAM (Electronic National Agriculture Market) is an online platform that:", options:["Manages electronic FPO registration under this extension approach for crop production", "Provides electronic land records in extension education in agriculture", "Provides e-learning to farmers in rural development programmes under field conditions", "Creates a unified national electronic market for agricultural commodities through APMC mandis"], correct:3, explanation:"e-NAM is an online trading platform integrating existing APMC mandis across states, creating a unified national market for agricultural commodities for transparent price discovery and better farmer income." },
  { id:"gen_r486", subject:"general-agriculture", question:"The minimum number of farmers required to form an FPO (Farmer Producer Company) is:", options:["5 farmers", "10 farmers", "500 farmers", "100 farmers (for most FPC registrations)"], correct:1, explanation:"Under the Companies Act, a Farmer Producer Company (FPC) requires a minimum of 10 individual farmer-members. NABARD and SFAC also set minimum member requirements for FPO support eligibility." },
  { id:"gen_r487", subject:"general-agriculture", question:"The Revised Guidelines on ATMA (2010) proposed that State Farmer Advisory Committees include:", options:["Only research scientists in extension education in agriculture", "Only government officials in rural development programmes", "Only large farmers and industry representatives under field conditions", "At least 60% farmer representation (including women and marginalized farmers)"], correct:3, explanation:"ATMA revised guidelines (2010) require Farmer Advisory Committees at district, block and village levels with at least 60% farmer representatives including women, small/marginal farmers and SHGs." },
  { id:"gen_r488", subject:"general-agriculture", question:"Community Managed Resource Centres (CMRCs) under NRLM are established to:", options:["Provide health services to SHG members under standard field conditions", "Provide banking services in extension education under standard field conditions", "Support SHG federations with agricultural extension and market linkages", "Manage community forests in rural development programmes"], correct:2, explanation:"CMRCs under NRLM provide agricultural extension, technology demonstrations, input supply and market linkages to SHG (Self Help Group) federations at cluster level, particularly to women farmers." },
  { id:"gen_r489", subject:"general-agriculture", question:"The main benefit of FPOs for small and marginal farmers is:", options:["Collective strength for bulk input purchase, processing and market access improving income", "Getting individual government subsidies in extension education under standard field conditions", "Access to higher land holdings in rural development programmes under standard field conditions", "Avoiding all government regulations under this extension approach under standard field conditions"], correct:0, explanation:"FPOs provide collective strength enabling small farmers to bulk-purchase inputs at lower cost, collectively process and grade produce, negotiate better prices with traders and access markets they cannot individually reach." },
  { id:"gen_r490", subject:"general-agriculture", question:"Under PM-KISAN scheme, farmers receive direct income support of:", options:["Rs. 5000 per year in one installment in extension education", "Rs. 2000 per year in 2 installments in rural development programmes", "Rs. 10,000 per year in 4 installments under this extension approach", "Rs. 6000 per year in 3 installments of Rs. 2000 each"], correct:3, explanation:"PM-KISAN (Pradhan Mantri Kisan Samman Nidhi) provides Rs. 6000 per year in 3 equal installments of Rs. 2000 each (every 4 months) directly into the bank accounts of farmer families." },
  { id:"gen_r491", subject:"general-agriculture", question:"Under PMFBY (Pradhan Mantri Fasal Bima Yojana), the premium paid by farmers for kharif crops is:", options:["2% of sum insured (or actuarial rate whichever is less)", "1% of sum insured in extension education", "5% of sum insured in rural development programmes", "10% of sum insured under this extension approach"], correct:0, explanation:"Under PMFBY, farmers pay maximum 2% of sum insured for kharif crops, 1.5% for rabi crops and 5% for commercial/horticultural crops. The balance is shared by central and state governments." },
  { id:"gen_r492", subject:"general-agriculture", question:"e-NAM (Electronic National Agriculture Market) is regulated by which body?", options:["RBI (Reserve Bank of India) in extension education", "SEBI (Securities and Exchange Board) in rural development programmes", "Ministry of Commerce under this extension approach", "SFAC (Small Farmers Agribusiness Consortium) under Ministry of Agriculture"], correct:3, explanation:"e-NAM is implemented by SFAC (Small Farmers Agribusiness Consortium) under the Ministry of Agriculture & Farmers Welfare. It creates a unified national online market across state APMC mandis." },
  { id:"gen_r493", subject:"general-agriculture", question:"Soil Health Card scheme provides farmers with a card showing:", options:["Soil nutrient status and fertilizer recommendations every 2 years", "Credit eligibility for farm loans in extension education", "Land ownership details and area in rural development programmes", "Crop insurance coverage details under this extension approach"], correct:0, explanation:"Soil Health Card provides farmers information about their soil's 12 nutrient parameters (NPK, S, Zn, Fe, Cu, Mn, B, pH, EC, OC) and crop-specific fertilizer recommendations, issued every 2 years." },
  { id:"gen_r494", subject:"general-agriculture", question:"The full form of PM-KISAN is:", options:["Pradhan Mantri Kisan Sanrakshan Nidhi", "Pradhan Mantri Kisan Sahayata Nidhi", "Pradhan Mantri Kisan Samman Nidhi", "Pradhan Mantri Kisan Suvidha Nidhi"], correct:2, explanation:"PM-KISAN stands for Pradhan Mantri Kisan Samman Nidhi. It was launched in February 2019 and covers all eligible landholder farmer families across the country." },
  { id:"gen_r495", subject:"general-agriculture", question:"Pradhan Mantri Krishi Sinchai Yojana (PMKSY) aims at:", options:["Providing free electricity to farmers in rural development programmes under field conditions", "Building reservoirs and dams only in extension education in agriculture", "'Har Khet Ko Pani' (water to every field) and 'More Crop Per Drop' (improving water use efficiency)", "Providing subsidies on irrigation pumps only under this extension approach for crop production"], correct:2, explanation:"PMKSY has twin objectives: 'Har Khet Ko Pani' (extending irrigation coverage) and 'More Crop Per Drop' (improving water use efficiency through drip and sprinkler irrigation). Budget outlay is Rs. 93,068 crore." },
  { id:"gen_r496", subject:"general-agriculture", question:"Under PMFBY, who assesses crop loss for insurance claims?", options:["Panchayat committee only in extension education in agriculture", "Individual farmers themselves in rural development programmes under field conditions", "Insurance company surveyors alone under this extension approach", "State Government through Crop Cutting Experiments (CCEs) and technology (satellite, drones)"], correct:3, explanation:"Crop loss assessment under PMFBY is done through Crop Cutting Experiments (CCEs) conducted by state governments, supplemented by remote sensing/satellite data, smartphone apps and drones." },
  { id:"gen_r497", subject:"general-agriculture", question:"The Kisan Credit Card (KCC) scheme was started in which year?", options:["2004", "2010", "1990", "1998"], correct:3, explanation:"Kisan Credit Card (KCC) was introduced in 1998 by NABARD to provide timely and adequate credit to farmers for agricultural needs in a flexible, simplified manner." },
  { id:"gen_r498", subject:"general-agriculture", question:"PM-KISAN is implemented by which ministry?", options:["Ministry of Finance", "Ministry of Food and Public Distribution", "Ministry of Agriculture and Farmers Welfare", "Ministry of Rural Development"], correct:2, explanation:"PM-KISAN is implemented by the Ministry of Agriculture and Farmers Welfare. State governments identify eligible beneficiaries and the Central Government directly transfers funds to their bank accounts." },
  { id:"gen_r499", subject:"general-agriculture", question:"RKVY (Rashtriya Krishi Vikas Yojana) was launched in which year to incentivize states for agricultural development?", options:["2003", "2012", "2007", "2016"], correct:2, explanation:"RKVY (Rashtriya Krishi Vikas Yojana) was launched in 2007 during the 11th Five Year Plan to achieve 4% agricultural growth by incentivizing states to increase public investment in agriculture." },
  { id:"gen_r500", subject:"general-agriculture", question:"PM-KISAN eligibility excludes which category of farmers?", options:["Small farmers with less than 2 ha land under this extension approach in the context of integrated farming systems", "Farmers with more than 5 ha land in extension education in agriculture based on conventional agronomic practices", "Tenant farmers in rural development programmes under field conditions during the critical growth period of crops", "Institutional landholders, constitutional post holders, income tax payers and retired employees with pension above Rs. 10,000/month"], correct:3, explanation:"PM-KISAN excludes: institutional landholders; current/former holders of constitutional posts; serving/retired officers; income-taxpayers; professionals (doctors, engineers, lawyers); and pensioners receiving above Rs. 10,000/month." },
  { id:"gen_r501", subject:"general-agriculture", question:"The nodal agency for implementing Soil Health Card scheme is:", options:["State Cooperative Banks in extension education", "ICAR in rural development programmes in agriculture", "Department of Agriculture & Farmers Welfare (through state governments)", "NABARD under this extension approach under field conditions"], correct:2, explanation:"Soil Health Card Scheme is implemented by the Department of Agriculture & Farmers Welfare through state governments, which establish soil testing laboratories, conduct testing and issue cards to farmers." },
  { id:"gen_r503", subject:"general-agriculture", question:"NRLM (National Rural Livelihoods Mission) aims at:", options:["Providing urban employment to rural migrants in extension education in agriculture", "Mobilizing poor rural households into SHGs and connecting them to credit, skills and markets", "Building rural road infrastructure in rural development programmes under field conditions", "Establishing rural hospitals under this extension approach for crop production"], correct:1, explanation:"NRLM (Aajeevika/Deendayal Antyodaya Yojana-NRLM) organizes poor rural households (especially women) into SHGs, SHG federations and connects them to credit, skills, livelihoods and social entitlements." },
  { id:"gen_r504", subject:"general-agriculture", question:"The cooperative movement in India got its first legal framework through:", options:["National Bank Act 1982", "RBI Act 1934", "Cooperative Societies Act 1912", "Cooperative Societies Act 1904"], correct:3, explanation:"The Cooperative Credit Societies Act 1904 was India's first legislation for cooperatives, leading to the formation of agricultural credit cooperatives. The Cooperative Societies Act 1912 gave further impetus." },
  { id:"gen_r505", subject:"general-agriculture", question:"Regional Rural Banks (RRBs) were established in India in:", options:["1990", "1982", "1959", "1975"], correct:3, explanation:"RRBs were established in October 1975 (first RRB: Prathama Bank in Moradabad, UP) under RRB Act 1976, combining the strengths of cooperative societies and commercial banks to serve rural areas." },
  { id:"gen_r506", subject:"general-agriculture", question:"The SHG-Bank Linkage Programme in India was pioneered by:", options:["NABARD from 1992 as a pilot programme", "Ministry of Finance directly", "Commercial banks voluntarily in extension education", "RBI alone in rural development programmes"], correct:0, explanation:"NABARD launched the SHG-Bank Linkage Programme as a pilot in 1992, which became the world's largest microfinance programme, linking SHGs directly to formal banking for savings and credit." },
  { id:"gen_r507", subject:"general-agriculture", question:"Deendayal Antyodaya Yojana-National Rural Livelihoods Mission (DAY-NRLM) aims to reach how many rural poor households?", options:["15 crore households", "10 crore households", "7 crore households", "1 crore households"], correct:2, explanation:"DAY-NRLM aims to reach 7 crore poor rural households across India by mobilizing them into 62.5 lakh SHGs and federating them into village-level organizations for sustainable livelihoods." },
  { id:"gen_r508", subject:"general-agriculture", question:"Vaidyanathan Committee report (2004) recommended revival of which cooperative credit institution?", options:["Commercial banks under standard field conditions", "RRBs only as recommended by ICAR guidelines", "NABARD itself under standard field conditions", "Primary Agricultural Cooperative Societies (PACS)"], correct:3, explanation:"The Vaidyanathan Task Force/Committee on revival of rural cooperative credit structure (2004) recommended revival of PACS, DCCBs and SCBs with government financial support for recapitalization and reforms." },
  { id:"gen_r509", subject:"general-agriculture", question:"Pradhan Mantri Micro Food Processing Enterprises (PM-FME) scheme supports:", options:["Individual micro food enterprises and FPOs for formalizing and upgrading informal food processing", "Only export food processors in extension education in agriculture", "Government food processing corporations in rural development programmes under field conditions", "Large food processing factories only under this extension approach for crop production"], correct:0, explanation:"PM-FME scheme supports micro food processing enterprises and FPOs with 35% grant for plant and machinery for formalizing, upgrading technology, marketing support and capacity building." },
  { id:"gen_r510", subject:"general-agriculture", question:"MGNREGS guarantees how many days of wage employment per year to rural households?", options:["100 days per year (additional 50 for drought-affected areas)", "200 days per year in extension education", "50 days per year in rural development programmes", "150 days per year under this extension approach"], correct:0, explanation:"MGNREGS (Mahatma Gandhi National Rural Employment Guarantee Scheme) guarantees 100 days of wage employment per year per rural household. In drought-affected areas, additional 50 days can be provided." },
  { id:"gen_r511", subject:"general-agriculture", question:"The current wage rate under MGNREGS (approximately 2023-24) is approximately:", options:["Rs. 500/day under standard field conditions", "Rs. 221â€“350/day (varies by state)", "Rs. 800/day under standard field conditions", "Rs. 100/day under standard field conditions"], correct:1, explanation:"MGNREGS wage rates vary by state (indexed to state minimum wage for agricultural labor). The national average is approximately Rs. 221â€“350/day with different rates for different states." },
  { id:"gen_r512", subject:"general-agriculture", question:"PMGSY (Pradhan Mantri Gram Sadak Yojana) aims at:", options:["Building rural health centers in extension education under standard field conditions", "Providing electricity to rural areas in rural development programmes", "Connecting unconnected habitations above population threshold with all-weather roads", "Providing piped water to rural areas in irrigated crop production systems"], correct:2, explanation:"PMGSY provides all-weather road connectivity to unconnected habitations with population above 500 (in plains) and 250 (in hills/tribal areas) through construction of new rural roads." },
  { id:"gen_r513", subject:"general-agriculture", question:"National Horticulture Mission (NHM) was launched in India in:", options:["2009", "2014", "2001", "2005"], correct:3, explanation:"National Horticulture Mission (NHM) was launched in 2005-06 during the 10th Five Year Plan to promote holistic development of horticulture sector including fruits, vegetables, flowers, spices and medicinal plants." },
  { id:"gen_r514", subject:"general-agriculture", question:"SDG (Sustainable Development Goals) were adopted by the United Nations in which year?", options:["2015", "2010", "2018", "2012"], correct:0, explanation:"The 17 Sustainable Development Goals (SDGs) were adopted by all UN member states in September 2015 as part of the 2030 Agenda for Sustainable Development, replacing the Millennium Development Goals." },
  { id:"gen_r515", subject:"general-agriculture", question:"MGNREGS was enacted under which Act of Parliament?", options:["Rural Employment Guarantee Act 2003 under standard field conditions", "Mahatma Gandhi National Rural Employment Guarantee Act 2005", "National Wage Employment Act 2006 under standard field conditions", "National Rural Employment Act 2004 under standard field conditions"], correct:1, explanation:"MGNREGS is implemented under the Mahatma Gandhi National Rural Employment Guarantee Act 2005, which gives rural households a legal right to demand 100 days of wage employment." },
  { id:"gen_r516", subject:"general-agriculture", question:"The Green Revolution in India was mainly associated with which crop and state in the 1960s?", options:["Wheat in Punjab and rice in West Bengal", "Pulses in Rajasthan in rural development programmes", "Cotton in Gujarat in extension education", "Sorghum in Andhra Pradesh under this extension approach"], correct:0, explanation:"The Green Revolution (late 1960s) was associated with HYV wheat (Sonora-64, Lerma Roja) in Punjab, Haryana and Western UP, and HYV rice (IR-8) initially. Norman Borlaug and M.S. Swaminathan are credited." },
  { id:"gen_r517", subject:"general-agriculture", question:"RKVY-RAFTAAR (Remunerative Approaches for Agriculture and Allied sector Rejuvenation) focuses on:", options:["Government seed production only in extension education under standard field conditions", "Only crop insurance programmes in rural development programmes under standard field conditions", "Agripreneurship promotion, farm-to-market value chain and innovation in agri-startups", "Infrastructure construction only under this extension approach under standard field conditions"], correct:2, explanation:"RKVY-RAFTAAR focuses on making farming remunerative by promoting agripreneurship, value addition, farmer-market linkages, innovation, agri-startups and reducing post-harvest losses." },
  { id:"gen_r518", subject:"general-agriculture", question:"The UN's Sustainable Development Goal (SDG) 2 'Zero Hunger' aims to:", options:["Eliminate all food imports and exports under this extension approach under standard field conditions", "Reduce food prices to zero in extension education as recommended by ICAR guidelines", "Provide free food to all people globally in rural development programmes under standard field conditions", "End hunger, achieve food security, improved nutrition and promote sustainable agriculture by 2030"], correct:3, explanation:"SDG 2 (Zero Hunger) aims to end hunger, achieve food security, improve nutrition and promote sustainable agriculture by 2030 through increased agricultural productivity, sustainable food systems and equitable access." },
  { id:"gen_r519", subject:"general-agriculture", question:"Community Development Programme (CDP) in India was launched in:", options:["1952", "1960", "1947", "1965"], correct:0, explanation:"Community Development Programme (CDP) was launched on October 2, 1952 (Gandhi Jayanti) to bring about integrated rural development through local self-government, community participation and administrative support." },
  { id:"gen_r520", subject:"general-agriculture", question:"National Food Security Act (NFSA) 2013 entitles which beneficiaries to subsidized food grains?", options:["All Indian citizens without exception in extension education in agriculture under standard field conditions", "Priority Households (5 kg/person/month at Rs. 1â€“3) and Antyodaya Anna Yojana households (35 kg/family/month)", "Only urban poor families in rural development programmes under field conditions under standard field conditions", "Only BPL families in rural areas under this extension approach under standard field conditions"], correct:1, explanation:"NFSA 2013 entitles Priority Household (PHH) members to 5 kg/person/month at Rs. 3/2/1 per kg (rice/wheat/coarse grains) and AAY households (poorest) to 35 kg/family/month." },
  { id:"gen_r521", subject:"general-agriculture", question:"The 'Double the Farmers' Income (DFI)' initiative by Government of India aims to double farmers' income by:", options:["2022", "2025", "2030", "2020"], correct:0, explanation:"The government announced the target of doubling farmers' real income by 2022 (Kisan Samridhi in the 75th Independence year). The Dalwai Committee was constituted to develop a strategy for DFI." },
  { id:"gen_r522", subject:"general-agriculture", question:"Three-column matching: Match the pre-independence rural development project, its year, and its founder/location:\nCol A: 1-Srinikethan, 2-Sevagram, 3-Gurugram experiment\nCol B: P-1914, Q-1921, R-1920s\nCol C: i-F L B Brown/Punjab, ii-Rabindranath Tagore/West Bengal, iii-Gandhiji/Maharashtra", options:["1-P-ii, 2-Q-iii, 3-R-i", "1-P-iii, 2-Q-i, 3-R-ii", "1-R-i, 2-P-ii, 3-Q-iii", "1-Q-ii, 2-P-iii, 3-R-i"], correct:0, explanation:"Srinikethan (P-1914, ii-Tagore/West Bengal); Sevagram (Q-1921, iii-Gandhiji/Maharashtra); Gurugram experiment (R-1920s, i-F L B Brown/Punjab)." },
  { id:"gen_r523", subject:"general-agriculture", question:"The Community Development Programme (CDP) was launched in India on:", options:["26th January 1950", "2nd October 1952", "15th August 1947", "2nd October 1959"], correct:1, explanation:"The Community Development Programme was started in India on 2nd October 1952 (Gandhi Jayanti), with 55 community development projects organized across the country." },
  { id:"gen_r524", subject:"general-agriculture", question:"Each community development project under CDP (1952) consisted of approximately:", options:["100 villages, 50,000 population, 50,000 acres of land", "200 villages, 1 lakh population, 1,00,000 acres of land", "300 villages, 2 lakh population, 1,50,000 acres of agricultural land", "500 villages, 5 lakh population, 3,00,000 acres of land"], correct:2, explanation:"Each CDP project consisted of 300 villages, 2 lakh population and 1,50,000 acres of agricultural land, divided into 3 blocks of 100 villages each." },
];
